/// Calculates pop out position when record is ejected from a jukebox.
/// Mirrors vanilla `JukeboxBlockEntity.java:54` & `Vec3.java:181`:
/// `Vec3.atLowerCornerWithOffset(pos, 0.5, 1.01, 0.5).offsetRandomXZ(random, 0.7F)`
/// where `rx` and `rz` are random floats in `[0.0, 1.0]`.
#[must_use]
pub fn calculate_jukebox_pop_out_position(pos: pumpkin_util::math::position::BlockPos, rx: f64, rz: f64) -> pumpkin_util::math::vector3::Vector3<f64> {
    pumpkin_util::math::vector3::Vector3::new(
        f64::from(pos.0.x) + 0.5 + (rx - 0.5) * 0.7,
        f64::from(pos.0.y) + 1.01,
        f64::from(pos.0.z) + 0.5 + (rz - 0.5) * 0.7,
    )
}

/// Returns the item remaining after crafting, mirroring vanilla `Item.java:433-438`
/// & `CraftingRecipe.java:26-36`.
#[must_use]
pub fn get_crafting_remainder(item_id: u16) -> Option<&'static pumpkin_data::item::Item> {
    use pumpkin_data::item::Item;
    if item_id == Item::WATER_BUCKET.id
        || item_id == Item::LAVA_BUCKET.id
        || item_id == Item::MILK_BUCKET.id
        || item_id == Item::POWDER_SNOW_BUCKET.id
        || item_id == Item::AXOLOTL_BUCKET.id
        || item_id == Item::COD_BUCKET.id
        || item_id == Item::SALMON_BUCKET.id
        || item_id == Item::PUFFERFISH_BUCKET.id
        || item_id == Item::TROPICAL_FISH_BUCKET.id
        || item_id == Item::TADPOLE_BUCKET.id
    {
        Some(&Item::BUCKET)
    } else if item_id == Item::HONEY_BOTTLE.id
        || item_id == Item::POTION.id
        || item_id == Item::SPLASH_POTION.id
        || item_id == Item::LINGERING_POTION.id
        || item_id == Item::OMINOUS_BOTTLE.id
        || item_id == Item::DRAGON_BREATH.id
    {
        Some(&Item::GLASS_BOTTLE)
    } else if item_id == Item::MUSHROOM_STEW.id
        || item_id == Item::RABBIT_STEW.id
        || item_id == Item::BEETROOT_SOUP.id
        || item_id == Item::SUSPICIOUS_STEW.id
    {
        Some(&Item::BOWL)
    } else {
        None
    }
}

/// Calculates respawn anchor comparator output, mirroring vanilla `RespawnAnchorBlock.java:208`:
/// `Mth.floor((charges - 0) / 4.0F * 15.0F)`.
#[must_use]
pub const fn calculate_respawn_anchor_comparator_output(charges: u8) -> u8 {
    let clamped = if charges > 4 { 4 } else { charges };
    ((clamped as u32 * 15) / 4) as u8
}

/// Evaluates if a composter can accept compostable items, mirroring vanilla `ComposterBlock.java:128-129`:
/// Only accepts items if `fillLevel < 7` (level 7 is fermenting, level 8 is ready).
#[must_use]
pub const fn can_composter_accept_items(level: u8) -> bool {
    level < 7
}

/// Evaluates if a composter is ready to yield bone meal, mirroring vanilla `ComposterBlock.java:49`:
/// Ready at level 8.
#[must_use]
pub const fn is_composter_ready_to_harvest(level: u8) -> bool {
    level == 8
}

/// Calculates composter comparator output, mirroring vanilla `ComposterBlock.java:232`:
/// Returns level (0..8).
#[must_use]
pub const fn calculate_composter_comparator_output(level: u8) -> u8 {
    if level > 8 {
        8
    } else {
        level
    }
}

/// Calculates lectern comparator output signal, mirroring vanilla `LecternBlockEntity.java:172-175`:
/// `Mth.floor(pageProgress * 14.0F) + (this.hasBook() ? 1 : 0)`.
#[must_use]
pub fn calculate_lectern_comparator_signal(has_book: bool, page: usize, page_count: usize) -> u8 {
    if !has_book || page_count == 0 {
        return 0;
    }
    let progress = if page_count > 1 {
        (page.min(page_count - 1)) as f32 / (page_count - 1) as f32
    } else {
        1.0
    };
    (progress * 14.0).floor() as u8 + 1
}

/// Calculates lectern book drop offset when destroyed, mirroring vanilla `LecternBlockEntity.java:222-224`:
/// `xo = 0.25F * direction.getStepX()`, `zo = 0.25F * direction.getStepZ()`.
#[must_use]
pub const fn calculate_lectern_drop_offset(facing_step_x: f32, facing_step_z: f32) -> (f64, f64) {
    (
        0.25 * facing_step_x as f64,
        0.25 * facing_step_z as f64,
    )
}

/// Calculates chiseled bookshelf targeted slot (0..5) based on normalized hit face coordinates (x, y),
/// mirroring vanilla `ChiseledBookShelfBlock.java:49-56, 122` & `SelectableSlotContainer.java`:
/// 2 rows, 3 columns per row.
#[must_use]
pub fn calculate_chiseled_bookshelf_hit_slot(cursor_x: f32, cursor_y: f32) -> usize {
    let row = ((1.0 - cursor_y) * 2.0).floor().clamp(0.0, 1.0) as usize;
    let col = (cursor_x * 3.0).floor().clamp(0.0, 2.0) as usize;
    col + row * 3
}

/// Calculates cauldron comparator output signal, mirroring vanilla `AbstractCauldronBlock.java:76-78`,
/// `LayeredCauldronBlock.java:109-111` & `LavaCauldronBlock.java:49-51`:
/// Empty cauldron = 0, lava cauldron = 3, water/powder snow = level (1..3).
#[must_use]
pub fn calculate_cauldron_comparator_output(block_type: &str, level: u8) -> u8 {
    match block_type {
        "water_cauldron" | "powder_snow_cauldron" => {
            if level < 1 {
                1
            } else if level > 3 {
                3
            } else {
                level
            }
        }
        "lava_cauldron" => 3,
        _ => 0,
    }
}

/// Evaluates flower pot potting eligibility and plant name resolution,
