/// ```
#[must_use]
pub fn calculate_effective_fall_distance(
    impact_pos_y: f64,
    current_y: f64,
    raw_fall_distance: f64,
) -> (f64, bool) {
    let effective = (impact_pos_y - current_y).min(raw_fall_distance);
    let landed_above = effective <= 0.0;
    (effective.max(0.0), landed_above)
}

