/// `return !this.isSleeping() && !this.isSitting() && !this.isFaceplanted();`
#[must_use]
pub const fn can_fox_move(is_sleeping: bool, is_sitting: bool, is_faceplanted: bool) -> bool {
    !is_sleeping && !is_sitting && !is_faceplanted
}

