/// `getAgeScale() = isBaby() ? 0.5F : 1.0F`.
pub const SNIFFER_ADULT_WIDTH: f32 = 1.9;
pub const SNIFFER_ADULT_HEIGHT: f32 = 1.75;
pub const SNIFFER_ADULT_EYE_HEIGHT: f32 = 1.05;
pub const SNIFFER_DIGGING_HEIGHT: f32 = 1.35;
