#[must_use]
pub fn calculate_dispense_item_spawn_position(base_pos: Vector3<f64>, is_y_axis: bool) -> Vector3<f64> {
    let offset = if is_y_axis {
        DISPENSE_ITEM_Y_AXIS_OFFSET
    } else {
        DISPENSE_ITEM_HORIZONTAL_AXIS_OFFSET
    };
    Vector3::new(base_pos.x, base_pos.y - offset, base_pos.z)
}

#[must_use]
pub fn calculate_dispense_item_velocity(
    step_x: f64,
    step_z: f64,
    pow: f64,
    accuracy: i32,
    rand_diff_x: f64,
    rand_diff_y: f64,
    rand_diff_z: f64,
) -> Vector3<f64> {
    let spread = DISPENSE_ITEM_SPREAD_FACTOR * f64::from(accuracy);
    let vx = rand_diff_x.mul_add(spread, step_x * pow);
    let vy = rand_diff_y.mul_add(spread, DISPENSE_ITEM_BASE_UP_VELOCITY);
    let vz = rand_diff_z.mul_add(spread, step_z * pow);
    Vector3::new(vx, vy, vz)
}

#[must_use]
pub fn calculate_ominous_potion_velocity(
    rand_diff_x: f64,
    rand_diff_y: f64,
    rand_diff_z: f64,
) -> Vector3<f64> {
    // Direction.DOWN = (0, -1, 0)
    // shoot(0, -1, 0, power, uncertainty)
    let spread = DISPENSE_ITEM_SPREAD_FACTOR * OMINOUS_POTION_UNCERTAINTY;
    let vx = rand_diff_x * spread * OMINOUS_POTION_POWER;
    let vy = (-1.0 + rand_diff_y * spread) * OMINOUS_POTION_POWER;
    let vz = rand_diff_z * spread * OMINOUS_POTION_POWER;
    Vector3::new(vx, vy, vz)
}

#[must_use]
pub fn calculate_ominous_arrow_velocity(
    rand_diff_x: f64,
    rand_diff_y: f64,
    rand_diff_z: f64,
) -> Vector3<f64> {
    let spread = DISPENSE_ITEM_SPREAD_FACTOR * OMINOUS_ARROW_UNCERTAINTY;
    let vx = rand_diff_x * spread * OMINOUS_ARROW_POWER;
    let vy = (-1.0 + rand_diff_y * spread) * OMINOUS_ARROW_POWER;
    let vz = rand_diff_z * spread * OMINOUS_ARROW_POWER;
    Vector3::new(vx, vy, vz)
}

#[must_use]
pub fn calculate_ominous_wind_charge_velocity(
    rand_diff_x: f64,
    rand_diff_y: f64,
    rand_diff_z: f64,
) -> Vector3<f64> {
    let dir_x = rand_diff_x * OMINOUS_PROJECTILE_DIRECTION_DEVIATION;
    let dir_y = -1.0 + rand_diff_y * OMINOUS_PROJECTILE_DIRECTION_DEVIATION;
    let dir_z = rand_diff_z * OMINOUS_PROJECTILE_DIRECTION_DEVIATION;
    Vector3::new(dir_x, dir_y, dir_z)
}

#[must_use]
pub fn calculate_ominous_fire_charge_velocity(
    rand_diff_x: f64,
    rand_diff_y: f64,
    rand_diff_z: f64,
) -> Vector3<f64> {
    let dir_x = rand_diff_x * OMINOUS_PROJECTILE_DIRECTION_DEVIATION;
    let dir_y = -1.0 + rand_diff_y * OMINOUS_PROJECTILE_DIRECTION_DEVIATION;
    let dir_z = rand_diff_z * OMINOUS_PROJECTILE_DIRECTION_DEVIATION;
    let len = (dir_x * dir_x + dir_y * dir_y + dir_z * dir_z).sqrt();
    if len > 0.0 {
        Vector3::new(dir_x / len * 0.1, dir_y / len * 0.1, dir_z / len * 0.1)
    } else {
        Vector3::new(0.0, -0.1, 0.0)
    }
}

/// Vanilla `ShearsItem.java:55`: damage applied to shears when used to cut blocks or mobs.
pub const SHEARS_DAMAGE_AMOUNT: u16 = 1;

/// Vanilla `Mob.java:564-566`, `Wolf.java:447-449`:
/// Determines if a player can shear equipment off a mob.
/// Generic mobs require `!is_vehicle()`, while wolves require `is_owner`.
#[must_use]
pub fn can_shear_mob_equipment(is_vehicle: bool, is_owner: bool, is_wolf: bool) -> bool {
    if is_wolf {
        is_owner
    } else {
        !is_vehicle
    }
}

/// Vanilla `Mob.java:571-574`:
/// Checks if an equipped item can be sheared off by a player.
/// In Vanilla 1.21.4, Wolf Armor is equippable with `can_be_sheared = true`.
/// If the item has Curse of Binding (`EnchantmentEffectComponents.PREVENT_ARMOR_CHANGE`),
/// it cannot be sheared unless the player is in Creative mode.
#[must_use]
pub fn can_equipment_be_sheared(
    is_can_be_sheared_item: bool,
    has_curse_of_binding: bool,
    is_creative: bool,
) -> bool {
    if !is_can_be_sheared_item {
        return false;
    }
    !has_curse_of_binding || is_creative
}

/// Vanilla `Fox.java:132`: minimum ticks before a fox finishes eating food held in mouth (30 seconds).
pub const FOX_MIN_TICKS_BEFORE_EAT: i32 = 600;

/// Vanilla `Fox.java:224`: ticks before eating when fox starts playing chewing sounds (28 seconds).
pub const FOX_CHEWING_START_TICKS: i32 = 560;

/// Vanilla `Fox.java:224`: chance per tick to play chewing sound while in chewing window.
pub const FOX_CHEWING_SOUND_CHANCE: f32 = 0.1;

/// Vanilla `Fox.java:265`: chance for naturally spawned fox to hold an item in its mouth (20%).
pub const FOX_NATURAL_MOUTH_ITEM_CHANCE: f32 = 0.2;

/// Vanilla `Fox.java:266-281`: resolves naturally spawned fox mouth item from roll.
#[must_use]
pub fn get_fox_spawn_mouth_item(roll: f32, secondary_roll: bool) -> Option<&'static pumpkin_data::item::Item> {
    if roll < 0.50 {
        Some(&pumpkin_data::item::Item::EMERALD)
    } else if roll < 0.70 {
        Some(&pumpkin_data::item::Item::EGG)
    } else if roll < 0.85 {
        if secondary_roll {
            Some(&pumpkin_data::item::Item::RABBIT_FOOT)
        } else {
            Some(&pumpkin_data::item::Item::RABBIT_HIDE)
        }
    } else if roll < 0.90 {
        Some(&pumpkin_data::item::Item::WHEAT)
    } else if roll < 0.95 {
        Some(&pumpkin_data::item::Item::LEATHER)
    } else if roll < 0.99 {
        Some(&pumpkin_data::item::Item::FEATHER)
    } else {
        Some(&pumpkin_data::item::Item::CHICKEN)
    }
}

/// Vanilla `Fox.java:224`: returns true if a chewing sound should be played.
#[must_use]
pub fn should_play_fox_chewing_sound(ticks: i32, roll: f32) -> bool {
    ticks > FOX_CHEWING_START_TICKS && roll < FOX_CHEWING_SOUND_CHANCE
}

