/// Rotates a 3D attachment point vector around the Y axis by -yaw (in degrees),
/// matching vanilla `EntityAttachments.java:79` and `Vec3.java:245`.
#[must_use]
pub fn transform_attachment_point(point: Vector3<f64>, yaw_degrees: f32) -> Vector3<f64> {
    let radians = (-yaw_degrees).to_radians();
    let cos = f64::from(radians.cos());
    let sin = f64::from(radians.sin());
    Vector3::new(
        point.x * cos + point.z * sin,
        point.y,
        point.z * cos - point.x * sin,
    )
}

/// Vanilla `Entity.getVehicleAttachmentPoint(vehicle)` (`Entity.java:2470-2472`).
/// Returns the offset applied to this passenger when riding a vehicle:
/// `(0.0, -riding_offset, 0.0)` for mobs with ridingOffset,
/// `Avatar.DEFAULT_VEHICLE_ATTACHMENT = (0.0, 0.6, 0.0)` for players/mannequins,
/// or `(0.0, 0.0, 0.0)` fallback (`EntityAttachment.Fallback.AT_FEET`).
#[must_use]
pub fn get_entity_vehicle_attachment_point(
    passenger_type: &'static pumpkin_data::entity::EntityType,
    passenger_yaw: f32,
) -> Vector3<f64> {
    use pumpkin_data::entity::EntityType;
    let point = if passenger_type == &EntityType::PLAYER || passenger_type == &EntityType::MANNEQUIN {
        DEFAULT_VEHICLE_ATTACHMENT
    } else if passenger_type == &EntityType::BOGGED
        || passenger_type == &EntityType::SKELETON
        || passenger_type == &EntityType::STRAY
        || passenger_type == &EntityType::ZOMBIE
        || passenger_type == &EntityType::DROWNED
        || passenger_type == &EntityType::HUSK
        || passenger_type == &EntityType::ZOMBIE_VILLAGER
        || passenger_type == &EntityType::ZOMBIFIED_PIGLIN
        || passenger_type == &EntityType::PIGLIN
        || passenger_type == &EntityType::PIGLIN_BRUTE
        || passenger_type == &EntityType::PARCHED
    {
        // EntityTypes.java: ridingOffset(-0.7F) -> attach(0.0, 0.7, 0.0)
        Vector3::new(0.0, 0.7, 0.0)
    } else if passenger_type == &EntityType::WITHER_SKELETON {
        // EntityTypes.java: ridingOffset(-0.875F) -> attach(0.0, 0.875, 0.0)
        Vector3::new(0.0, 0.875, 0.0)
    } else if passenger_type == &EntityType::EVOKER
        || passenger_type == &EntityType::PILLAGER
        || passenger_type == &EntityType::VINDICATOR
        || passenger_type == &EntityType::ILLUSIONER
    {
        // EntityTypes.java: ridingOffset(-0.6F) -> attach(0.0, 0.6, 0.0)
        Vector3::new(0.0, 0.6, 0.0)
    } else if passenger_type == &EntityType::GIANT {
        // EntityTypes.java: ridingOffset(-3.75F) -> attach(0.0, 3.75, 0.0)
        Vector3::new(0.0, 3.75, 0.0)
    } else if passenger_type == &EntityType::PHANTOM {
        // EntityTypes.java: ridingOffset(-0.125F) -> attach(0.0, 0.125, 0.0)
        Vector3::new(0.0, 0.125, 0.0)
    } else if passenger_type == &EntityType::GHAST || passenger_type == &EntityType::HAPPY_GHAST {
        // EntityTypes.java: ridingOffset(0.5F) -> attach(0.0, -0.5, 0.0)
        Vector3::new(0.0, -0.5, 0.0)
    } else if passenger_type == &EntityType::ALLAY || passenger_type == &EntityType::VEX {
        // EntityTypes.java: ridingOffset(0.04F) -> attach(0.0, -0.04, 0.0)
        Vector3::new(0.0, -0.04, 0.0)
    } else {
        Vector3::new(0.0, 0.0, 0.0)
    };
    transform_attachment_point(point, passenger_yaw)
}

/// Vanilla `Entity.getPassengerAttachmentPoint(passenger, dimensions, scale)`
/// (`Entity.java:2478-2485`, `AbstractBoat.java:138-154`, `AbstractMinecart.java:180-183`,
/// `Camel.java:493-509`, `AbstractHorse.java:1042-1045`, `AbstractCubeMob.java:249-251`).
#[must_use]
pub fn get_passenger_attachment_point(
    vehicle_type: &'static pumpkin_data::entity::EntityType,
    passenger_type: &'static pumpkin_data::entity::EntityType,
    passenger_index: usize,
    total_passengers: usize,
    vehicle_yaw: f32,
    vehicle_pose: pumpkin_data::entity::EntityPose,
    vehicle_scale: f32,
    is_animal_passenger: bool,
    stand_anim: f32,
) -> Vector3<f64> {
    use pumpkin_data::entity::EntityType;

    // 1. Boats & Rafts (AbstractBoat.java:138-154)
    if is_boat_entity_type(vehicle_type) {
        let is_raft = is_raft_entity_type(vehicle_type);
        let is_chest = is_chest_boat_entity_type(vehicle_type);
        let ride_height = if is_raft {
            f64::from(0.5625f32 * RAFT_RIDE_HEIGHT_RATIO)
        } else {
            f64::from(0.5625f32 * BOAT_RIDE_HEIGHT_RATIO)
        };
        let offset = if total_passengers > 1 {
            let base = if passenger_index == 0 {
                BOAT_MULTI_PASSENGER_DRIVER_OFFSET
            } else {
                BOAT_MULTI_PASSENGER_RIDER_OFFSET
            };
            if is_animal_passenger {
                base + BOAT_ANIMAL_PASSENGER_EXTRA_OFFSET
            } else {
                base
            }
        } else if is_chest {
            CHEST_BOAT_PASSENGER_OFFSET_X
        } else {
            0.0f32
        };
        let point = Vector3::new(0.0, ride_height, f64::from(offset));
        return transform_attachment_point(point, vehicle_yaw);
    }

    // 2. Minecarts (AbstractMinecart.java:180-183)
    if is_minecart_entity_type(vehicle_type) {
        if passenger_type == &EntityType::VILLAGER || passenger_type == &EntityType::WANDERING_TRADER {
            return MINECART_LOWERED_PASSENGER_ATTACHMENT;
        }
        return Vector3::new(0.0, MINECART_PASSENGER_ATTACHMENT_Y, 0.0);
    }

    // 3. Camels (Camel.java:493-509)
    if vehicle_type == &EntityType::CAMEL || vehicle_type == &EntityType::CAMEL_HUSK {
        let is_driver = passenger_index == 0;
        let mut offset = CAMEL_DRIVER_OFFSET;
        if total_passengers > 1 {
            if !is_driver {
                offset = CAMEL_PASSENGER_OFFSET;
            }
            if is_animal_passenger {
                offset += CAMEL_ANIMAL_EXTRA_OFFSET;
            }
        }
        let scale = if vehicle_scale <= 0.0 { 1.0f32 } else { vehicle_scale };
        let is_sitting = vehicle_pose == pumpkin_data::entity::EntityPose::Sitting;
        let age_sit_y_offset = if scale < 0.9f32 {
            f64::from(CAMEL_BABY_AGE_SIT_OFFSET)
        } else {
            f64::from(CAMEL_ADULT_AGE_SIT_OFFSET)
        };
        let dim_height = if is_sitting { 0.945f64 } else { 2.375f64 };
        let mut base_sit_offset = dim_height - age_sit_y_offset;
        let sitting_height_diff = f64::from(scale * CAMEL_SITTING_HEIGHT_DIFFERENCE);
        let vertical_drop = sitting_height_diff - f64::from(scale * CAMEL_VERTICAL_DROP_MARGIN);
        let bottom_point = sitting_height_diff - vertical_drop;
        if is_sitting {
            base_sit_offset += bottom_point;
        }
        let point = Vector3::new(0.0, base_sit_offset, f64::from(offset * scale));
        return transform_attachment_point(point, vehicle_yaw);
    }

    // 4. Horses & Equines (AbstractHorse.java:1042-1045, EntityTypes.java)
    if vehicle_type == &EntityType::HORSE {
        let scale = if vehicle_scale <= 0.0 { 1.0f64 } else { f64::from(vehicle_scale) };
        let anim = f64::from(stand_anim);
        let point = Vector3::new(
            0.0,
            HORSE_PASSENGER_ATTACHMENT_Y + 0.15 * anim * scale,
            -0.7 * anim * scale,
        );
        return transform_attachment_point(point, vehicle_yaw);
    }
    if vehicle_type == &EntityType::DONKEY {
        return Vector3::new(0.0, DONKEY_PASSENGER_ATTACHMENT_Y, 0.0);
    }
    if vehicle_type == &EntityType::MULE {
        return Vector3::new(0.0, MULE_PASSENGER_ATTACHMENT_Y, 0.0);
    }
    if vehicle_type == &EntityType::SKELETON_HORSE || vehicle_type == &EntityType::ZOMBIE_HORSE {
        return Vector3::new(0.0, EQUINE_UNDEAD_PASSENGER_ATTACHMENT_Y, 0.0);
    }
    if vehicle_type == &EntityType::LLAMA || vehicle_type == &EntityType::TRADER_LLAMA {
        return transform_attachment_point(LLAMA_PASSENGER_ATTACHMENT, vehicle_yaw);
    }
    if vehicle_type == &EntityType::PIG {
        return Vector3::new(0.0, PIG_PASSENGER_ATTACHMENT_Y, 0.0);
    }
    if vehicle_type == &EntityType::STRIDER {
        return Vector3::new(0.0, STRIDER_PASSENGER_ATTACHMENT_Y, 0.0);
    }

    // 5. Slime & Magma Cube (AbstractCubeMob.java:249-251)
    if vehicle_type == &EntityType::SLIME || vehicle_type == &EntityType::MAGMA_CUBE {
        let size = if vehicle_scale <= 0.0 { 1.0f64 } else { f64::from(vehicle_scale) };
        let height = 0.51 * size;
        let y = height - 0.015625 * size * size;
        return Vector3::new(0.0, y, 0.0);
    }

    // 6. Other specific mobs (EntityTypes.java)
    let point = if vehicle_type == &EntityType::CHICKEN {
        Vector3::new(0.0, 0.7, -0.1)
    } else if vehicle_type == &EntityType::COW || vehicle_type == &EntityType::MOOSHROOM {
        Vector3::new(0.0, 1.36875, 0.0)
    } else if vehicle_type == &EntityType::SHEEP {
        Vector3::new(0.0, 1.2375, 0.0)
    } else if vehicle_type == &EntityType::GOAT {
        Vector3::new(0.0, 1.1125, 0.0)
    } else if vehicle_type == &EntityType::FROG {
        Vector3::new(0.0, 0.375, -0.25)
    } else if vehicle_type == &EntityType::FOX {
        Vector3::new(0.0, 0.6375, -0.25)
    } else if vehicle_type == &EntityType::WOLF {
        Vector3::new(0.0, 0.81875, -0.0625)
    } else if vehicle_type == &EntityType::CAT {
        Vector3::new(0.0, 0.5125, 0.0)
    } else if vehicle_type == &EntityType::OCELOT {
        Vector3::new(0.0, 0.6375, 0.0)
    } else if vehicle_type == &EntityType::PARROT {
        Vector3::new(0.0, 0.4625, 0.0)
    } else if vehicle_type == &EntityType::TURTLE {
        Vector3::new(0.0, 0.55625, -0.25)
    } else if vehicle_type == &EntityType::RAVAGER {
        Vector3::new(0.0, 2.2625, -0.0625)
    } else if vehicle_type == &EntityType::HOGLIN || vehicle_type == &EntityType::ZOGLIN {
        Vector3::new(0.0, 1.49375, 0.0)
    } else if vehicle_type == &EntityType::ZOMBIE
        || vehicle_type == &EntityType::DROWNED
        || vehicle_type == &EntityType::PIGLIN
        || vehicle_type == &EntityType::PIGLIN_BRUTE
    {
        Vector3::new(0.0, 2.0125, 0.0)
    } else if vehicle_type == &EntityType::HUSK {
        Vector3::new(0.0, 2.075, 0.0)
    } else if vehicle_type == &EntityType::ZOMBIE_VILLAGER {
        Vector3::new(0.0, 2.125, 0.0)
    } else if vehicle_type == &EntityType::ZOMBIFIED_PIGLIN
        || vehicle_type == &EntityType::EVOKER
        || vehicle_type == &EntityType::PILLAGER
        || vehicle_type == &EntityType::VINDICATOR
        || vehicle_type == &EntityType::ILLUSIONER
    {
        Vector3::new(0.0, 2.0, 0.0)
    } else if vehicle_type == &EntityType::WITCH {
        Vector3::new(0.0, 2.2625, 0.0)
    } else if vehicle_type == &EntityType::WARDEN {
        Vector3::new(0.0, 3.15, 0.0)
    } else if vehicle_type == &EntityType::SNIFFER {
        Vector3::new(0.0, 2.09375, 0.0)
    } else if vehicle_type == &EntityType::SPIDER {
        Vector3::new(0.0, 0.765, 0.0)
    } else if vehicle_type == &EntityType::GHAST {
        Vector3::new(0.0, 4.0625, 0.0)
    } else if vehicle_type == &EntityType::HAPPY_GHAST {
        let points = [
            Vector3::new(0.0, 4.0, 1.7),
            Vector3::new(-1.7, 4.0, 0.0),
            Vector3::new(0.0, 4.0, -1.7),
            Vector3::new(1.7, 4.0, 0.0),
        ];
        let clamped = passenger_index.min(points.len() - 1);
        points[clamped]
    } else if vehicle_type == &EntityType::ENDER_DRAGON {
        Vector3::new(0.0, 3.0, 0.0)
    } else if vehicle_type == &EntityType::ELDER_GUARDIAN {
        Vector3::new(0.0, 2.350625, 0.0)
    } else if vehicle_type == &EntityType::GUARDIAN {
        Vector3::new(0.0, 0.975, 0.0)
    } else if vehicle_type == &EntityType::ENDERMAN {
        Vector3::new(0.0, 2.80625, 0.0)
    } else if vehicle_type == &EntityType::ENDERMITE || vehicle_type == &EntityType::SILVERFISH {
        Vector3::new(0.0, 0.2375, 0.0)
    } else if vehicle_type == &EntityType::PHANTOM {
        Vector3::new(0.0, 0.3375, 0.0)
    } else if vehicle_type == &EntityType::VEX {
        Vector3::new(0.0, 0.7375, 0.0)
    } else if vehicle_type == &EntityType::NAUTILUS || vehicle_type == &EntityType::ZOMBIE_NAUTILUS {
        Vector3::new(0.0, 1.1375, 0.0)
    } else {
        // Fallback AT_HEIGHT
        let (_, height, _) = get_entity_pose_dimensions(vehicle_type, vehicle_pose);
        Vector3::new(0.0, f64::from(height), 0.0)
    };

    transform_attachment_point(point, vehicle_yaw)
}

/// Vanilla `positionRider` calculation (`Entity.java:2461-2465`):
/// `position = vehicle.getPassengerRidingPosition(passenger)`
/// `offset = passenger.getVehicleAttachmentPoint(vehicle)`
/// `result = position - offset`
#[must_use]
pub fn calculate_passenger_position(
    vehicle_pos: Vector3<f64>,
    vehicle_type: &'static pumpkin_data::entity::EntityType,
    vehicle_yaw: f32,
    vehicle_pose: pumpkin_data::entity::EntityPose,
    vehicle_scale: f32,
    passenger_type: &'static pumpkin_data::entity::EntityType,
    passenger_yaw: f32,
    passenger_index: usize,
    total_passengers: usize,
    is_animal_passenger: bool,
    stand_anim: f32,
) -> Vector3<f64> {
    let passenger_attachment = get_passenger_attachment_point(
        vehicle_type,
        passenger_type,
        passenger_index,
        total_passengers,
        vehicle_yaw,
        vehicle_pose,
        vehicle_scale,
        is_animal_passenger,
        stand_anim,
    );
    let vehicle_attachment = get_entity_vehicle_attachment_point(passenger_type, passenger_yaw);
    vehicle_pos + passenger_attachment - vehicle_attachment
}

// ============================================================================
// Gap 431: Vehicle Passenger Rotation Clamping & Dismount Placement Parity
// ============================================================================

/// Maximum head rotation angle (in degrees) away from the boat body orientation.
/// Mirrors vanilla `AbstractBoat.java:702`: `float maxHeadRotation = 105.0F;`
pub const BOAT_PASSENGER_MAX_HEAD_ROTATION_DEGREES: f32 = 105.0;

/// Default maximum passenger count for standard boats / rafts (driver + 1 passenger).
pub const BOAT_DEFAULT_MAX_PASSENGERS: usize = 2;

/// Animal body yaw rotation offset when passenger ID is even (90.0 degrees sideways).
/// Mirrors vanilla `AbstractBoat.java:711`: `passenger.getId() % 2 == 0 ? 90.0F : 270.0F`.
pub const BOAT_ANIMAL_PASSENGER_EVEN_YAW_OFFSET: f32 = 90.0;

/// Animal body yaw rotation offset when passenger ID is odd (270.0 degrees sideways).
/// Mirrors vanilla `AbstractBoat.java:711`: `passenger.getId() % 2 == 0 ? 90.0F : 270.0F`.
pub const BOAT_ANIMAL_PASSENGER_ODD_YAW_OFFSET: f32 = 270.0;

/// Maximum head rotation angle (in degrees) for mobs relative to their body yaw (75.0 degrees).
/// Mirrors vanilla `Mob.java:758`: `public int getMaxHeadYRot() { return 75; }`.
pub const MOB_DEFAULT_MAX_HEAD_ROTATION_DEGREES: f32 = 75.0;

/// Single leash offset height ratio for boats: `0.88 * height`.
/// Mirrors vanilla `AbstractBoat.java:386`: `new Vec3(0.0, 0.88F * this.getBbHeight(), 0.64F * this.getBbWidth())`.
pub const BOAT_LEASH_OFFSET_HEIGHT_RATIO: f64 = 0.88;

/// Single leash offset width ratio for boats: `0.64 * width`.
/// Mirrors vanilla `AbstractBoat.java:386`: `new Vec3(0.0, 0.88F * this.getBbHeight(), 0.64F * this.getBbWidth())`.
pub const BOAT_LEASH_OFFSET_WIDTH_RATIO: f64 = 0.64;

/// Quad leash attachment front offset ratio (0.0).
/// Mirrors vanilla `AbstractBoat.java:396`: `createQuadLeashOffsets(this, 0.0, 0.64, 0.382, 0.88)`.
pub const BOAT_QUAD_LEASH_FRONT_OFFSET_RATIO: f64 = 0.0;

/// Quad leash attachment front-back distance ratio (0.64).
/// Mirrors vanilla `AbstractBoat.java:396`: `createQuadLeashOffsets(this, 0.0, 0.64, 0.382, 0.88)`.
pub const BOAT_QUAD_LEASH_FRONT_BACK_RATIO: f64 = 0.64;

/// Quad leash attachment left-right distance ratio (0.382).
/// Mirrors vanilla `AbstractBoat.java:396`: `createQuadLeashOffsets(this, 0.0, 0.64, 0.382, 0.88)`.
pub const BOAT_QUAD_LEASH_LEFT_RIGHT_RATIO: f64 = 0.382;

/// Quad leash attachment height ratio (0.88).
/// Mirrors vanilla `AbstractBoat.java:396`: `createQuadLeashOffsets(this, 0.0, 0.64, 0.382, 0.88)`.
pub const BOAT_QUAD_LEASH_HEIGHT_RATIO: f64 = 0.88;

/// Small epsilon used for distance and boundary calculations during dismounting.
/// Mirrors vanilla `DismountHelper.java` and `Entity.java:3754` (`1.0E-5F`).
pub const DISMOUNT_EPSILON: f64 = 1.0e-5;

/// Strider escape angles in degrees: `[0.0, -22.5, 22.5, -45.0, 45.0]`.
/// Mirrors vanilla `Strider.java:216-222`.
pub const STRIDER_DISMOUNT_ESCAPE_ANGLES: [f32; 5] = [0.0, -22.5, 22.5, -45.0, 45.0];

/// Returns whether an entity type is exempt from boat passenger rotation clamping.
/// Only entities with tag `#minecraft:can_turn_in_boats` are exempt (Vanilla 1.21.4: `minecraft:breeze`).
/// Mirrors vanilla `AbstractBoat.java:647`: `!passenger.is(EntityTypeTags.CAN_TURN_IN_BOATS)`.
#[must_use]
pub fn is_entity_exempt_from_boat_rotation_clamp(
    entity_type: &pumpkin_data::entity::EntityType,
) -> bool {
    entity_type == &pumpkin_data::entity::EntityType::BREEZE
}

/// Clamps a mob's head rotation relative to its body rotation.
/// Mirrors vanilla `Mob.java:762-769` (`clampHeadRotationToBody`):
/// ```java
/// float limit = this.getMaxHeadYRot();
/// float headYRot = this.getYHeadRot();
/// float delta = Mth.wrapDegrees(this.yBodyRot - headYRot);
/// float targetDelta = Mth.clamp(Mth.wrapDegrees(this.yBodyRot - headYRot), -limit, limit);
/// float newHeadYRot = headYRot + delta - targetDelta;
/// this.setYHeadRot(newHeadYRot);
/// ```
#[must_use]
pub fn clamp_mob_head_rotation_to_body(body_yaw: f32, head_yaw: f32, max_head_rot: f32) -> f32 {
    let delta = pumpkin_util::math::wrap_degrees(body_yaw - head_yaw);
    let target_delta = delta.clamp(-max_head_rot, max_head_rot);
    head_yaw + delta - target_delta
}

/// Calculates the single lead attachment offset for a boat.
/// Mirrors vanilla `AbstractBoat.java:385-387`:
/// `new Vec3(0.0, 0.88F * this.getBbHeight(), 0.64F * this.getBbWidth())`.
#[must_use]
pub fn calculate_boat_leash_offset(width: f32, height: f32) -> Vector3<f64> {
    Vector3::new(
        0.0,
        height as f64 * BOAT_LEASH_OFFSET_HEIGHT_RATIO,
        width as f64 * BOAT_LEASH_OFFSET_WIDTH_RATIO,
    )
}

/// Calculates 4 quad leash attachment point offsets for an entity.
/// Mirrors vanilla `Leashable.java:279-291` (`createQuadLeashOffsets`).
#[must_use]
pub fn calculate_quad_leash_offsets(
    width: f32,
    height: f32,
    front_offset: f64,
    front_back: f64,
    left_right: f64,
    height_ratio: f64,
) -> [Vector3<f64>; 4] {
    let width_f64 = width as f64;
    let front_offset_scaled = front_offset * width_f64;
    let front_back_scaled = front_back * width_f64;
    let left_right_scaled = left_right * width_f64;
    let height_scaled = height_ratio * height as f64;
    [
        Vector3::new(-left_right_scaled, height_scaled, front_back_scaled + front_offset_scaled),
        Vector3::new(-left_right_scaled, height_scaled, -front_back_scaled + front_offset_scaled),
        Vector3::new(left_right_scaled, height_scaled, -front_back_scaled + front_offset_scaled),
        Vector3::new(left_right_scaled, height_scaled, front_back_scaled + front_offset_scaled),
    ]
}

/// Calculates the 4 quad leash attachment offsets for a boat.
/// Mirrors vanilla `AbstractBoat.java:395-397`.
#[must_use]
pub fn calculate_boat_quad_leash_offsets(width: f32, height: f32) -> [Vector3<f64>; 4] {
    calculate_quad_leash_offsets(
        width,
        height,
        BOAT_QUAD_LEASH_FRONT_OFFSET_RATIO,
        BOAT_QUAD_LEASH_FRONT_BACK_RATIO,
        BOAT_QUAD_LEASH_LEFT_RIGHT_RATIO,
        BOAT_QUAD_LEASH_HEIGHT_RATIO,
    )
}

/// Modifies passenger fluid interaction box when riding a boat.
/// If not underwater, clamps passenger fluid bounding box to start at `max(passenger_min_y, boat_max_y)`.
/// If `boat_max_y >= passenger_max_y`, the passenger fluid interaction box is null (cannot touch fluid).
/// Mirrors vanilla `AbstractBoat.java:816-829`:
/// ```java
/// if (this.isUnderWater()) {
///    return passengerBox;
/// }
/// AABB boatBox = this.getBoundingBox();
/// if (boatBox.maxY >= passengerBox.maxY) {
///    return null;
/// }
/// double minY = Math.max(passengerBox.minY, boatBox.maxY);
/// return new AABB(passengerBox.minX, minY, passengerBox.minZ, passengerBox.maxX, passengerBox.maxY, passengerBox.maxZ);
/// ```
#[must_use]
pub fn modify_boat_passenger_fluid_box(
    passenger_min: Vector3<f64>,
    passenger_max: Vector3<f64>,
    boat_max_y: f64,
    is_underwater: bool,
) -> Option<(Vector3<f64>, Vector3<f64>)> {
    if is_underwater {
        return Some((passenger_min, passenger_max));
    }
    if boat_max_y >= passenger_max.y {
        return None;
    }
    let min_y = passenger_min.y.max(boat_max_y);
    Some((
        Vector3::new(passenger_min.x, min_y, passenger_min.z),
        passenger_max,
    ))
}

/// Calculates the updated fall distance for a boat.
/// Resets to 0 when on ground. Does not accumulate while in water.
/// Mirrors vanilla `AbstractBoat.java:753-762` (`checkFallDamage`).
#[must_use]
pub fn calculate_boat_fall_distance(
    current_fall_distance: f32,
    ya: f64,
    on_ground: bool,
    is_passenger: bool,
    is_water_below: bool,
) -> f32 {
    if is_passenger {
        current_fall_distance
    } else if on_ground {
        0.0
    } else if !is_water_below && ya < 0.0 {
        current_fall_distance - ya as f32
    } else {
        current_fall_distance
    }
}

// ============================================================================
// Gap 443: Boat Item Placement Raycast, Fluid Intersection & Dispense Parity
// ============================================================================

/// Base distance in front of dispenser to spawn a boat: 0.5625 blocks (9/16).
/// Total offset is `0.5625 + boat.width / 2.0`.
/// Mirrors vanilla `BoatDispenseItemBehavior.java:27`: `double justOutsideDispenser = 0.5625 + this.type.getWidth() / 2.0;`.
pub const BOAT_DISPENSER_OUTSIDE_BASE_OFFSET: f64 = 0.5625;

/// Vertical scale applied to dispenser stepY: 1.125 blocks (9/8).
/// Mirrors vanilla `BoatDispenseItemBehavior.java:29`: `double spawnY = center.y() + direction.getStepY() * 1.125F;`.
pub const BOAT_DISPENSER_STEP_Y_SCALE: f64 = 1.125;

/// Vertical offset applied when the target block in front of the dispenser is water (1.0 block).
/// Mirrors vanilla `BoatDispenseItemBehavior.java:34`: `yOffset = 1.0;`.
pub const BOAT_DISPENSER_WATER_Y_OFFSET: f64 = 1.0;

/// Vertical offset applied when the target block in front of dispenser is air and the block below is water (0.0 blocks).
/// Mirrors vanilla `BoatDispenseItemBehavior.java:40`: `yOffset = 0.0;`.
pub const BOAT_DISPENSER_AIR_WATER_BELOW_Y_OFFSET: f64 = 0.0;

/// Maximum reach distance for boat item placement raycasting (5.0 blocks).
/// Mirrors vanilla `BoatItem.java:39-40`: `double range = 5.0;`.
pub const BOAT_PLACEMENT_REACH_DISTANCE: f64 = 5.0;

/// Inflation applied to the raycast search bounding box when looking for blocking entities (1.0 block).
/// Mirrors vanilla `BoatItem.java:40`: `player.getBoundingBox().expandTowards(viewVector.scale(5.0)).inflate(1.0)`.
pub const BOAT_PLACEMENT_SEARCH_BOX_INFLATION: f64 = 1.0;

/// Checks whether a dispenser can spawn a boat based on fluid conditions in front.
/// Returns `Some(y_offset)` if boat can be spawned, or `None` if item should drop instead.
/// Mirrors vanilla `BoatDispenseItemBehavior.java:33-41`:
/// ```java
/// double yOffset;
/// if (level.getFluidState(frontPos).is(FluidTags.WATER)) {
///    yOffset = 1.0;
/// } else {
///    if (!level.getBlockState(frontPos).isAir() || !level.getFluidState(frontPos.below()).is(FluidTags.WATER)) {
///       return this.defaultDispenseItemBehavior.dispense(source, dispensed);
///    }
///    yOffset = 0.0;
/// }
/// ```
#[must_use]
pub fn can_dispense_boat(
    is_front_water: bool,
    is_front_air: bool,
    is_below_front_water: bool,
) -> Option<f64> {
    if is_front_water {
        Some(BOAT_DISPENSER_WATER_Y_OFFSET)
    } else if is_front_air && is_below_front_water {
        Some(BOAT_DISPENSER_AIR_WATER_BELOW_Y_OFFSET)
    } else {
        None
    }
}

/// Calculates the exact spawn position for a dispensed boat.
/// Mirrors vanilla `BoatDispenseItemBehavior.java:27-30, 45`:
/// ```java
/// double justOutsideDispenser = 0.5625 + this.type.getWidth() / 2.0;
/// double spawnX = center.x() + direction.getStepX() * justOutsideDispenser;
/// double spawnY = center.y() + direction.getStepY() * 1.125F;
/// double spawnZ = center.z() + direction.getStepZ() * justOutsideDispenser;
/// boat.setInitialPos(spawnX, spawnY + yOffset, spawnZ);
/// ```
#[must_use]
pub fn calculate_boat_dispense_spawn_position(
    center: Vector3<f64>,
    step_x: i32,
    step_y: i32,
    step_z: i32,
    boat_width: f32,
    y_offset: f64,
) -> Vector3<f64> {
    let just_outside = BOAT_DISPENSER_OUTSIDE_BASE_OFFSET + f64::from(boat_width) / 2.0;
    let spawn_x = center.x + f64::from(step_x) * just_outside;
    let spawn_y = center.y + f64::from(step_y) * BOAT_DISPENSER_STEP_Y_SCALE + y_offset;
    let spawn_z = center.z + f64::from(step_z) * just_outside;
    Vector3::new(spawn_x, spawn_y, spawn_z)
}

/// Converts a dispenser Facing property to a boat spawn yaw angle in degrees.
/// Mirrors vanilla `BoatDispenseItemBehavior.java:47` (`direction.toYRot()`):
/// `(direction.data2d & 3) * 90` where `South=0.0, West=90.0, North=180.0, East=270.0`.
#[must_use]
pub fn facing_to_boat_dispense_yaw(facing: pumpkin_data::block_properties::Facing) -> f32 {
    use pumpkin_data::block_properties::Facing;
    match facing {
        Facing::South => 0.0,
        Facing::West => 90.0,
        Facing::North => 180.0,
        Facing::East => 270.0,
        Facing::Up | Facing::Down => 0.0,
    }
}

/// Checks whether a point is contained inside an entity's pick bounding box inflated by pick radius.
/// Mirrors vanilla `BoatItem.java:45-47`:
/// ```java
/// AABB bb = entity.getBoundingBox().inflate(entity.getPickRadius());
/// if (bb.contains(from)) return InteractionResult.PASS;
/// ```
#[must_use]
pub fn is_point_inside_entity_pick_box(
    point: Vector3<f64>,
    box_min: Vector3<f64>,
    box_max: Vector3<f64>,
    pick_radius: f32,
) -> bool {
    let r = f64::from(pick_radius);
    point.x >= box_min.x - r
        && point.x <= box_max.x + r
        && point.y >= box_min.y - r
        && point.y <= box_max.y + r
        && point.z >= box_min.z - r
        && point.z <= box_max.z + r
}

/// Calculates the body yaw for a passenger riding a boat.
/// Animals riding in a completely full boat (2 passengers) face sideways (perpendicular, 90 or 270 degrees).
/// Mirrors vanilla `AbstractBoat.java:709-713`:
/// ```java
/// private float calculatePassengerBodyYRot(final Entity passenger) {
///    return passenger instanceof Animal && this.getPassengers().size() == this.getMaxPassengers()
///       ? this.getYRot() + (passenger.getId() % 2 == 0 ? 90.0F : 270.0F)
///       : this.getYRot();
/// }
/// ```
#[must_use]
pub fn calculate_boat_passenger_body_y_rot(
    boat_yaw: f32,
    passenger_type: &'static pumpkin_data::entity::EntityType,
    passenger_id: i32,
    total_passengers: usize,
    max_passengers: usize,
) -> f32 {
    if is_animal_entity_type(passenger_type) && total_passengers >= max_passengers {
        let side_offset = if passenger_id % 2 == 0 {
            BOAT_ANIMAL_PASSENGER_EVEN_YAW_OFFSET
        } else {
            BOAT_ANIMAL_PASSENGER_ODD_YAW_OFFSET
        };
        boat_yaw + side_offset
    } else {
        boat_yaw
    }
}

/// Clamps the passenger rotation inside a boat.
/// - If passenger has tag `#minecraft:can_turn_in_boats` (Breeze), no clamping is applied.
/// - If passenger is a Mob, its yaw is locked to the body yaw (`mob.clampHeadRotationToBody()`).
/// - If passenger is a Player / other, yaw is clamped to within +/- 105 degrees of the boat's body yaw.
/// Returns `(clamped_yaw, y_delta)` where `y_delta` is the delta applied to `passenger.yRotO`.
/// Mirrors vanilla `AbstractBoat.java:693-706`:
/// ```java
/// protected float clampRotation(final Entity passenger) {
///    float passengerBodyYRot = this.calculatePassengerBodyYRot(passenger);
///    passenger.setYBodyRot(passengerBodyYRot);
///    if (passenger instanceof Mob mob) {
///       passenger.setYRot(passengerBodyYRot);
///       mob.clampHeadRotationToBody();
///       return Mth.wrapDegrees(passengerBodyYRot - passenger.getYRot());
///    } else {
///       float delta = Mth.wrapDegrees(passenger.getYRot() - passengerBodyYRot);
///       float maxHeadRotation = 105.0F;
///       float targetDelta = Mth.clamp(delta, -105.0F, 105.0F);
///       passenger.setYRot(passenger.getYRot() + targetDelta - delta);
///       return targetDelta - delta;
///    }
/// }
/// ```
#[must_use]
pub fn clamp_boat_passenger_rotation(
    boat_yaw: f32,
    passenger_type: &'static pumpkin_data::entity::EntityType,
    passenger_id: i32,
    passenger_yaw: f32,
    total_passengers: usize,
    max_passengers: usize,
    is_mob: bool,
) -> (f32, f32) {
    if is_entity_exempt_from_boat_rotation_clamp(passenger_type) {
        return (passenger_yaw, 0.0);
    }

    let passenger_body_y_rot = calculate_boat_passenger_body_y_rot(
        boat_yaw,
        passenger_type,
        passenger_id,
        total_passengers,
        max_passengers,
    );

    use pumpkin_util::math::wrap_degrees;

    if is_mob {
        let y_delta = wrap_degrees(passenger_body_y_rot - passenger_yaw);
        (passenger_body_y_rot, y_delta)
    } else {
        let delta = wrap_degrees(passenger_yaw - passenger_body_y_rot);
        let target_delta = delta.clamp(
            -BOAT_PASSENGER_MAX_HEAD_ROTATION_DEGREES,
            BOAT_PASSENGER_MAX_HEAD_ROTATION_DEGREES,
        );
        let new_yaw = passenger_yaw + target_delta - delta;
        let y_delta = target_delta - delta;
        (new_yaw, y_delta)
    }
}

/// Calculates the horizontal escape vector for dismounting an entity.
/// Mirrors vanilla `Entity.getCollisionHorizontalEscapeVector` (`Entity.java:3753-3758`):
/// ```java
/// double distance = (colliderWidth + collidingWidth + 1.0E-5F) / 2.0;
/// float directionX = -Mth.sin(directionDegrees * (float) (Math.PI / 180.0));
/// float directionZ = Mth.cos(directionDegrees * (float) (Math.PI / 180.0));
/// float scale = Math.max(Math.abs(directionX), Math.abs(directionZ));
/// return new Vec3(directionX * distance / scale, 0.0, directionZ * distance / scale);
/// ```
#[must_use]
pub fn get_collision_horizontal_escape_vector(
    collider_width: f64,
    colliding_width: f64,
    direction_degrees: f32,
) -> Vector3<f64> {
    let distance = (collider_width + colliding_width + DISMOUNT_EPSILON) / 2.0;
    let rad = (direction_degrees as f64).to_radians();
    let dir_x = -rad.sin();
    let dir_z = rad.cos();
    let scale = dir_x.abs().max(dir_z.abs());
    Vector3::new(
        dir_x * distance / scale,
        0.0,
        dir_z * distance / scale,
    )
}

/// Converts a yaw rotation into a 2D horizontal Direction matching vanilla `Direction.fromYRot` (`Direction.java:299-301`):
/// `from2DDataValue(Mth.floor(yRot / 90.0 + 0.5) & 3)`
/// where `0 -> SOUTH, 1 -> WEST, 2 -> NORTH, 3 -> EAST`.
#[must_use]
pub fn horizontal_direction_from_yaw(yaw: f32) -> pumpkin_data::BlockDirection {
    use pumpkin_data::BlockDirection;
    let idx = ((f64::from(yaw) / 90.0 + 0.5).floor() as i32) & 3;
    match idx {
        0 => BlockDirection::South,
        1 => BlockDirection::West,
        2 => BlockDirection::North,
        3 => BlockDirection::East,
        _ => BlockDirection::South,
    }
}

/// Returns the 8 horizontal block offsets around a vehicle in vanilla order:
/// `[right, left, back+right, back+left, forward+right, forward+left, back, forward]`.
/// Mirrors vanilla `DismountHelper.offsetsForDirection` (`DismountHelper.java:22-36`).
#[must_use]
pub fn dismount_offsets_for_direction(forward: pumpkin_data::BlockDirection) -> [(i32, i32); 8] {
    use pumpkin_data::BlockDirection;
    let (fx, fz) = match forward {
        BlockDirection::North => (0, -1),
        BlockDirection::South => (0, 1),
        BlockDirection::East => (1, 0),
        BlockDirection::West => (-1, 0),
        _ => (0, 1),
    };
    // In Minecraft 2D coordinates:
    // South (0, 1) -> clockwise is West (-1, 0)
    // West (-1, 0) -> clockwise is North (0, -1)
    // North (0, -1) -> clockwise is East (1, 0)
    // East (1, 0) -> clockwise is South (0, 1)
    // Hence right = (-fz, fx), left = (fz, -fx), back = (-fx, -fz)
    let (rx, rz) = (-fz, fx);
    let (lx, lz) = (fz, -fx);
    let (bx, bz) = (-fx, -fz);

    [
        (rx, rz),
        (lx, lz),
        (bx + rx, bz + rz),
        (bx + lx, bz + lz),
        (fx + rx, fz + rz),
        (fx + lx, fz + lz),
        (bx, bz),
        (fx, fz),
    ]
}

/// Checks whether a block floor height is valid for dismounting onto.
/// Mirrors vanilla `DismountHelper.isBlockFloorValid` (`DismountHelper.java:38-40`):
/// `return !Double.isInfinite(blockFloorHeight) && blockFloorHeight < 1.0;`
#[must_use]
pub fn is_block_floor_valid(floor_height: f64) -> bool {
    floor_height.is_finite() && floor_height < 1.0
}

/// Returns the candidate dismount poses for an entity.
/// Players check `[Standing, Crouching, Swimming]`, mobs only check `[Standing]`.
/// Mirrors vanilla `Player.getDismountPoses` (`Player.java:1855`) and `LivingEntity.getDismountPoses` (`LivingEntity.java:3761`).
#[must_use]
pub fn get_entity_dismount_poses(is_player: bool) -> &'static [pumpkin_data::entity::EntityPose] {
    if is_player {
        &[
            pumpkin_data::entity::EntityPose::Standing,
            pumpkin_data::entity::EntityPose::Crouching,
            pumpkin_data::entity::EntityPose::Swimming,
        ]
    } else {
        &[pumpkin_data::entity::EntityPose::Standing]
    }
}

/// Returns the Y offsets to test for minecart dismount for a given pose.
/// Mirrors vanilla `AbstractMinecart.POSE_DISMOUNT_HEIGHTS` (`AbstractMinecart.java:57-59`):
/// - Standing: `[0, 1, -1]`
/// - Crouching: `[0, 1, -1]`
/// - Swimming: `[0, 1]`
#[must_use]
pub fn get_minecart_dismount_y_offsets(pose: pumpkin_data::entity::EntityPose) -> &'static [i32] {
    match pose {
        pumpkin_data::entity::EntityPose::Standing | pumpkin_data::entity::EntityPose::Crouching => {
            &[0, 1, -1]
        }
        pumpkin_data::entity::EntityPose::Swimming => &[0, 1],
        _ => &[0],
    }
}

/// Vanilla `ShulkerBoxBlock.java:83-84` & `Shulker.java:264-277`:
/// Returns the expected min and max bounds for shulker box lid opening collision box.
#[must_use]
pub fn get_shulker_box_lid_bounds(
    x: f64,
    y: f64,
    z: f64,
    facing: pumpkin_data::BlockDirection,
) -> ([f64; 3], [f64; 3]) {
    let eps = 1.0e-6;
    match facing {
        pumpkin_data::BlockDirection::Up => (
            [x + eps, y + 1.0 + eps, z + eps],
            [x + 1.0 - eps, y + 1.5 - eps, z + 1.0 - eps],
        ),
        pumpkin_data::BlockDirection::Down => (
            [x + eps, y - 0.5 + eps, z + eps],
            [x + 1.0 - eps, y - eps, z + 1.0 - eps],
        ),
        pumpkin_data::BlockDirection::North => (
            [x + eps, y + eps, z - 0.5 + eps],
            [x + 1.0 - eps, y + 1.0 - eps, z - eps],
        ),
        pumpkin_data::BlockDirection::South => (
            [x + eps, y + eps, z + 1.0 + eps],
            [x + 1.0 - eps, y + 1.0 - eps, z + 1.5 - eps],
        ),
        pumpkin_data::BlockDirection::West => (
            [x - 0.5 + eps, y + eps, z + eps],
            [x - eps, y + 1.0 - eps, z + 1.0 - eps],
        ),
        pumpkin_data::BlockDirection::East => (
            [x + 1.0 + eps, y + eps, z + eps],
            [x + 1.5 - eps, y + 1.0 - eps, z + 1.0 - eps],
        ),
    }
}

