        assert_eq!(calculate_ghast_damage_received(6.0, true), 1000.0);
        assert_eq!(calculate_ghast_damage_received(6.0, false), 6.0);

        // 5. Ghast constants parity (Ghast.java:46, 51, 118-121, 146, 195, 361, 365, 379)
