    #[test]
    fn test_decorated_pot_and_crafter_parity() {
        // Decorated Pot constants & wobble
        assert_eq!(DECORATED_POT_EVENT_POT_WOBBLES, 1);
        assert_eq!(DECORATED_POT_WOBBLE_POSITIVE_TICKS, 7);
        assert_eq!(DECORATED_POT_WOBBLE_NEGATIVE_TICKS, 10);

        // Pitch formula: 0.7 + 0.5 * (count / max_stack)
        assert!((calculate_decorated_pot_pitch(0, 64) - 0.7).abs() < 1e-4);
        assert!((calculate_decorated_pot_pitch(32, 64) - 0.95).abs() < 1e-4);
        assert!((calculate_decorated_pot_pitch(64, 64) - 1.2).abs() < 1e-4);
        assert!((calculate_decorated_pot_pitch(1, 1) - 1.2).abs() < 1e-4);

        // Pot comparator output: lerpDiscrete from 0 to 15
        assert_eq!(calculate_decorated_pot_comparator_output(0, 64), 0);
        assert_eq!(calculate_decorated_pot_comparator_output(1, 64), 1);
        assert_eq!(calculate_decorated_pot_comparator_output(32, 64), 8);
        assert_eq!(calculate_decorated_pot_comparator_output(64, 64), 15);
        assert_eq!(calculate_decorated_pot_comparator_output(1, 1), 15);

        // Crafter constants
        assert_eq!(CRAFTER_CONTAINER_SIZE, 9);
        assert_eq!(CRAFTER_CONTAINER_WIDTH, 3);
        assert_eq!(CRAFTER_CONTAINER_HEIGHT, 3);
        assert_eq!(CRAFTER_CRAFTING_TICK_DELAY, 4);
        assert_eq!(CRAFTER_MAX_CRAFTING_TICKS, 6);
        assert_eq!(CRAFTER_FAIL_EVENT_ID, 1050);
        assert_eq!(CRAFTER_CRAFT_EVENT_ID, 1049);

        // Crafter analog redstone signal (0..9)
        for i in 0..=9 {
            assert_eq!(calculate_crafter_redstone_signal(i), i as u8);
        }
        assert_eq!(calculate_crafter_redstone_signal(15), 9); // capped at container size 9

        // Crafter smaller_stack_exist distribution logic:
        let disabled = [false; 9];
        let mut slots: [Option<(u16, u8)>; 9] = [None; 9];
        slots[0] = Some((100, 1));
        // slot 0 has 1 item, slots 1..8 are empty: must distribute to next slot!
        assert!(crafter_smaller_stack_exist(&slots, &disabled, 0));

        // When all slots have 1 item: no smaller stack exists
        for slot in &mut slots {
            *slot = Some((100, 1));
        }
        assert!(!crafter_smaller_stack_exist(&slots, &disabled, 0));

        // When slot 0 has 2 items and slot 1 has 1 item: smaller stack exists at slot 1
        slots[0] = Some((100, 2));
        assert!(crafter_smaller_stack_exist(&slots, &disabled, 0));

        // When slot 1 is disabled and slot 2 is empty: skips slot 1 and detects slot 2
        let mut disabled_with_1 = [false; 9];
        disabled_with_1[1] = true;
        slots[1] = None;
        slots[2] = None;
        assert!(crafter_smaller_stack_exist(&slots, &disabled_with_1, 0));
    }

    #[test]
    fn test_shulker_box_dispenser_and_dropper_parity() {
        // Shulker Box constants
        assert_eq!(SHULKER_BOX_COLUMNS, 9);
        assert_eq!(SHULKER_BOX_ROWS, 3);
        assert_eq!(SHULKER_BOX_CONTAINER_SIZE, 27);
        assert_eq!(SHULKER_BOX_EVENT_SET_OPEN_COUNT, 1);
        assert_eq!(SHULKER_BOX_OPENING_TICK_LENGTH, 10);
        assert_eq!(SHULKER_BOX_MAX_LID_HEIGHT, 0.5);
        assert_eq!(SHULKER_BOX_MAX_LID_ROTATION, 270.0);

        // Dispenser & Dropper container sizes
        assert_eq!(DISPENSER_CONTAINER_SIZE, 9);
        assert_eq!(DROPPER_CONTAINER_SIZE, 9);

        // Reservoir sampling parity:
        assert_eq!(dispenser_reservoir_sampling(&[], &[]), None);

        // When rolls are all 0: every candidate replaces the previous, yielding the last one
        let slots = vec![0, 3, 5, 8];
        assert_eq!(
            dispenser_reservoir_sampling(&slots, &[0, 0, 0, 0]),
            Some(8)
        );

        // When roll is 0 only for first candidate and > 0 for rest: first candidate remains selected
        assert_eq!(
            dispenser_reservoir_sampling(&slots, &[0, 1, 1, 1]),
            Some(0)
        );

        // When roll is 0 for first and third candidate: third candidate selected
        assert_eq!(
            dispenser_reservoir_sampling(&slots, &[0, 1, 0, 1]),
            Some(5)
        );
    }

    #[test]
    fn test_note_block_pitch_instruments_and_particle_parity() {
        assert_eq!(NOTE_BLOCK_VOLUME, 3.0);
        assert_eq!(NOTE_BLOCK_TOTAL_NOTES, 25);
        assert_eq!(NOTE_BLOCK_OCTAVE_SEMITONES, 12);

        // Pitch formula: 2^((note - 12) / 12)
        assert!((calculate_note_block_pitch(0) - 0.5).abs() < 1e-5);
        assert!((calculate_note_block_pitch(12) - 1.0).abs() < 1e-5);
        assert!((calculate_note_block_pitch(24) - 2.0).abs() < 1e-5);
        assert!((calculate_note_block_pitch(6) - std::f32::consts::FRAC_1_SQRT_2).abs() < 1e-4);
        assert!((calculate_note_block_pitch(18) - std::f32::consts::SQRT_2).abs() < 1e-4);

        // Particle color offset: note / 24.0
        assert!((calculate_note_particle_color_offset(0) - 0.0).abs() < 1e-6);
        assert!((calculate_note_particle_color_offset(12) - 0.5).abs() < 1e-6);
        assert!((calculate_note_particle_color_offset(24) - 1.0).abs() < 1e-6);

        // Base block instrument classification (all 20 instruments)
        let base_instruments = [
            "harp", "basedrum", "snare", "hat", "bass", "flute", "bell", "guitar",
            "chime", "xylophone", "iron_xylophone", "cow_bell", "didgeridoo", "bit",
            "banjo", "pling", "trumpet", "trumpet_exposed", "trumpet_oxidized", "trumpet_weathered"
        ];
        for inst in base_instruments {
            assert!(is_note_block_base_instrument(inst), "expected {} to be base instrument", inst);
        }

        // Mob head and custom head instruments (not base instruments)
        let non_base = ["zombie", "skeleton", "creeper", "dragon", "wither_skeleton", "piglin", "custom_head"];
        for inst in non_base {
            assert!(!is_note_block_base_instrument(inst), "expected {} to NOT be base instrument", inst);
        }
    }

