    #[test]
    fn test_dragon_egg_constants_and_teleport_packing_parity() {
        use crate::block::blocks::dragon_egg::DragonEggBlock;
        use pumpkin_util::math::position::BlockPos;
        use pumpkin_util::math::vector3::Vector3;

        assert_eq!(DragonEggBlock::DELAY_AFTER_PLACE, 5);
        assert_eq!(DragonEggBlock::HORIZONTAL_TELEPORT_RADIUS, 16);
        assert_eq!(DragonEggBlock::VERTICAL_TELEPORT_RADIUS, 8);
        assert_eq!(DragonEggBlock::TELEPORT_ATTEMPTS, 1000);
        assert_eq!(DragonEggBlock::EVENT_DRAGON_EGG_TELEPORT, 2015);
        assert_eq!(DragonEggBlock::DUST_COLOR, -16777216);

        // Same position (zero difference)
        let pos = BlockPos(Vector3::new(100, 64, 100));
        let packed_zero = DragonEggBlock::pack_teleport_difference(&pos, &pos);
        let expected_zero = (16 << 16) | (8 << 8) | 16;
        assert_eq!(packed_zero, expected_zero);

        // Target with offsets: +10 X, +4 Y, -5 Z
        let target = BlockPos(Vector3::new(110, 68, 95));
        let packed = DragonEggBlock::pack_teleport_difference(&pos, &target);
        let expected = (26 << 16) | (12 << 8) | 11;
        assert_eq!(packed, expected);
    }

    #[test]
    fn test_respawn_anchor_charges_and_comparator_parity() {
        use crate::block::blocks::respawn_anchor::RespawnAnchorBlock;

        assert_eq!(RespawnAnchorBlock::MIN_CHARGES, 0);
        assert_eq!(RespawnAnchorBlock::MAX_CHARGES, 4);
        assert_eq!(RespawnAnchorBlock::EXPLOSION_POWER, 5.0);
        assert_eq!(RespawnAnchorBlock::MAX_COMPARATOR_SIGNAL, 15);

        // Comparator signal scaling: floor(charges / 4.0 * 15)
        assert_eq!(RespawnAnchorBlock::get_scaled_charge_level(0, 15), 0);
        assert_eq!(RespawnAnchorBlock::get_scaled_charge_level(1, 15), 3);
        assert_eq!(RespawnAnchorBlock::get_scaled_charge_level(2, 15), 7);
        assert_eq!(RespawnAnchorBlock::get_scaled_charge_level(3, 15), 11);
        assert_eq!(RespawnAnchorBlock::get_scaled_charge_level(4, 15), 15);

        // Explosion condition in unsupported dimensions (e.g. Overworld/End)
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(0, false));
        assert!(RespawnAnchorBlock::should_explode_in_unsupported_dimension(1, false));
        assert!(RespawnAnchorBlock::should_explode_in_unsupported_dimension(4, false));
        // Works in supported dimension (Nether)
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(0, true));
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(1, true));
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(4, true));
    }

    #[test]
    fn test_daylight_detector_constants_and_power_clamping_parity() {
        use crate::block::blocks::redstone::daylight_detector::DaylightDetectorBlock;

        assert_eq!(DaylightDetectorBlock::MIN_POWER, 0);
        assert_eq!(DaylightDetectorBlock::MAX_POWER, 15);
        assert_eq!(DaylightDetectorBlock::UPDATE_INTERVAL_TICKS, 20);
        assert_eq!(DaylightDetectorBlock::SHAPE_HEIGHT, 6.0);
        assert_eq!(DaylightDetectorBlock::SUN_ANGLE_LERP_FACTOR, 0.2);

        // Clamping checks:
        // Midday (sun directly overhead, angle 0 rad): target * cos(0) = 15
        assert_eq!(
            DaylightDetectorBlock::calculate_signal_strength(15, 0.0, false),
            15
        );
        // Inverted at midday: 15 - 15 = 0
        assert_eq!(
            DaylightDetectorBlock::calculate_signal_strength(15, 0.0, true),
            0
        );
        // Inverted at midnight: 15 - 0 = 15
        assert_eq!(
            DaylightDetectorBlock::calculate_signal_strength(0, std::f32::consts::PI, true),
            15
        );
        // Midnight (angle PI rad, cos(PI) = -1): target <= 0
        assert_eq!(
            DaylightDetectorBlock::calculate_signal_strength(15, std::f32::consts::PI, false),
            0
        );
    }

