    #[test]
    fn test_trapped_chest_viewer_count_signal_and_direction_parity() {
        use crate::block::blocks::chests::TrappedChestBlock;
        use crate::block::entities::trapped_chest::TrappedChestBlockEntity;
        use pumpkin_data::BlockDirection;

        assert_eq!(TrappedChestBlock::MIN_POWER, 0);
        assert_eq!(TrappedChestBlock::MAX_POWER, 15);
        assert_eq!(TrappedChestBlockEntity::MIN_POWER, 0);
        assert_eq!(TrappedChestBlockEntity::MAX_POWER, 15);
        assert!(TrappedChestBlockEntity::EMITS_REDSTONE);

        // Viewer count to signal strength clamping (0..=15)
        assert_eq!(TrappedChestBlock::calculate_signal(0), 0);
        assert_eq!(TrappedChestBlock::calculate_signal(1), 1);
        assert_eq!(TrappedChestBlock::calculate_signal(7), 7);
        assert_eq!(TrappedChestBlock::calculate_signal(15), 15);
        assert_eq!(TrappedChestBlock::calculate_signal(16), 15);
        assert_eq!(TrappedChestBlock::calculate_signal(100), 15);

        // Strong power direction (only Up, powering the block underneath)
        assert!(TrappedChestBlock::emits_strong_power(BlockDirection::Up));
        assert!(!TrappedChestBlock::emits_strong_power(BlockDirection::Down));
        assert!(!TrappedChestBlock::emits_strong_power(BlockDirection::North));
        assert!(!TrappedChestBlock::emits_strong_power(BlockDirection::South));
        assert!(!TrappedChestBlock::emits_strong_power(BlockDirection::East));
        assert!(!TrappedChestBlock::emits_strong_power(BlockDirection::West));
    }

    #[test]
    fn test_target_block_timing_precision_and_power_parity() {
        use crate::block::blocks::redstone::target_block::TargetBlock;
        use pumpkin_data::entity::EntityType;
        use pumpkin_util::math::position::BlockPos;
        use pumpkin_util::math::vector3::Vector3;

        assert_eq!(TargetBlock::ACTIVATION_TICKS_ARROWS, 20);
        assert_eq!(TargetBlock::ACTIVATION_TICKS_OTHER, 8);
        assert_eq!(TargetBlock::MIN_POWER, 1);
        assert_eq!(TargetBlock::MAX_POWER, 15);
        assert_eq!(TargetBlock::BULLSEYE_MIN_DISTANCE, 30.0);
        assert!(!TargetBlock::emits_strong_power());

        // Activation ticks parity (arrows and tridents get 20 ticks, other projectiles get 8 ticks)
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::ARROW), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::SPECTRAL_ARROW), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::TRIDENT), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::SNOWBALL), 8);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::EGG), 8);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::ENDER_PEARL), 8);

        // Power calculation from hit coordinates:
        let block_pos = BlockPos::new(10, 64, -20);

        // Exact bullseye center on North face (x=10.5, y=64.5, z=-20.0) -> distance = 0.0 -> power = 15
        let center_hit = Vector3::new(10.5, 64.5, -20.0);
        assert_eq!(TargetBlock::calculate_hit_power(&center_hit, &block_pos), 15);

        // Slightly off center (x=10.5, y=64.8, z=-20.0) -> dy=0.3 -> distance = 0.3 -> factor = (0.5-0.3)/0.5 = 0.4 -> ceil(15*0.4) = 6
        let off_center_hit = Vector3::new(10.5, 64.8, -20.0);
        assert_eq!(TargetBlock::calculate_hit_power(&off_center_hit, &block_pos), 7);

        // Edge hit on North face (x=10.99, y=64.5, z=-20.0) -> dx=0.49 -> factor = (0.5-0.49)/0.5 = 0.02 -> power = 1
        let edge_hit = Vector3::new(10.99, 64.5, -20.0);
        assert_eq!(TargetBlock::calculate_hit_power(&edge_hit, &block_pos), 1);
    }

    #[test]
    fn test_sculk_sensor_timing_range_and_calibration_parity() {
        use crate::block::blocks::redstone::sculk_sensor::SculkSensorBlock;
        use crate::block::entities::calibrated_sculk_sensor::CalibratedSculkSensorBlockEntity;
        use crate::block::entities::sculk_sensor::SculkSensorBlockEntity;
        use pumpkin_data::block_properties::HorizontalFacing;
        use pumpkin_data::{BlockDirection, BlockId};

        // Active and Cooldown durations
        assert_eq!(SculkSensorBlock::ACTIVE_TICKS_REGULAR, 30);
        assert_eq!(SculkSensorBlock::ACTIVE_TICKS_CALIBRATED, 10);
        assert_eq!(SculkSensorBlock::COOLDOWN_TICKS, 10);
        assert_eq!(SculkSensorBlock::LISTENER_RANGE_REGULAR, 8);
        assert_eq!(SculkSensorBlock::LISTENER_RANGE_CALIBRATED, 16);

        // Block entity listener ranges
        assert_eq!(SculkSensorBlockEntity::LISTENER_RANGE, 8);
        assert_eq!(CalibratedSculkSensorBlockEntity::LISTENER_RANGE, 16);

        // Variant-based active ticks & listener ranges
        assert_eq!(SculkSensorBlock::get_active_ticks(BlockId::SCULK_SENSOR), 30);
        assert_eq!(SculkSensorBlock::get_active_ticks(BlockId::CALIBRATED_SCULK_SENSOR), 10);
        assert_eq!(SculkSensorBlock::get_listener_range(BlockId::SCULK_SENSOR), 8);
        assert_eq!(SculkSensorBlock::get_listener_range(BlockId::CALIBRATED_SCULK_SENSOR), 16);

        // Redstone strength based on vibration distance:
        // Regular (radius 8):
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(0.0, 8), 15);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(4.0, 8), 8);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(8.0, 8), 1);

        // Calibrated (radius 16):
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(0.0, 16), 15);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(8.0, 16), 8);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(16.0, 16), 1);

        // Calibrated directional output filtering:
        // Facing North => no output to North, outputs to all other directions
        assert!(!SculkSensorBlock::can_output_weak_power(BlockId::CALIBRATED_SCULK_SENSOR, Some(HorizontalFacing::North), BlockDirection::North));
        assert!(SculkSensorBlock::can_output_weak_power(BlockId::CALIBRATED_SCULK_SENSOR, Some(HorizontalFacing::North), BlockDirection::South));
        assert!(SculkSensorBlock::can_output_weak_power(BlockId::CALIBRATED_SCULK_SENSOR, Some(HorizontalFacing::North), BlockDirection::East));
        assert!(SculkSensorBlock::can_output_weak_power(BlockId::CALIBRATED_SCULK_SENSOR, Some(HorizontalFacing::North), BlockDirection::West));
        assert!(SculkSensorBlock::can_output_weak_power(BlockId::CALIBRATED_SCULK_SENSOR, Some(HorizontalFacing::North), BlockDirection::Up));
        assert!(SculkSensorBlock::can_output_weak_power(BlockId::CALIBRATED_SCULK_SENSOR, Some(HorizontalFacing::North), BlockDirection::Down));

        // Regular sensor outputs in all directions
        assert!(SculkSensorBlock::can_output_weak_power(BlockId::SCULK_SENSOR, None, BlockDirection::North));

        // Strong power direction (powers block beneath)
        assert!(SculkSensorBlock::emits_strong_power(BlockDirection::Up));
        assert!(!SculkSensorBlock::emits_strong_power(BlockDirection::Down));
        assert!(!SculkSensorBlock::emits_strong_power(BlockDirection::North));
    }

    #[test]
    fn test_redstone_torch_burnout_delays_and_signals_parity() {
        use crate::block::blocks::redstone::redstone_torch::RedstoneTorchBlock;
        use pumpkin_data::block_properties::HorizontalFacing;
        use pumpkin_data::BlockDirection;

        assert_eq!(RedstoneTorchBlock::RECENT_TOGGLE_TIMER, 60);
        assert_eq!(RedstoneTorchBlock::MAX_RECENT_TOGGLES, 8);
        assert_eq!(RedstoneTorchBlock::RESTART_DELAY, 160);
        assert_eq!(RedstoneTorchBlock::TOGGLE_DELAY, 2);
        assert_eq!(RedstoneTorchBlock::BURNOUT_EVENT, 1502);
        assert_eq!(RedstoneTorchBlock::POWER_ON, 15);
        assert_eq!(RedstoneTorchBlock::POWER_OFF, 0);

        // Burnout threshold check
        assert!(!RedstoneTorchBlock::is_burnt_out(0));
        assert!(!RedstoneTorchBlock::is_burnt_out(7));
        assert!(RedstoneTorchBlock::is_burnt_out(8));
        assert!(RedstoneTorchBlock::is_burnt_out(10));

        // Floor torch weak power (outputs everywhere except Up towards query from below)
        assert!(RedstoneTorchBlock::can_output_weak_power(false, None, BlockDirection::North));
        assert!(RedstoneTorchBlock::can_output_weak_power(false, None, BlockDirection::South));
        assert!(RedstoneTorchBlock::can_output_weak_power(false, None, BlockDirection::East));
        assert!(RedstoneTorchBlock::can_output_weak_power(false, None, BlockDirection::West));
        assert!(RedstoneTorchBlock::can_output_weak_power(false, None, BlockDirection::Down));
        assert!(!RedstoneTorchBlock::can_output_weak_power(false, None, BlockDirection::Up));

        // Wall torch weak power (attached facing North -> outputs everywhere except into its attached face North)
        assert!(!RedstoneTorchBlock::can_output_weak_power(true, Some(HorizontalFacing::North), BlockDirection::North));
        assert!(RedstoneTorchBlock::can_output_weak_power(true, Some(HorizontalFacing::North), BlockDirection::South));
        assert!(RedstoneTorchBlock::can_output_weak_power(true, Some(HorizontalFacing::North), BlockDirection::East));
        assert!(RedstoneTorchBlock::can_output_weak_power(true, Some(HorizontalFacing::North), BlockDirection::West));
        assert!(RedstoneTorchBlock::can_output_weak_power(true, Some(HorizontalFacing::North), BlockDirection::Up));
        assert!(RedstoneTorchBlock::can_output_weak_power(true, Some(HorizontalFacing::North), BlockDirection::Down));

        // Strong power: only Down (powering the block directly above it)
        assert!(RedstoneTorchBlock::emits_strong_power(BlockDirection::Down));
        assert!(!RedstoneTorchBlock::emits_strong_power(BlockDirection::Up));
        assert!(!RedstoneTorchBlock::emits_strong_power(BlockDirection::North));
    }

    #[test]
    fn test_lectern_pulse_duration_and_comparator_signal_parity() {
        use crate::block::blocks::lectern::LecternBlock;
        use crate::block::entities::lectern::{calculate_lectern_comparator_output, LecternBlockEntity};
        use pumpkin_data::BlockDirection;

        assert_eq!(LecternBlock::PAGE_CHANGE_IMPULSE_TICKS, 2);
        assert_eq!(LecternBlock::PAGE_TURN_PULSE_TICKS, 2);
        assert_eq!(LecternBlock::PAGE_CHANGE_EVENT, 1043);
        assert_eq!(LecternBlock::POWER_ON, 15);
        assert_eq!(LecternBlock::POWER_OFF, 0);

        assert_eq!(LecternBlockEntity::MIN_COMPARATOR_SIGNAL, 1);
        assert_eq!(LecternBlockEntity::MAX_COMPARATOR_SIGNAL, 15);

        // Strong power direction: only Up (powers block beneath)
        assert!(LecternBlock::emits_strong_power(BlockDirection::Up));
        assert!(!LecternBlock::emits_strong_power(BlockDirection::Down));
        assert!(!LecternBlock::emits_strong_power(BlockDirection::North));

        // Comparator signal calculations:
        // No book => 0
        assert_eq!(calculate_lectern_comparator_output(false, 0, 5), 0);
        assert_eq!(calculate_lectern_comparator_output(true, 0, 0), 0);

        // Single page book => always 15
        assert_eq!(calculate_lectern_comparator_output(true, 0, 1), 15);

        // 15 page book: page 0 => 1, page 7 => 8, page 14 => 15
        assert_eq!(calculate_lectern_comparator_output(true, 0, 15), 1);
        assert_eq!(calculate_lectern_comparator_output(true, 7, 15), 8);
        assert_eq!(calculate_lectern_comparator_output(true, 14, 15), 15);

        // Clamping if page exceeds page_count - 1
        assert_eq!(calculate_lectern_comparator_output(true, 20, 15), 15);
    }
    #[test]
    fn test_chiseled_bookshelf_slot_selection_and_comparator_parity() {
        use crate::block::blocks::chiseled_bookshelf::ChiseledBookshelfBlock;
        use crate::block::entities::chiseled_bookshelf::ChiseledBookshelfBlockEntity;
        use pumpkin_data::block_properties::ChiseledBookshelfLikeProperties;
        use pumpkin_data::Block;

        // Constants verification
        assert_eq!(ChiseledBookshelfBlock::MAX_BOOKS_IN_STORAGE, 6);
        assert_eq!(ChiseledBookshelfBlock::BOOKS_PER_ROW, 3);
        assert_eq!(ChiseledBookshelfBlock::ROWS, 2);
        assert_eq!(ChiseledBookshelfBlock::COLUMNS, 3);
        assert_eq!(ChiseledBookshelfBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(ChiseledBookshelfBlock::MAX_COMPARATOR_OUTPUT, 6);

        assert_eq!(ChiseledBookshelfBlockEntity::DEFAULT_LAST_INTERACTED_SLOT, -1);
        assert_eq!(ChiseledBookshelfBlockEntity::MAX_BOOKS_IN_STORAGE, 6);
        assert_eq!(ChiseledBookshelfBlockEntity::BOOKS_PER_ROW, 3);
        assert_eq!(ChiseledBookshelfBlockEntity::ROWS, 2);
        assert_eq!(ChiseledBookshelfBlockEntity::COLUMNS, 3);
        assert_eq!(ChiseledBookshelfBlockEntity::MAX_STACK_SIZE, 1);
        assert_eq!(ChiseledBookshelfBlockEntity::INVENTORY_SIZE, 6);

        // Section calculation (matching vanilla SelectableSlotContainer)
        assert_eq!(ChiseledBookshelfBlock::get_section(0.0, 3), 0);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.2, 3), 0);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.33, 3), 0);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.35, 3), 1);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.5, 3), 1);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.66, 3), 1);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.67, 3), 2);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.99, 3), 2);
        assert_eq!(ChiseledBookshelfBlock::get_section(1.0, 3), 2);

        // Rows calculation (2 rows)
        assert_eq!(ChiseledBookshelfBlock::get_section(0.0, 2), 0);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.49, 2), 0);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.5, 2), 1);
        assert_eq!(ChiseledBookshelfBlock::get_section(1.0, 2), 1);

        // Hit slot calculation (x in 0..1, y in 0..1)
        // Top row (y = 0.8 => 1.0 - y = 0.2 => row 0)
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.1, 0.8), 0);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.5, 0.8), 1);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.9, 0.8), 2);

        // Bottom row (y = 0.2 => 1.0 - y = 0.8 => row 1)
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.1, 0.2), 3);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.5, 0.2), 4);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.9, 0.2), 5);

        // Comparator output formula: last_interacted_slot + 1 for 0..5, else 0
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(-1), 0);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(0), 1);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(1), 2);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(2), 3);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(3), 4);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(4), 5);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(5), 6);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(6), 0);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(-5), 0);

        // Slot bitmask and properties helpers
        let mut props = ChiseledBookshelfLikeProperties::default(&Block::CHISELED_BOOKSHELF);
        assert_eq!(ChiseledBookshelfBlock::slot_bitmask_from_properties(&props), 0);
        assert_eq!(ChiseledBookshelfBlock::get_occupied_slot_count(&props), 0);

        props.slot_0_occupied = true;
        props.slot_2_occupied = true;
        props.slot_5_occupied = true;
        assert_eq!(ChiseledBookshelfBlock::slot_bitmask_from_properties(&props), (1 << 0) | (1 << 2) | (1 << 5));
        assert_eq!(ChiseledBookshelfBlock::get_occupied_slot_count(&props), 3);
        assert!(ChiseledBookshelfBlock::is_slot_occupied(&props, 0));
        assert!(!ChiseledBookshelfBlock::is_slot_occupied(&props, 1));
        assert!(ChiseledBookshelfBlock::is_slot_occupied(&props, 2));
        assert!(!ChiseledBookshelfBlock::is_slot_occupied(&props, 3));
        assert!(!ChiseledBookshelfBlock::is_slot_occupied(&props, 4));
        assert!(ChiseledBookshelfBlock::is_slot_occupied(&props, 5));
        assert!(!ChiseledBookshelfBlock::is_slot_occupied(&props, 6));
    }
#[test]
    fn test_composter_fill_levels_probabilities_and_comparator_parity() {
        use crate::block::blocks::composter::ComposterBlock;
        use pumpkin_data::BlockDirection;

        // Constants verification
        assert_eq!(ComposterBlock::READY, 8);
        assert_eq!(ComposterBlock::MIN_LEVEL, 0);
        assert_eq!(ComposterBlock::MAX_LEVEL, 7);
        assert_eq!(ComposterBlock::NUM_LEVELS, 9);
        assert_eq!(ComposterBlock::FULL_COMPOSTING_TICKS, 20);
        assert_eq!(ComposterBlock::COMPOSTER_FILL_EVENT, 1500);
        assert_eq!(ComposterBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(ComposterBlock::MAX_COMPARATOR_OUTPUT, 8);

        // Comparator output matches fill level 0..=8
        for level in 0..=8 {
            assert_eq!(ComposterBlock::calculate_comparator_output(level), level);
        }
        // Clamping above ready (safety)
        assert_eq!(ComposterBlock::calculate_comparator_output(9), 8);
        assert_eq!(ComposterBlock::calculate_comparator_output(15), 8);

        // Ready and can compost more states
        for level in 0..=7 {
            assert!(!ComposterBlock::is_ready(level));
        }
        assert!(ComposterBlock::is_ready(8));

        for level in 0..=6 {
            assert!(ComposterBlock::can_compost_more(level));
        }
        assert!(!ComposterBlock::can_compost_more(7));
        assert!(!ComposterBlock::can_compost_more(8));

        // Hopper insertion (only from Up face and when level < 7)
        for level in 0..=6 {
            assert!(ComposterBlock::can_hopper_insert(level, BlockDirection::Up));
            assert!(!ComposterBlock::can_hopper_insert(level, BlockDirection::Down));
            assert!(!ComposterBlock::can_hopper_insert(level, BlockDirection::North));
        }
        assert!(!ComposterBlock::can_hopper_insert(7, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_insert(8, BlockDirection::Up));

        // Hopper extraction (only from Down face and when level == 8 READY)
        for level in 0..=7 {
            assert!(!ComposterBlock::can_hopper_extract(level, BlockDirection::Down));
        }
        assert!(ComposterBlock::can_hopper_extract(8, BlockDirection::Down));
        assert!(!ComposterBlock::can_hopper_extract(8, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_extract(8, BlockDirection::North));

        // Composting chance logic
        // 30% chance item (seeds, saplings, leaves)
        assert!(ComposterBlock::should_level_increase(0, 0.3, 0.1));
        assert!(!ComposterBlock::should_level_increase(0, 0.3, 0.5));
        // Level 0 does not automatically succeed unless chance passes (vanilla parity)
        assert!(!ComposterBlock::should_level_increase(0, 0.3, 0.35));

        // 100% chance item (cake, pumpkin pie)
        assert!(ComposterBlock::should_level_increase(0, 1.0, 0.99));
        assert!(ComposterBlock::should_level_increase(6, 1.0, 0.5));

        // Full composter (level >= 7) cannot increase further via composting items
        assert!(!ComposterBlock::should_level_increase(7, 1.0, 0.0));
        assert!(!ComposterBlock::should_level_increase(8, 1.0, 0.0));
    }
#[test]
    fn test_cauldron_fluid_types_levels_and_comparator_parity() {
        use crate::block::blocks::cauldron::CauldronBlock;
        use pumpkin_data::block_properties::WaterCauldronLikeProperties;
        use pumpkin_data::{Block, BlockId};

        // Constants verification
        assert_eq!(CauldronBlock::MIN_FILL_LEVEL, 1);
        assert_eq!(CauldronBlock::MAX_FILL_LEVEL, 3);
        assert_eq!(CauldronBlock::LAVA_SIGNAL, 3);
        assert_eq!(CauldronBlock::EMPTY_SIGNAL, 0);
        assert_eq!(CauldronBlock::FLOOR_LEVEL, 4);
        assert!((CauldronBlock::RAIN_FILL_CHANCE - 0.05).abs() < 1e-6);
        assert!((CauldronBlock::POWDER_SNOW_FILL_CHANCE - 0.10).abs() < 1e-6);
        assert_eq!(CauldronBlock::DRIP_WATER_EVENT, 1047);

        // Comparator signals:
        // Empty cauldron: 0
        assert_eq!(
            CauldronBlock::calculate_comparator_output(BlockId::CAULDRON, Block::CAULDRON.default_state.id),
            0
        );

        // Water cauldron: 1, 2, 3
        let water_cauldron = &Block::WATER_CAULDRON;
        for level in 1..=3 {
            let mut props = WaterCauldronLikeProperties::default(water_cauldron);
            props.level = level;
            let state_id = props.to_state_id(water_cauldron);
            assert_eq!(
                CauldronBlock::calculate_comparator_output(BlockId::WATER_CAULDRON, state_id),
                level
            );
            assert_eq!(
                CauldronBlock::is_full(BlockId::WATER_CAULDRON, state_id),
                level == 3
            );
            let expected_height = (6.0 + f64::from(level) * 3.0) / 16.0;
            assert!(
                (CauldronBlock::get_content_height(BlockId::WATER_CAULDRON, state_id) - expected_height).abs() < 1e-6
            );
        }

        // Powder snow cauldron: 1, 2, 3
        let snow_cauldron = &Block::POWDER_SNOW_CAULDRON;
        for level in 1..=3 {
            let mut props = WaterCauldronLikeProperties::default(snow_cauldron);
            props.level = level;
            let state_id = props.to_state_id(snow_cauldron);
            assert_eq!(
                CauldronBlock::calculate_comparator_output(BlockId::POWDER_SNOW_CAULDRON, state_id),
                level
            );
            assert_eq!(
                CauldronBlock::is_full(BlockId::POWDER_SNOW_CAULDRON, state_id),
                level == 3
            );
            let expected_height = (6.0 + f64::from(level) * 3.0) / 16.0;
            assert!(
                (CauldronBlock::get_content_height(BlockId::POWDER_SNOW_CAULDRON, state_id) - expected_height).abs() < 1e-6
            );
        }

        // Lava cauldron: always 3 signal, always full, content height 0.9375
        let lava_state = Block::LAVA_CAULDRON.default_state.id;
        assert_eq!(
            CauldronBlock::calculate_comparator_output(BlockId::LAVA_CAULDRON, lava_state),
            3
        );
        assert!(CauldronBlock::is_full(BlockId::LAVA_CAULDRON, lava_state));
        assert!((CauldronBlock::get_content_height(BlockId::LAVA_CAULDRON, lava_state) - 0.9375).abs() < 1e-6);

        // Extinguish fire check
        assert!(CauldronBlock::can_extinguish_fire(BlockId::WATER_CAULDRON));
        assert!(CauldronBlock::can_extinguish_fire(BlockId::POWDER_SNOW_CAULDRON));
        assert!(!CauldronBlock::can_extinguish_fire(BlockId::CAULDRON));
        assert!(!CauldronBlock::can_extinguish_fire(BlockId::LAVA_CAULDRON));

        // Precipitation fill chances
        assert!(CauldronBlock::should_rain_fill(0.01));
        assert!(!CauldronBlock::should_rain_fill(0.06));
        assert!(CauldronBlock::should_snow_fill(0.05));
        assert!(!CauldronBlock::should_snow_fill(0.15));
    }
#[test]
    fn test_crafter_redstone_triggering_disabled_slots_and_comparator_parity() {
        use crate::block::blocks::redstone::crafter::CrafterBlock;
        use crate::block::entities::crafter::CrafterBlockEntity;

        // Constants verification
        assert_eq!(CrafterBlock::CRAFTING_TICK_DELAY, 4);
        assert_eq!(CrafterBlock::MAX_CRAFTING_TICKS, 6);
        assert_eq!(CrafterBlock::CONTAINER_SIZE, 9);
        assert_eq!(CrafterBlock::CONTAINER_WIDTH, 3);
        assert_eq!(CrafterBlock::CONTAINER_HEIGHT, 3);
        assert_eq!(CrafterBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(CrafterBlock::MAX_COMPARATOR_OUTPUT, 9);

        assert_eq!(CrafterBlockEntity::SLOT_DISABLED, 1);
        assert_eq!(CrafterBlockEntity::SLOT_ENABLED, 0);
        assert_eq!(CrafterBlockEntity::DATA_TRIGGERED, 9);
        assert_eq!(CrafterBlockEntity::NUM_DATA, 10);
        assert_eq!(CrafterBlockEntity::DEFAULT_CRAFTING_TICKS_REMAINING, 0);
        assert!(!CrafterBlockEntity::DEFAULT_TRIGGERED);

        // Comparator signal calculations
        assert_eq!(CrafterBlock::calculate_comparator_signal(0, 0), 0);
        assert_eq!(CrafterBlock::calculate_comparator_signal(3, 2), 5);
        assert_eq!(CrafterBlock::calculate_comparator_signal(9, 0), 9);
        assert_eq!(CrafterBlock::calculate_comparator_signal(0, 9), 9);
        assert_eq!(CrafterBlock::calculate_comparator_signal(5, 4), 9);
        assert_eq!(CrafterBlock::calculate_comparator_signal(6, 6), 9);

        // State array comparator calculation
        let mut occupied = [false; 9];
        let mut disabled = [false; 9];
        assert_eq!(CrafterBlock::calculate_signal_from_states(&occupied, &disabled), 0);

        occupied[0] = true;
        occupied[1] = true;
        disabled[2] = true;
        disabled[4] = true;
        // Slots 0, 1 occupied, slots 2, 4 disabled -> 4
        assert_eq!(CrafterBlock::calculate_signal_from_states(&occupied, &disabled), 4);

        // Overlapping slot (occupied + disabled) counts as 1 slot active
        disabled[0] = true;
        assert_eq!(CrafterBlock::calculate_signal_from_states(&occupied, &disabled), 4);

        // Bitmask conversions
        let mut test_disabled = [false; 9];
        test_disabled[0] = true;
        test_disabled[2] = true;
        test_disabled[8] = true;
        let expected_mask = (1 << 0) | (1 << 2) | (1 << 8);
        assert_eq!(CrafterBlock::disabled_slots_to_bitmask(&test_disabled), expected_mask);

        let roundtrip = CrafterBlock::bitmask_to_disabled_slots(expected_mask);
        assert_eq!(roundtrip, test_disabled);

        // Crafting slot validity
        assert!(CrafterBlock::is_slot_valid_for_craft(true, false));
        assert!(!CrafterBlock::is_slot_valid_for_craft(true, true));
        assert!(!CrafterBlock::is_slot_valid_for_craft(false, false));
        assert!(!CrafterBlock::is_slot_valid_for_craft(false, true));
    }
#[test]
    fn test_hopper_redstone_locking_timing_and_comparator_parity() {
        use crate::block::blocks::hopper::HopperBlock;
        use crate::block::entities::hopper::HopperBlockEntity;
        use pumpkin_data::block_properties::FacingHopper;
        use pumpkin_data::BlockDirection;

        // Constants verification
        assert_eq!(HopperBlock::HOPPER_CONTAINER_SIZE, 5);
        assert_eq!(HopperBlock::CONTAINER_SIZE, 5);
        assert_eq!(HopperBlock::MOVE_ITEM_SPEED, 8);
        assert_eq!(HopperBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(HopperBlock::MAX_COMPARATOR_OUTPUT, 15);

        assert_eq!(HopperBlockEntity::INVENTORY_SIZE, 5);
        assert_eq!(HopperBlockEntity::CONTAINER_SIZE, 5);
        assert_eq!(HopperBlockEntity::MOVE_ITEM_SPEED, 8);
        assert_eq!(HopperBlockEntity::NO_COOLDOWN_TIME, -1);

        // Placement facing resolution
        assert_eq!(HopperBlock::calculate_facing_from_direction(BlockDirection::North), FacingHopper::North);
        assert_eq!(HopperBlock::calculate_facing_from_direction(BlockDirection::East), FacingHopper::East);
        assert_eq!(HopperBlock::calculate_facing_from_direction(BlockDirection::South), FacingHopper::South);
        assert_eq!(HopperBlock::calculate_facing_from_direction(BlockDirection::West), FacingHopper::West);
        assert_eq!(HopperBlock::calculate_facing_from_direction(BlockDirection::Up), FacingHopper::Down);
        assert_eq!(HopperBlock::calculate_facing_from_direction(BlockDirection::Down), FacingHopper::Down);

        // Redstone locking (enabled state)
        assert!(HopperBlock::is_enabled(false));  // unpowered => enabled (unlocked)
        assert!(!HopperBlock::is_enabled(true));  // powered => disabled (locked)

        // Comparator signal calculations (standard 5-slot container formula)
        // 1. Completely empty
        let empty_counts = [0u8; 5];
        let max_stacks = [64u8; 5];
        assert_eq!(HopperBlock::calculate_container_comparator_output(&empty_counts, &max_stacks), 0);

        // 2. Single item (1/64 in slot 0) => minimum signal 1
        let mut single_item = [0u8; 5];
        single_item[0] = 1;
        assert_eq!(HopperBlock::calculate_container_comparator_output(&single_item, &max_stacks), 1);

        // 3. Exactly 1 full stack of 64 in slot 0 => fullness = 0.2 => floor(0.2 * 14) + 1 = 3
        let mut one_stack = [0u8; 5];
        one_stack[0] = 64;
        assert_eq!(HopperBlock::calculate_container_comparator_output(&one_stack, &max_stacks), 3);

        // 4. Completely full (5 stacks of 64) => fullness = 1.0 => floor(14) + 1 = 15
        let full_stacks = [64u8; 5];
        assert_eq!(HopperBlock::calculate_container_comparator_output(&full_stacks, &max_stacks), 15);

        // 5. Single unstackable item (e.g. sword, max_stack = 1) in slot 0 => fullness = 0.2 => signal 3
        let unstackable_counts = [1, 0, 0, 0, 0];
        let unstackable_max = [1, 64, 64, 64, 64];
        assert_eq!(HopperBlock::calculate_container_comparator_output(&unstackable_counts, &unstackable_max), 3);
    }
#[test]
    fn test_repeater_delays_locking_and_output_parity() {
        use crate::block::blocks::redstone::repeater::RepeaterBlock;
        use pumpkin_data::block_properties::HorizontalFacing;
        use pumpkin_data::{BlockDirection, BlockId};

        // Constants verification
        assert_eq!(RepeaterBlock::MIN_DELAY, 1);
        assert_eq!(RepeaterBlock::MAX_DELAY, 4);
        assert_eq!(RepeaterBlock::DELAY_MULTIPLIER, 2);
        assert_eq!(RepeaterBlock::POWER_ON, 15);
        assert_eq!(RepeaterBlock::POWER_OFF, 0);
        assert_eq!(RepeaterBlock::DEFAULT_DELAY, 1);
        assert!(!RepeaterBlock::DEFAULT_LOCKED);
        assert!(!RepeaterBlock::DEFAULT_POWERED);

        // Delay ticks calculation (delay setting * 2 game ticks)
        assert_eq!(RepeaterBlock::calculate_delay_ticks(1), 2);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(2), 4);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(3), 6);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(4), 8);

        // Clamping checks
        assert_eq!(RepeaterBlock::calculate_delay_ticks(0), 2);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(5), 8);

        // Delay cycling (1 -> 2 -> 3 -> 4 -> 1)
        assert_eq!(RepeaterBlock::cycle_delay(1), 2);
        assert_eq!(RepeaterBlock::cycle_delay(2), 3);
        assert_eq!(RepeaterBlock::cycle_delay(3), 4);
        assert_eq!(RepeaterBlock::cycle_delay(4), 1);
        assert_eq!(RepeaterBlock::cycle_delay(5), 1);

        // Output power
        assert_eq!(RepeaterBlock::get_output_power(true), 15);
        assert_eq!(RepeaterBlock::get_output_power(false), 0);

        // Output direction (only in facing direction)
        assert!(RepeaterBlock::emits_power_in_direction(HorizontalFacing::North, BlockDirection::North));
        assert!(!RepeaterBlock::emits_power_in_direction(HorizontalFacing::North, BlockDirection::South));
        assert!(!RepeaterBlock::emits_power_in_direction(HorizontalFacing::North, BlockDirection::East));
        assert!(!RepeaterBlock::emits_power_in_direction(HorizontalFacing::North, BlockDirection::West));
        assert!(!RepeaterBlock::emits_power_in_direction(HorizontalFacing::North, BlockDirection::Up));
        assert!(!RepeaterBlock::emits_power_in_direction(HorizontalFacing::North, BlockDirection::Down));

        // Locking sides (must be orthogonal horizontal directions)
        // Facing North: locked from East and West
        assert!(RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::East));
        assert!(RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::West));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::North));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::South));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::Up));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::Down));

        // Facing East: locked from North and South
        assert!(RepeaterBlock::is_locking_side(HorizontalFacing::East, BlockDirection::North));
        assert!(RepeaterBlock::is_locking_side(HorizontalFacing::East, BlockDirection::South));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::East, BlockDirection::East));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::East, BlockDirection::West));

        // Side locking block types (only diodes: repeater and comparator)
        assert!(RepeaterBlock::can_be_locked_by_block(BlockId::REPEATER));
        assert!(RepeaterBlock::can_be_locked_by_block(BlockId::COMPARATOR));
        assert!(!RepeaterBlock::can_be_locked_by_block(BlockId::REDSTONE_WIRE));
        assert!(!RepeaterBlock::can_be_locked_by_block(BlockId::REDSTONE_TORCH));
        assert!(!RepeaterBlock::can_be_locked_by_block(BlockId::STONE));
    }
#[test]
    fn test_comparator_mode_signal_and_item_frame_parity() {
        use crate::block::blocks::redstone::comparator::ComparatorBlock;
        use crate::block::entities::comparator::ComparatorBlockEntity;

        // Constants verification
        assert_eq!(ComparatorBlock::DELAY, 2);
        assert!((ComparatorBlock::CLICK_VOLUME - 0.3).abs() < 1e-6);
        assert!((ComparatorBlock::CLICK_PITCH_COMPARE - 0.5).abs() < 1e-6);
        assert!((ComparatorBlock::CLICK_PITCH_SUBTRACT - 0.55).abs() < 1e-6);
        assert_eq!(ComparatorBlock::POWER_ON, 15);
        assert_eq!(ComparatorBlock::POWER_OFF, 0);
        assert_eq!(ComparatorBlock::DEFAULT_OUTPUT, 0);
        assert_eq!(ComparatorBlockEntity::DEFAULT_OUTPUT, 0);

        // Click pitch calculation
        assert!((ComparatorBlock::get_click_pitch(false) - 0.5).abs() < 1e-6);
        assert!((ComparatorBlock::get_click_pitch(true) - 0.55).abs() < 1e-6);

        // Signal in COMPARE mode (is_subtract = false)
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 5, false), 10);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 10, false), 10);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 12, false), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(0, 0, false), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(0, 5, false), 0);

        // Signal in SUBTRACT mode (is_subtract = true)
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 3, true), 7);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 10, true), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 12, true), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(0, 0, true), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(0, 5, true), 0);

        // Powered state logic (should_turn_on)
        // 1. input > side => ON in both modes
        assert!(ComparatorBlock::should_turn_on(10, 5, false));
        assert!(ComparatorBlock::should_turn_on(10, 5, true));

        // 2. input == side => ON in Compare, OFF in Subtract
        assert!(ComparatorBlock::should_turn_on(10, 10, false));
        assert!(!ComparatorBlock::should_turn_on(10, 10, true));

        // 3. input < side => OFF in both modes
        assert!(!ComparatorBlock::should_turn_on(8, 10, false));
        assert!(!ComparatorBlock::should_turn_on(8, 10, true));

        // 4. input == 0 => OFF in both modes
        assert!(!ComparatorBlock::should_turn_on(0, 0, false));
        assert!(!ComparatorBlock::should_turn_on(0, 0, true));

        // Item frame output (1 + rotation % 8 if has item, 0 if empty)
        assert_eq!(ComparatorBlock::calculate_item_frame_output(false, 0), 0);
        assert_eq!(ComparatorBlock::calculate_item_frame_output(false, 4), 0);

        for rot in 0..8 {
            assert_eq!(ComparatorBlock::calculate_item_frame_output(true, rot), rot + 1);
        }
        // Rotation modulo 8 wrapping
        assert_eq!(ComparatorBlock::calculate_item_frame_output(true, 8), 1);
        assert_eq!(ComparatorBlock::calculate_item_frame_output(true, 9), 2);
    }
#[test]
    fn test_daylight_detector_signals_modes_weather_and_power_parity() {
        use crate::block::blocks::redstone::daylight_detector::DaylightDetectorBlock;
        use crate::block::entities::daylight_detector::DaylightDetectorBlockEntity;

        // Constants verification
        assert_eq!(DaylightDetectorBlock::MIN_POWER, 0);
        assert_eq!(DaylightDetectorBlock::MAX_POWER, 15);
        assert_eq!(DaylightDetectorBlock::DEFAULT_POWER, 0);
        assert!(!DaylightDetectorBlock::DEFAULT_INVERTED);
        assert_eq!(DaylightDetectorBlock::UPDATE_INTERVAL_TICKS, 20);
        assert!((DaylightDetectorBlock::SHAPE_HEIGHT - 6.0).abs() < 1e-6);
        assert_eq!(DaylightDetectorBlock::RAIN_SKY_DARKEN_REDUCTION, 5);
        assert_eq!(DaylightDetectorBlock::THUNDER_SKY_DARKEN_REDUCTION, 5);
        assert_eq!(DaylightDetectorBlockEntity::TICK_INTERVAL_TICKS, 20);

        // Does NOT emit strong power (vanilla does not override getDirectSignal)
        assert!(!DaylightDetectorBlock::emits_strong_power());

        // Weather darkening calculation
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, false, false), 15);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, true, false), 10);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, false, true), 10);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, true, true), 5);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(4, true, false), 0);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(0, false, false), 0);

        // Inverted mode signals (15 - effective sky brightness)
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(15), 0);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(10), 5);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(5), 10);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(0), 15);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(-5), 15);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(20), 0);

        // Normal mode signal at noon (sun angle 0 rad)
        assert_eq!(DaylightDetectorBlock::calculate_normal_signal(15, 0.0), 15);
        assert_eq!(DaylightDetectorBlock::calculate_normal_signal(10, 0.0), 10);
        assert_eq!(DaylightDetectorBlock::calculate_normal_signal(0, 0.0), 0);

        // Check equivalence with calculate_signal_strength
        assert_eq!(
            DaylightDetectorBlock::calculate_signal_strength(15, 0.0, false),
            DaylightDetectorBlock::calculate_normal_signal(15, 0.0)
        );
        assert_eq!(
            DaylightDetectorBlock::calculate_signal_strength(15, 0.0, true),
            DaylightDetectorBlock::calculate_inverted_signal(15)
        );
    }

    #[test]
    fn test_observer_pulse_timing_facing_and_power_parity() {
        use crate::block::blocks::redstone::observer::ObserverBlock;
        use pumpkin_data::BlockDirection;
        use pumpkin_data::block_properties::Facing;

        // Constants verification
        assert_eq!(ObserverBlock::PULSE_DURATION, 2);
        assert_eq!(ObserverBlock::DETECTION_DELAY, 2);
        assert_eq!(ObserverBlock::POWER_ON, 15);
        assert_eq!(ObserverBlock::POWER_OFF, 0);
        assert!(!ObserverBlock::DEFAULT_POWERED);
        assert_eq!(ObserverBlock::DEFAULT_FACING, Facing::South);

        // Power signal logic
        assert_eq!(ObserverBlock::get_power_signal(true), 15);
        assert_eq!(ObserverBlock::get_power_signal(false), 0);

        // Observed and output direction logic
        let directions = [
            (BlockDirection::North, BlockDirection::South),
            (BlockDirection::South, BlockDirection::North),
            (BlockDirection::East, BlockDirection::West),
            (BlockDirection::West, BlockDirection::East),
            (BlockDirection::Up, BlockDirection::Down),
            (BlockDirection::Down, BlockDirection::Up),
        ];

        for (facing, opposite) in directions {
            assert_eq!(ObserverBlock::get_observed_direction(facing), facing);
            assert_eq!(ObserverBlock::get_output_direction(facing), opposite);

            // Power is only emitted in the observer's facing direction (from back to querying block)
            assert!(ObserverBlock::emits_power_in_direction(facing, facing));
            assert!(!ObserverBlock::emits_power_in_direction(facing, opposite));

            // Neighbor updates are only observed when matching facing direction
            assert!(ObserverBlock::is_observed_direction(facing, facing));
            assert!(!ObserverBlock::is_observed_direction(facing, opposite));
        }

        // Placement facing respects 6-way entity facing order (including Up and Down)
        let order_up = [Facing::Up, Facing::North, Facing::South, Facing::East, Facing::West, Facing::Down];
        assert_eq!(ObserverBlock::calculate_facing_from_player(&order_up), Facing::Up);

        let order_down = [Facing::Down, Facing::North, Facing::South, Facing::East, Facing::West, Facing::Up];
        assert_eq!(ObserverBlock::calculate_facing_from_player(&order_down), Facing::Down);

        let order_north = [Facing::North, Facing::Up, Facing::Down, Facing::South, Facing::East, Facing::West];
        assert_eq!(ObserverBlock::calculate_facing_from_player(&order_north), Facing::North);
    }

    #[test]
    fn test_piston_push_limit_reactions_stickiness_and_facing_parity() {
        use crate::block::blocks::piston::piston::PistonBlock;
        use pumpkin_data::block_properties::Facing;
        use pumpkin_data::block_state::PistonBehavior;
        use pumpkin_data::{Block, BlockDirection};

        // Constants verification (Vanilla: PistonStructureResolver.MAX_PUSH_DEPTH = 12)
        assert_eq!(PistonBlock::MAX_PUSH_LIMIT, 12);
        assert_eq!(PistonBlock::TRIGGER_EXTEND, 0);
        assert_eq!(PistonBlock::TRIGGER_CONTRACT, 1);
        assert_eq!(PistonBlock::TRIGGER_DROP, 2);
        assert!((PistonBlock::PLATFORM_THICKNESS - 4.0).abs() < 1e-6);
        assert!(!PistonBlock::DEFAULT_EXTENDED);
        assert_eq!(PistonBlock::DEFAULT_FACING, Facing::North);

        // Stickiness verification (Honey and Slime do not stick to each other)
        assert!(PistonBlock::is_sticky_block(&Block::SLIME_BLOCK));
        assert!(PistonBlock::is_sticky_block(&Block::HONEY_BLOCK));
        assert!(!PistonBlock::is_sticky_block(&Block::STONE));
        assert!(!PistonBlock::is_sticky_block(&Block::DIRT));
        assert!(!PistonBlock::is_sticky_block(&Block::AIR));

        assert!(!PistonBlock::can_stick_to_each_other(&Block::SLIME_BLOCK, &Block::HONEY_BLOCK));
        assert!(!PistonBlock::can_stick_to_each_other(&Block::HONEY_BLOCK, &Block::SLIME_BLOCK));
        assert!(PistonBlock::can_stick_to_each_other(&Block::SLIME_BLOCK, &Block::SLIME_BLOCK));
        assert!(PistonBlock::can_stick_to_each_other(&Block::HONEY_BLOCK, &Block::HONEY_BLOCK));
        assert!(PistonBlock::can_stick_to_each_other(&Block::SLIME_BLOCK, &Block::STONE));
        assert!(PistonBlock::can_stick_to_each_other(&Block::HONEY_BLOCK, &Block::STONE));
        assert!(!PistonBlock::can_stick_to_each_other(&Block::STONE, &Block::DIRT));

        // Piston push reactions
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Destroy, true, BlockDirection::North, BlockDirection::North),
            Some(true)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Destroy, false, BlockDirection::North, BlockDirection::North),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Block, true, BlockDirection::North, BlockDirection::North),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::PushOnly, false, BlockDirection::North, BlockDirection::North),
            Some(true)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::PushOnly, false, BlockDirection::North, BlockDirection::South),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Ignore, false, BlockDirection::North, BlockDirection::North),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Normal, false, BlockDirection::North, BlockDirection::North),
            None
        );

        // Immovable block types
        assert!(!PistonBlock::is_pushable_block_type(&Block::OBSIDIAN));
        assert!(!PistonBlock::is_pushable_block_type(&Block::CRYING_OBSIDIAN));
        assert!(!PistonBlock::is_pushable_block_type(&Block::RESPAWN_ANCHOR));
        assert!(!PistonBlock::is_pushable_block_type(&Block::REINFORCED_DEEPSLATE));
        assert!(PistonBlock::is_pushable_block_type(&Block::STONE));
        assert!(PistonBlock::is_pushable_block_type(&Block::OAK_PLANKS));

        // Placement facing: faces opposite to nearest looking direction (including vertical)
        let order_down = [Facing::Down, Facing::North, Facing::South, Facing::East, Facing::West, Facing::Up];
        assert_eq!(PistonBlock::calculate_facing_from_player(&order_down), Facing::Up);

        let order_up = [Facing::Up, Facing::North, Facing::South, Facing::East, Facing::West, Facing::Down];
        assert_eq!(PistonBlock::calculate_facing_from_player(&order_up), Facing::Down);

        let order_north = [Facing::North, Facing::Up, Facing::Down, Facing::South, Facing::East, Facing::West];
        assert_eq!(PistonBlock::calculate_facing_from_player(&order_north), Facing::South);

        let order_south = [Facing::South, Facing::Up, Facing::Down, Facing::North, Facing::East, Facing::West];
        assert_eq!(PistonBlock::calculate_facing_from_player(&order_south), Facing::North);
    }

    #[test]
    fn test_dispenser_and_dropper_timing_facing_and_comparator_parity() {
        use crate::block::blocks::redstone::dispenser::DispenserBlock;
        use crate::block::blocks::redstone::dropper::DropperBlock;
        use pumpkin_data::block_properties::Facing;
        use pumpkin_util::math::position::BlockPos;

        // Constants verification
        assert_eq!(DispenserBlock::TRIGGER_DURATION, 4);
        assert_eq!(DropperBlock::TRIGGER_DURATION, 4);
        assert_eq!(DispenserBlock::CONTAINER_SIZE, 9);
        assert_eq!(DropperBlock::CONTAINER_SIZE, 9);
        assert_eq!(DispenserBlock::FAIL_EVENT_ID, 1001);
        assert_eq!(DropperBlock::FAIL_EVENT_ID, 1001);
        assert_eq!(DispenserBlock::DISPENSE_EVENT_ID, 1000);
        assert_eq!(DropperBlock::DROP_EVENT_ID, 1000);
        assert_eq!(DispenserBlock::LAUNCH_EVENT_ID, 1002);
        assert!((DispenserBlock::DISPENSE_OFFSET_SCALE - 0.7).abs() < 1e-6);
        assert!(!DispenserBlock::DEFAULT_TRIGGERED);
        assert!(!DropperBlock::DEFAULT_TRIGGERED);
        assert_eq!(DispenserBlock::DEFAULT_FACING, Facing::North);
        assert_eq!(DropperBlock::DEFAULT_FACING, Facing::North);

        // Facing orientation from player order
        let order_down = [Facing::Down, Facing::North, Facing::South, Facing::East, Facing::West, Facing::Up];
        assert_eq!(DispenserBlock::calculate_facing_from_player(&order_down), Facing::Up);
        assert_eq!(DropperBlock::calculate_facing_from_player(&order_down), Facing::Up);

        let order_up = [Facing::Up, Facing::North, Facing::South, Facing::East, Facing::West, Facing::Down];
        assert_eq!(DispenserBlock::calculate_facing_from_player(&order_up), Facing::Down);
        assert_eq!(DropperBlock::calculate_facing_from_player(&order_up), Facing::Down);

        let order_north = [Facing::North, Facing::Up, Facing::Down, Facing::South, Facing::East, Facing::West];
        assert_eq!(DispenserBlock::calculate_facing_from_player(&order_north), Facing::South);
        assert_eq!(DropperBlock::calculate_facing_from_player(&order_north), Facing::South);

        // Dispense position offsets
        let pos = BlockPos::new(10, 64, 10);
        let center = pos.to_centered_f64(); // (10.5, 64.5, 10.5)

        let pos_up = DispenserBlock::calculate_dispense_position(&pos, Facing::Up, 0.7);
        assert!((pos_up.x - center.x).abs() < 1e-6);
        assert!((pos_up.y - (center.y + 0.7)).abs() < 1e-6);
        assert!((pos_up.z - center.z).abs() < 1e-6);

        let pos_down = DispenserBlock::calculate_dispense_position(&pos, Facing::Down, 0.7);
        assert!((pos_down.x - center.x).abs() < 1e-6);
        assert!((pos_down.y - (center.y - 0.7)).abs() < 1e-6);
        assert!((pos_down.z - center.z).abs() < 1e-6);

        let pos_north = DispenserBlock::calculate_dispense_position(&pos, Facing::North, 0.7);
        assert!((pos_north.x - center.x).abs() < 1e-6);
        assert!((pos_north.y - center.y).abs() < 1e-6);
        assert!((pos_north.z - (center.z - 0.7)).abs() < 1e-6);

        let drop_pos = DropperBlock::calculate_drop_position(&pos, Facing::South, 0.7);
        assert!((drop_pos.x - center.x).abs() < 1e-6);
        assert!((drop_pos.y - center.y).abs() < 1e-6);
        assert!((drop_pos.z - (center.z + 0.7)).abs() < 1e-6);

        // Container comparator outputs
        let max_cap = 9 * 64; // 576 items
        assert_eq!(DispenserBlock::calculate_comparator_output(0, max_cap), 0);
        assert_eq!(DropperBlock::calculate_comparator_output(0, max_cap), 0);
        assert_eq!(DispenserBlock::calculate_comparator_output(1, max_cap), 1);
        assert_eq!(DispenserBlock::calculate_comparator_output(288, max_cap), 8);
        assert_eq!(DispenserBlock::calculate_comparator_output(max_cap, max_cap), 15);
    }

    #[test]
    fn test_tripwire_and_hook_tension_disarm_and_signal_parity() {
        use crate::block::blocks::redstone::tripwire::TripwireBlock;
        use crate::block::blocks::redstone::tripwire_hook::TripwireHookBlock;
        use pumpkin_data::block_properties::HorizontalFacing;
        use pumpkin_data::entity::EntityType;
        use pumpkin_data::item::Item;

        // TripwireHook constants
        assert_eq!(TripwireHookBlock::WIRE_DIST_MIN, 1);
        assert_eq!(TripwireHookBlock::WIRE_DIST_MAX, 42);
        assert_eq!(TripwireHookBlock::RECHECK_PERIOD_TICKS, 10);
        assert_eq!(TripwireHookBlock::POWER_ON, 15);
        assert_eq!(TripwireHookBlock::POWER_OFF, 0);
        assert!(!TripwireHookBlock::DEFAULT_POWERED);
        assert!(!TripwireHookBlock::DEFAULT_ATTACHED);
        assert_eq!(TripwireHookBlock::DEFAULT_FACING, HorizontalFacing::North);

        assert!((TripwireHookBlock::CLICK_ON_VOLUME - 0.4).abs() < 1e-6);
        assert!((TripwireHookBlock::CLICK_ON_PITCH - 0.6).abs() < 1e-6);
        assert!((TripwireHookBlock::CLICK_OFF_VOLUME - 0.4).abs() < 1e-6);
        assert!((TripwireHookBlock::CLICK_OFF_PITCH - 0.5).abs() < 1e-6);
        assert!((TripwireHookBlock::ATTACH_VOLUME - 0.4).abs() < 1e-6);
        assert!((TripwireHookBlock::ATTACH_PITCH - 0.7).abs() < 1e-6);
        assert!((TripwireHookBlock::DETACH_VOLUME - 0.4).abs() < 1e-6);
        assert!((TripwireHookBlock::DETACH_PITCH - 1.2).abs() < 1e-6);

        // Tripwire constants
        assert_eq!(TripwireBlock::RECHECK_PERIOD_TICKS, 10);
        assert!(!TripwireBlock::DEFAULT_POWERED);
        assert!(!TripwireBlock::DEFAULT_ATTACHED);
        assert!(!TripwireBlock::DEFAULT_DISARMED);

        // Wire range & line formation
        assert!(!TripwireHookBlock::is_in_wire_range(0));
        assert!(TripwireHookBlock::is_in_wire_range(1));
        assert!(TripwireHookBlock::is_in_wire_range(41));
        assert!(!TripwireHookBlock::is_in_wire_range(42));

        assert!(!TripwireHookBlock::can_form_line(0));
        assert!(!TripwireHookBlock::can_form_line(1));
        assert!(TripwireHookBlock::can_form_line(2));
        assert!(TripwireHookBlock::can_form_line(41));

        // Power emissions
        assert_eq!(TripwireHookBlock::emits_weak_power(true), 15);
        assert_eq!(TripwireHookBlock::emits_weak_power(false), 0);

        assert_eq!(
            TripwireHookBlock::emits_strong_power(true, HorizontalFacing::North, HorizontalFacing::North),
            15
        );
        assert_eq!(
            TripwireHookBlock::emits_strong_power(true, HorizontalFacing::North, HorizontalFacing::South),
            0
        );
        assert_eq!(
            TripwireHookBlock::emits_strong_power(false, HorizontalFacing::North, HorizontalFacing::North),
            0
        );

        // Shears disarming and entity trigger ignores
        assert!(TripwireBlock::can_disarm_with_shears(&Item::SHEARS));
        assert!(!TripwireBlock::can_disarm_with_shears(&Item::DIAMOND_SWORD));
        assert!(!TripwireBlock::can_disarm_with_shears(&Item::STICK));

        assert!(TripwireBlock::is_entity_trigger_ignored(&EntityType::BAT));
        assert!(!TripwireBlock::is_entity_trigger_ignored(&EntityType::ZOMBIE));
        assert!(!TripwireBlock::is_entity_trigger_ignored(&EntityType::ARROW));

        // Hook activation condition
        assert!(TripwireBlock::calculate_hook_power(true, true));
        assert!(!TripwireBlock::calculate_hook_power(false, true)); // Disarmed prevents hook trigger!
        assert!(!TripwireBlock::calculate_hook_power(true, false));
        assert!(!TripwireBlock::calculate_hook_power(false, false));
    }

    #[test]
    fn test_noteblock_pitch_particles_and_instruments_parity() {
        use crate::block::blocks::note::NoteBlock;
        use pumpkin_data::block_properties::NoteblockInstrument;

        // Constants verification
        assert!((NoteBlock::NOTE_VOLUME - 3.0).abs() < 1e-6);
        assert_eq!(NoteBlock::MIN_NOTE, 0);
        assert_eq!(NoteBlock::MAX_NOTE, 24);
        assert_eq!(NoteBlock::NUM_NOTES, 25);
        assert_eq!(NoteBlock::DEFAULT_NOTE, 0);
        assert!(!NoteBlock::DEFAULT_POWERED);
        assert_eq!(NoteBlock::DEFAULT_INSTRUMENT, NoteblockInstrument::Harp);

        // Pitch calculations: 2 octaves range from 0.5 to 2.0
        assert!((NoteBlock::get_pitch_from_note(0) - 0.5).abs() < 1e-6);
        assert!((NoteBlock::get_pitch_from_note(12) - 1.0).abs() < 1e-6);
        assert!((NoteBlock::get_pitch_from_note(24) - 2.0).abs() < 1e-6);

        // Semitone ratio test (each semitone is 2^(1/12))
        let semitone_ratio = 2.0f32.powf(1.0 / 12.0);
        for note in 0..24 {
            let p1 = NoteBlock::get_pitch_from_note(note);
            let p2 = NoteBlock::get_pitch_from_note(note + 1);
            assert!((p2 / p1 - semitone_ratio).abs() < 1e-5);
        }

        // Note cycling modulo 25
        assert_eq!(NoteBlock::cycle_note(0), 1);
        assert_eq!(NoteBlock::cycle_note(12), 13);
        assert_eq!(NoteBlock::cycle_note(23), 24);
        assert_eq!(NoteBlock::cycle_note(24), 0);

        // Particle color X offset (0.0 to 1.0 over 24 notes)
        assert!((NoteBlock::get_particle_color_x(0) - 0.0).abs() < 1e-6);
        assert!((NoteBlock::get_particle_color_x(12) - 0.5).abs() < 1e-6);
        assert!((NoteBlock::get_particle_color_x(24) - 1.0).abs() < 1e-6);

        // Tunable vs Mob Head instruments
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Harp));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Bass));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Snare));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Hat));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Basedrum));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Bell));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Flute));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Chime));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Guitar));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Xylophone));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::IronXylophone));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::CowBell));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Didgeridoo));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Bit));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Banjo));
        assert!(NoteBlock::is_tunable_instrument(NoteblockInstrument::Pling));

        assert!(!NoteBlock::is_tunable_instrument(NoteblockInstrument::Zombie));
        assert!(!NoteBlock::is_tunable_instrument(NoteblockInstrument::Skeleton));
        assert!(!NoteBlock::is_tunable_instrument(NoteblockInstrument::Creeper));
        assert!(!NoteBlock::is_tunable_instrument(NoteblockInstrument::Dragon));
        assert!(!NoteBlock::is_tunable_instrument(NoteblockInstrument::WitherSkeleton));
        assert!(!NoteBlock::is_tunable_instrument(NoteblockInstrument::Piglin));
        assert!(!NoteBlock::is_tunable_instrument(NoteblockInstrument::CustomHead));
    }

    #[test]
    fn test_redstone_lamp_light_delays_and_state_transitions_parity() {
        use crate::block::blocks::redstone::redstone_lamp::RedstoneLamp;

        // Constants verification
        assert_eq!(RedstoneLamp::DELAY, 4);
        assert_eq!(RedstoneLamp::DEACTIVATION_DELAY, 4);
        assert_eq!(RedstoneLamp::LIGHT_LEVEL_LIT, 15);
        assert_eq!(RedstoneLamp::LIGHT_LEVEL_UNLIT, 0);
        assert!(!RedstoneLamp::DEFAULT_LIT);

        // Light level emission
        assert_eq!(RedstoneLamp::get_light_emission(true), 15);
        assert_eq!(RedstoneLamp::get_light_emission(false), 0);

        // Placement lit state
        assert!(RedstoneLamp::calculate_lit_on_placement(true));
        assert!(!RedstoneLamp::calculate_lit_on_placement(false));

        // State transition rules
        // Instant activation upon receiving power
        assert!(RedstoneLamp::should_turn_on(false, true));
        assert!(!RedstoneLamp::should_turn_on(false, false));
        assert!(!RedstoneLamp::should_turn_on(true, true));
        assert!(!RedstoneLamp::should_turn_on(true, false));

        // 4-tick delay schedule on losing power
        assert!(RedstoneLamp::should_schedule_turn_off(true, false));
        assert!(!RedstoneLamp::should_schedule_turn_off(true, true));
        assert!(!RedstoneLamp::should_schedule_turn_off(false, false));
        assert!(!RedstoneLamp::should_schedule_turn_off(false, true));

        // Turn off execution on tick check (keeps lit if power restored)
        assert!(RedstoneLamp::should_turn_off_on_tick(true, false));
        assert!(!RedstoneLamp::should_turn_off_on_tick(true, true));
        assert!(!RedstoneLamp::should_turn_off_on_tick(false, false));
    }
#[test]
    fn test_doors_trapdoors_and_fence_gates_parity() {
        use crate::block::blocks::doors::DoorBlock;
        use crate::block::blocks::trapdoor::TrapDoorBlock;
        use crate::block::blocks::fence_gates::FenceGateBlock;
        use pumpkin_data::Block;
        use pumpkin_data::block_properties::HorizontalFacing;

        // --- DoorBlock Parity ---
        assert_eq!(DoorBlock::SOUND_VOLUME, 1.0);
        assert_eq!(DoorBlock::SOUND_PITCH_BASE, 0.9);
        assert_eq!(DoorBlock::SOUND_PITCH_RANGE, 0.1);
        assert!(!DoorBlock::DEFAULT_OPEN);
        assert!(!DoorBlock::DEFAULT_POWERED);

        assert!((DoorBlock::calculate_sound_pitch(0.0) - 0.9).abs() < 1e-5);
        assert!((DoorBlock::calculate_sound_pitch(1.0) - 1.0).abs() < 1e-5);
        assert!((DoorBlock::calculate_sound_pitch(0.5) - 0.95).abs() < 1e-5);

        assert!(DoorBlock::can_open_by_hand(&Block::OAK_DOOR));
        assert!(!DoorBlock::can_open_by_hand(&Block::IRON_DOOR));

        // Evaluate redstone interaction: (current_open, current_powered, has_signal) -> (new_powered, new_open, should_play_sound)
        assert_eq!(DoorBlock::evaluate_redstone_interaction(false, false, true), (true, true, true));
        assert_eq!(DoorBlock::evaluate_redstone_interaction(true, true, false), (false, false, true));
        assert_eq!(DoorBlock::evaluate_redstone_interaction(true, false, true), (true, true, false));
        assert_eq!(DoorBlock::evaluate_redstone_interaction(true, true, true), (true, true, false));

        // --- TrapDoorBlock Parity ---
        assert_eq!(TrapDoorBlock::SOUND_VOLUME, 1.0);
        assert_eq!(TrapDoorBlock::SOUND_PITCH_BASE, 0.9);
        assert_eq!(TrapDoorBlock::SOUND_PITCH_RANGE, 0.1);
        assert!(!TrapDoorBlock::DEFAULT_OPEN);
        assert!(!TrapDoorBlock::DEFAULT_POWERED);
        assert!(!TrapDoorBlock::DEFAULT_WATERLOGGED);

        assert!((TrapDoorBlock::calculate_sound_pitch(0.0) - 0.9).abs() < 1e-5);
        assert!((TrapDoorBlock::calculate_sound_pitch(1.0) - 1.0).abs() < 1e-5);

        assert!(TrapDoorBlock::can_open_by_hand(&Block::OAK_TRAPDOOR));
        assert!(!TrapDoorBlock::can_open_by_hand(&Block::IRON_TRAPDOOR));

        assert_eq!(TrapDoorBlock::evaluate_redstone_interaction(false, false, true), (true, true, true));
        assert_eq!(TrapDoorBlock::evaluate_redstone_interaction(true, true, false), (false, false, true));

        // --- FenceGateBlock Parity ---
        assert_eq!(FenceGateBlock::SOUND_VOLUME, 1.0);
        assert_eq!(FenceGateBlock::SOUND_PITCH_BASE, 0.9);
        assert_eq!(FenceGateBlock::SOUND_PITCH_RANGE, 0.1);
        assert!(!FenceGateBlock::DEFAULT_OPEN);
        assert!(!FenceGateBlock::DEFAULT_POWERED);
        assert!(!FenceGateBlock::DEFAULT_IN_WALL);

        assert_eq!(FenceGateBlock::evaluate_redstone_interaction(false, false, true), (true, true, true));
        assert_eq!(FenceGateBlock::evaluate_redstone_interaction(true, true, false), (false, false, true));

        // Perpendicular connection: gate facing North connects along Axis X (East and West)
        assert!(FenceGateBlock::connects_to_direction(HorizontalFacing::North, HorizontalFacing::East));
        assert!(FenceGateBlock::connects_to_direction(HorizontalFacing::North, HorizontalFacing::West));
        assert!(!FenceGateBlock::connects_to_direction(HorizontalFacing::North, HorizontalFacing::North));
        assert!(!FenceGateBlock::connects_to_direction(HorizontalFacing::North, HorizontalFacing::South));
    }
#[test]
    fn test_bell_resonating_proper_hit_and_raiders_parity() {
        use crate::block::blocks::redstone::bell::BellBlock;
        use crate::block::entities::bell::BellBlockEntity;
        use pumpkin_data::BlockDirection;
        use pumpkin_data::block_properties::{BellAttachment, HorizontalFacing};

        // --- BellBlock Constants Parity ---
        assert_eq!(BellBlock::EVENT_BELL_RING, 1);
        assert_eq!(BellBlock::SOUND_VOLUME, 2.0);
        assert_eq!(BellBlock::SOUND_PITCH, 1.0);
        assert!((BellBlock::MAX_HIT_HEIGHT - 0.8124).abs() < 1e-4);
        assert_eq!(BellBlock::DEFAULT_FACING, HorizontalFacing::North);
        assert_eq!(BellBlock::DEFAULT_ATTACHMENT, BellAttachment::Floor);
        assert!(!BellBlock::DEFAULT_POWERED);

        // --- Redstone activation rule ---
        assert_eq!(BellBlock::evaluate_neighbor_signal_change(false, true), (true, true));
        assert_eq!(BellBlock::evaluate_neighbor_signal_change(true, true), (true, false));
        assert_eq!(BellBlock::evaluate_neighbor_signal_change(true, false), (false, false));
        assert_eq!(BellBlock::evaluate_neighbor_signal_change(false, false), (false, false));

        // --- Proper Hit mechanics ---
        // Hit from top or bottom faces never rings
        assert!(!BellBlock::is_proper_hit(BellAttachment::Floor, HorizontalFacing::North, BlockDirection::Up, 0.5));
        assert!(!BellBlock::is_proper_hit(BellAttachment::Floor, HorizontalFacing::North, BlockDirection::Down, 0.5));
        // Hit above 0.8124 height never rings
        assert!(!BellBlock::is_proper_hit(BellAttachment::Floor, HorizontalFacing::North, BlockDirection::North, 0.85));

        // Floor attachment: hit face must share same axis as facing
        assert!(BellBlock::is_proper_hit(BellAttachment::Floor, HorizontalFacing::North, BlockDirection::North, 0.5));
        assert!(BellBlock::is_proper_hit(BellAttachment::Floor, HorizontalFacing::North, BlockDirection::South, 0.5));
        assert!(!BellBlock::is_proper_hit(BellAttachment::Floor, HorizontalFacing::North, BlockDirection::East, 0.5));
        assert!(!BellBlock::is_proper_hit(BellAttachment::Floor, HorizontalFacing::North, BlockDirection::West, 0.5));

        // Wall attachments: hit face must NOT share same axis as facing
        assert!(!BellBlock::is_proper_hit(BellAttachment::SingleWall, HorizontalFacing::North, BlockDirection::North, 0.5));
        assert!(BellBlock::is_proper_hit(BellAttachment::SingleWall, HorizontalFacing::North, BlockDirection::East, 0.5));
        assert!(!BellBlock::is_proper_hit(BellAttachment::DoubleWall, HorizontalFacing::North, BlockDirection::South, 0.5));
        assert!(BellBlock::is_proper_hit(BellAttachment::DoubleWall, HorizontalFacing::North, BlockDirection::West, 0.5));

        // Ceiling attachment: any horizontal hit <= 0.8124 height succeeds
        assert!(BellBlock::is_proper_hit(BellAttachment::Ceiling, HorizontalFacing::North, BlockDirection::North, 0.5));
        assert!(BellBlock::is_proper_hit(BellAttachment::Ceiling, HorizontalFacing::North, BlockDirection::East, 0.5));

        // --- BellBlockEntity Constants & Formulas Parity ---
        assert_eq!(BellBlockEntity::DURATION, 50);
        assert_eq!(BellBlockEntity::GLOW_DURATION, 60);
        assert_eq!(BellBlockEntity::MIN_TICKS_BETWEEN_SEARCHES, 60);
        assert_eq!(BellBlockEntity::MAX_RESONATION_TICKS, 40);
        assert_eq!(BellBlockEntity::TICKS_BEFORE_RESONATION, 5);
        assert_eq!(BellBlockEntity::SEARCH_RADIUS, 48.0);
        assert_eq!(BellBlockEntity::HEAR_BELL_RADIUS, 32.0);
        assert_eq!(BellBlockEntity::HIGHLIGHT_RAIDERS_RADIUS, 48.0);

        // Particle count formula: clamp((nearbyRaiderCount - 21) / -2, 3, 15)
        assert_eq!(BellBlockEntity::calculate_particle_count(0), 10);
        assert_eq!(BellBlockEntity::calculate_particle_count(1), 10);
        assert_eq!(BellBlockEntity::calculate_particle_count(21), 3);
        assert_eq!(BellBlockEntity::calculate_particle_count(50), 3);
        assert_eq!(BellBlockEntity::calculate_particle_count(-20), 15);

        // Hearing and glowing radii
        assert!(BellBlockEntity::is_entity_hearing_bell(30.0 * 30.0));
        assert!(!BellBlockEntity::is_entity_hearing_bell(33.0 * 33.0));
        assert!(BellBlockEntity::is_raider_in_glow_range(45.0 * 45.0));
        assert!(!BellBlockEntity::is_raider_in_glow_range(50.0 * 50.0));
    }
#[test]
    fn test_target_block_hit_power_and_timing_parity() {
        use crate::block::blocks::redstone::target_block::TargetBlock;
        use pumpkin_data::block_properties::Axis;
        use pumpkin_data::entity::EntityType;

        // Constants verification
        assert_eq!(TargetBlock::ACTIVATION_TICKS_ARROWS, 20);
        assert_eq!(TargetBlock::ACTIVATION_TICKS_OTHER, 8);
        assert_eq!(TargetBlock::MIN_POWER, 1);
        assert_eq!(TargetBlock::MAX_POWER, 15);
        assert_eq!(TargetBlock::DEFAULT_POWER, 0);
        assert_eq!(TargetBlock::BULLSEYE_MIN_DISTANCE, 30.0);
        assert!(!TargetBlock::emits_strong_power());

        // Projectile activation tick durations
        assert!(TargetBlock::is_arrow_projectile(&EntityType::ARROW));
        assert!(TargetBlock::is_arrow_projectile(&EntityType::SPECTRAL_ARROW));
        assert!(TargetBlock::is_arrow_projectile(&EntityType::TRIDENT));
        assert!(!TargetBlock::is_arrow_projectile(&EntityType::SNOWBALL));
        assert!(!TargetBlock::is_arrow_projectile(&EntityType::EGG));
        assert!(!TargetBlock::is_arrow_projectile(&EntityType::WIND_CHARGE));

        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::ARROW), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::SPECTRAL_ARROW), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::TRIDENT), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::SNOWBALL), 8);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::EGG), 8);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::WIND_CHARGE), 8);

        // Power calculation from distance to center
        assert_eq!(TargetBlock::calculate_power_from_distance(0.0), 15);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.03), 15);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.04), 14);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.25), 8);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.49), 1);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.50), 1);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.60), 1);

        // Axis-based directional calculations
        // Top/Bottom (Axis Y): uses max(distX, distZ)
        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.0, 0.5, 0.0, Axis::Y), 15);
        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.25, 0.5, 0.1, Axis::Y), 8);

        // North/South (Axis Z): uses max(distX, distY)
        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.04, 0.02, 0.5, Axis::Z), 14);

        // East/West (Axis X): uses max(distY, distZ)
        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.5, 0.49, 0.1, Axis::X), 1);
    }
#[test]
    fn test_lightning_rod_pulse_power_and_orientations_parity() {
        use crate::block::blocks::redstone::lightning_rod::LightningRodBlock;
        use pumpkin_data::BlockDirection;
        use pumpkin_data::block_properties::Facing;
        use pumpkin_util::math::position::BlockPos;

        // Constants verification
        assert_eq!(LightningRodBlock::ACTIVATION_TICKS, 8);
        assert_eq!(LightningRodBlock::RANGE, 128);
        assert_eq!(LightningRodBlock::SPARK_CYCLE, 200);
        assert_eq!(LightningRodBlock::EVENT_LIGHTNING_STRIKE, 3002);
        assert_eq!(LightningRodBlock::POWER_ON, 15);
        assert_eq!(LightningRodBlock::POWER_OFF, 0);
        assert_eq!(LightningRodBlock::DEFAULT_FACING, Facing::Up);
        assert!(!LightningRodBlock::DEFAULT_POWERED);
        assert!(!LightningRodBlock::DEFAULT_WATERLOGGED);

        // Power emissions (unpowered vs powered)
        assert_eq!(LightningRodBlock::get_weak_power(false), 0);
        assert_eq!(LightningRodBlock::get_weak_power(true), 15);

        // Strong power directional emissions
        // Rod facing UP: emits strong power 15 only upwards
        assert_eq!(LightningRodBlock::get_strong_power(false, Facing::Up, BlockDirection::Up), 0);
        assert_eq!(LightningRodBlock::get_strong_power(true, Facing::Up, BlockDirection::Up), 15);
        assert_eq!(LightningRodBlock::get_strong_power(true, Facing::Up, BlockDirection::Down), 0);
        assert_eq!(LightningRodBlock::get_strong_power(true, Facing::Up, BlockDirection::North), 0);
        assert_eq!(LightningRodBlock::get_strong_power(true, Facing::Up, BlockDirection::East), 0);

        // Rod facing EAST: emits strong power 15 only eastwards
        assert_eq!(LightningRodBlock::get_strong_power(true, Facing::East, BlockDirection::East), 15);
        assert_eq!(LightningRodBlock::get_strong_power(true, Facing::East, BlockDirection::West), 0);
        assert_eq!(LightningRodBlock::get_strong_power(true, Facing::East, BlockDirection::Up), 0);

        // Attached block offset
        let rod_pos = BlockPos::new(10, 64, 10);
        // If rod faces UP, it is attached to the block below (Y - 1)
        assert_eq!(LightningRodBlock::get_attached_position(&rod_pos, Facing::Up), BlockPos::new(10, 63, 10));
        // If rod faces NORTH, it is attached to the block to the south (Z + 1)
        assert_eq!(LightningRodBlock::get_attached_position(&rod_pos, Facing::North), BlockPos::new(10, 64, 11));

        // Axis ordinals (for particle spark levelEvent 3002)
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::East), 0);
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::West), 0);
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::Up), 1);
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::Down), 1);
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::North), 2);
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::South), 2);
    }
#[test]
    fn test_sculk_sensor_frequencies_timings_and_calibrated_parity() {
        use crate::block::blocks::redstone::sculk_sensor::SculkSensorBlock;
        use pumpkin_data::block_properties::{HorizontalFacing, SculkSensorPhase};
        use pumpkin_data::{BlockDirection, BlockId};

        // Constants verification
        assert_eq!(SculkSensorBlock::ACTIVE_TICKS_REGULAR, 30);
        assert_eq!(SculkSensorBlock::ACTIVE_TICKS_CALIBRATED, 10);
        assert_eq!(SculkSensorBlock::COOLDOWN_TICKS, 10);
        assert_eq!(SculkSensorBlock::LISTENER_RANGE_REGULAR, 8);
        assert_eq!(SculkSensorBlock::LISTENER_RANGE_CALIBRATED, 16);
        assert_eq!(SculkSensorBlock::DEFAULT_PHASE, SculkSensorPhase::Inactive);
        assert_eq!(SculkSensorBlock::DEFAULT_POWER, 0);
        assert!(!SculkSensorBlock::DEFAULT_WATERLOGGED);
        assert_eq!(SculkSensorBlock::DEFAULT_FACING, HorizontalFacing::North);

        // Active duration and listener range per block variant
        assert_eq!(SculkSensorBlock::get_active_ticks(BlockId::SCULK_SENSOR), 30);
        assert_eq!(SculkSensorBlock::get_active_ticks(BlockId::CALIBRATED_SCULK_SENSOR), 10);
        assert_eq!(SculkSensorBlock::get_listener_range(BlockId::SCULK_SENSOR), 8);
        assert_eq!(SculkSensorBlock::get_listener_range(BlockId::CALIBRATED_SCULK_SENSOR), 16);

        // Distance-to-power attenuation formula: max(1, 15 - floor((15 / radius) * distance))
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(0.0, 8), 15);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(4.0, 8), 8);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(8.0, 8), 1);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(12.0, 8), 1);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(0.0, 16), 15);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(8.0, 16), 8);
        assert_eq!(SculkSensorBlock::get_redstone_strength_for_distance(16.0, 16), 1);

        // Strong power is exclusively upwards
        assert!(SculkSensorBlock::emits_strong_power(BlockDirection::Up));
        assert!(!SculkSensorBlock::emits_strong_power(BlockDirection::Down));
        assert!(!SculkSensorBlock::emits_strong_power(BlockDirection::North));
        assert!(!SculkSensorBlock::emits_strong_power(BlockDirection::South));
        assert!(!SculkSensorBlock::emits_strong_power(BlockDirection::East));
        assert!(!SculkSensorBlock::emits_strong_power(BlockDirection::West));

        // Calibrated sensor suppresses power back towards its calibration facing
        assert!(!SculkSensorBlock::can_output_weak_power(
            BlockId::CALIBRATED_SCULK_SENSOR,
            Some(HorizontalFacing::North),
            BlockDirection::North,
        ));
        assert!(SculkSensorBlock::can_output_weak_power(
            BlockId::CALIBRATED_SCULK_SENSOR,
            Some(HorizontalFacing::North),
            BlockDirection::South,
        ));
        assert!(SculkSensorBlock::can_output_weak_power(
            BlockId::CALIBRATED_SCULK_SENSOR,
            Some(HorizontalFacing::North),
            BlockDirection::East,
        ));
        assert!(SculkSensorBlock::can_output_weak_power(
            BlockId::SCULK_SENSOR,
            Some(HorizontalFacing::North),
            BlockDirection::North,
        ));

        // Resonance pitch bend across 16 frequencies: toneMap = [0, 0, 2, 4, 6, 7, 9, 10, 12, 14, 15, 18, 19, 21, 22, 24]
        assert!((SculkSensorBlock::get_resonance_pitch_for_frequency(0) - 0.5).abs() < 1e-5);
        assert!((SculkSensorBlock::get_resonance_pitch_for_frequency(1) - 0.5).abs() < 1e-5);
        assert!((SculkSensorBlock::get_resonance_pitch_for_frequency(8) - 1.0).abs() < 1e-5);
        assert!((SculkSensorBlock::get_resonance_pitch_for_frequency(15) - 2.0).abs() < 1e-5);

        // Scheduled tick phase transitions: Active -> Cooldown (10 ticks) -> Inactive
        assert_eq!(
            SculkSensorBlock::get_phase_transition_on_tick(SculkSensorPhase::Active),
            (SculkSensorPhase::Cooldown, 0, Some(10))
        );
        assert_eq!(
            SculkSensorBlock::get_phase_transition_on_tick(SculkSensorPhase::Cooldown),
            (SculkSensorPhase::Inactive, 0, None)
        );
        assert_eq!(
            SculkSensorBlock::get_phase_transition_on_tick(SculkSensorPhase::Inactive),
            (SculkSensorPhase::Inactive, 0, None)
        );
    }
#[test]
    fn test_daylight_detector_inversion_and_sky_light_curve_parity() {
        use crate::block::blocks::redstone::daylight_detector::DaylightDetectorBlock;

        // Constants verification
        assert_eq!(DaylightDetectorBlock::MIN_POWER, 0);
        assert_eq!(DaylightDetectorBlock::MAX_POWER, 15);
        assert_eq!(DaylightDetectorBlock::DEFAULT_POWER, 0);
        assert!(!DaylightDetectorBlock::DEFAULT_INVERTED);
        assert_eq!(DaylightDetectorBlock::UPDATE_INTERVAL_TICKS, 20);
        assert_eq!(DaylightDetectorBlock::SHAPE_HEIGHT, 6.0);
        assert!(!DaylightDetectorBlock::emits_strong_power());

        // Inverted calculation: 15 - brightness
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(15), 0);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(0), 15);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(5), 10);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(10), 5);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(-5), 15);
        assert_eq!(DaylightDetectorBlock::calculate_inverted_signal(20), 0);

        // Effective sky brightness with weather darkening (rain: -5, thunder: -5)
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, false, false), 15);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, true, false), 10);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, false, true), 10);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(15, true, true), 5);
        assert_eq!(DaylightDetectorBlock::calculate_effective_sky_brightness(4, true, false), 0);

        // Signal strength curve (normal vs inverted)
        assert_eq!(DaylightDetectorBlock::calculate_signal_strength(0, 0.0, false), 0);
        assert_eq!(DaylightDetectorBlock::calculate_signal_strength(0, 0.0, true), 15);
        assert_eq!(DaylightDetectorBlock::calculate_signal_strength(15, 0.0, false), 15);
        assert_eq!(DaylightDetectorBlock::calculate_signal_strength(15, 0.0, true), 0);
        assert_eq!(DaylightDetectorBlock::calculate_signal_strength(15, std::f32::consts::PI, false), 0);
        assert_eq!(DaylightDetectorBlock::calculate_signal_strength(15, std::f32::consts::PI, true), 0);
    }
#[test]
    fn test_tnt_fuse_impulse_and_placement_parity() {
        use crate::block::blocks::tnt::TNTBlock;
        use pumpkin_data::Block;

        // Constants verification
        assert!(!TNTBlock::DEFAULT_UNSTABLE);
        assert_eq!(TNTBlock::DEFAULT_FUSE, 80);
        assert_eq!(TNTBlock::DEFAULT_POWER, 4.0);
        assert_eq!(TNTBlock::EXPLOSION_Y_OFFSET_SCALE, 0.0625);
        assert_eq!(TNTBlock::INITIAL_VELOCITY_Y, 0.2);
        assert_eq!(TNTBlock::INITIAL_VELOCITY_HORIZONTAL_SCALE, 0.02);
        assert_eq!(TNTBlock::GRAVITY, 0.04);
        assert_eq!(TNTBlock::AIR_DRAG, 0.98);

        // Chain reaction short fuse formula: (rand % max(1, fuse / 4)) + fuse / 8
        // For default 80 fuse: range [10, 29]
        assert_eq!(TNTBlock::calculate_short_fuse(80, 0), 10);
        assert_eq!(TNTBlock::calculate_short_fuse(80, 19), 29);
        assert_eq!(TNTBlock::calculate_short_fuse(80, 25), 15);
        assert_eq!(TNTBlock::calculate_short_fuse(0, 5), 0);

        // Initial launch impulse vector: (-sin(rot)*0.02, 0.2, -cos(rot)*0.02)
        let (vx0, vy0, vz0) = TNTBlock::calculate_initial_velocity(0.0);
        assert!((vx0 - 0.0).abs() < 1e-6);
        assert!((vy0 - 0.2).abs() < 1e-6);
        assert!((vz0 - (-0.02)).abs() < 1e-6);

        let (vx_pi2, vy_pi2, vz_pi2) = TNTBlock::calculate_initial_velocity(std::f64::consts::FRAC_PI_2);
        assert!((vx_pi2 - (-0.02)).abs() < 1e-6);
        assert!((vy_pi2 - 0.2).abs() < 1e-6);
        assert!((vz_pi2 - 0.0).abs() < 1e-6);

        // Priming on placement check
        assert!(TNTBlock::should_prime_on_placement(&Block::STONE, true));
        assert!(!TNTBlock::should_prime_on_placement(&Block::STONE, false));
        assert!(!TNTBlock::should_prime_on_placement(&Block::TNT, true));
    }
#[test]
    fn test_crafter_redstone_triggers_slots_and_comparator_parity() {
        use crate::block::blocks::redstone::crafter::CrafterBlock;
        use pumpkin_data::block_properties::Orientation;

        // Constants verification
        assert_eq!(CrafterBlock::CRAFTING_TICK_DELAY, 4);
        assert_eq!(CrafterBlock::MAX_CRAFTING_TICKS, 6);
        assert_eq!(CrafterBlock::CRAFTER_ADVANCEMENT_DIAMETER, 17.0);
        assert_eq!(CrafterBlock::CONTAINER_SIZE, 9);
        assert_eq!(CrafterBlock::CONTAINER_WIDTH, 3);
        assert_eq!(CrafterBlock::CONTAINER_HEIGHT, 3);
        assert_eq!(CrafterBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(CrafterBlock::MAX_COMPARATOR_OUTPUT, 9);
        assert_eq!(CrafterBlock::DEFAULT_ORIENTATION, Orientation::NorthUp);
        assert!(!CrafterBlock::DEFAULT_TRIGGERED);
        assert!(!CrafterBlock::DEFAULT_CRAFTING);

        // Comparator signal calculations: (occupied + disabled).min(9)
        assert_eq!(CrafterBlock::calculate_comparator_signal(0, 0), 0);
        assert_eq!(CrafterBlock::calculate_comparator_signal(9, 0), 9);
        assert_eq!(CrafterBlock::calculate_comparator_signal(0, 4), 4);
        assert_eq!(CrafterBlock::calculate_comparator_signal(3, 3), 6);
        assert_eq!(CrafterBlock::calculate_comparator_signal(6, 3), 9);
        assert_eq!(CrafterBlock::calculate_comparator_signal(8, 4), 9); // capped at 9

        // State-array signal calculation
        let occupied = [true, false, true, false, false, false, false, false, false];
        let disabled = [false, true, false, false, false, false, false, false, false];
        assert_eq!(CrafterBlock::calculate_signal_from_states(&occupied, &disabled), 3);

        // Disabled slots bitmask conversions
        let mut slots = [false; 9];
        slots[0] = true;
        slots[2] = true;
        slots[4] = true;
        let mask = CrafterBlock::disabled_slots_to_bitmask(&slots);
        assert_eq!(mask, 1 | 4 | 16);
        let back = CrafterBlock::bitmask_to_disabled_slots(mask);
        assert_eq!(back, slots);

        // Slot valid for craft: occupied and not disabled
        assert!(CrafterBlock::is_slot_valid_for_craft(true, false));
        assert!(!CrafterBlock::is_slot_valid_for_craft(true, true));
        assert!(!CrafterBlock::is_slot_valid_for_craft(false, false));
        assert!(!CrafterBlock::is_slot_valid_for_craft(false, true));

        // Redstone trigger state machine: (powered, triggered) -> (new_triggered, should_schedule_craft)
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(true, false), (true, true));
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(false, true), (false, false));
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(true, true), (true, false));
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(false, false), (false, false));
    }
#[test]
    fn test_copper_bulb_t_flip_flop_and_light_levels_parity() {
        use crate::block::blocks::redstone::copper_bulb::CopperBulbBlock;
        use pumpkin_data::BlockId;

        // Constants verification
        assert!(!CopperBulbBlock::DEFAULT_POWERED);
        assert!(!CopperBulbBlock::DEFAULT_LIT);
        assert_eq!(CopperBulbBlock::COMPARATOR_SIGNAL_LIT, 15);
        assert_eq!(CopperBulbBlock::COMPARATOR_SIGNAL_UNLIT, 0);

        // Comparator analog output
        assert_eq!(CopperBulbBlock::get_comparator_output_value(true), 15);
        assert_eq!(CopperBulbBlock::get_comparator_output_value(false), 0);

        // T-flip-flop behavior: (current_lit, current_powered, has_signal) -> (new_lit, new_powered, sound)
        // 1. Initial state (unlit, unpowered), power arrives -> toggles to lit, plays TurnOn sound
        assert_eq!(
            CopperBulbBlock::evaluate_t_flip_flop(false, false, true),
            (true, true, Some(true))
        );

        // 2. Power removed (falling edge) -> remains lit, powered flag cleared, no sound
        assert_eq!(
            CopperBulbBlock::evaluate_t_flip_flop(true, true, false),
            (true, false, None)
        );

        // 3. Second pulse arrives (rising edge) -> toggles to unlit, plays TurnOff sound
        assert_eq!(
            CopperBulbBlock::evaluate_t_flip_flop(true, false, true),
            (false, true, Some(false))
        );

        // 4. Second pulse removed (falling edge) -> remains unlit, no sound
        assert_eq!(
            CopperBulbBlock::evaluate_t_flip_flop(false, true, false),
            (false, false, None)
        );

        // 5. Steady state (no edge) -> no modification
        assert_eq!(
            CopperBulbBlock::evaluate_t_flip_flop(true, true, true),
            (true, true, None)
        );

        // Light level per oxidation stage: 15 -> 12 -> 8 -> 4 (0 when unlit)
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::COPPER_BULB, false), 0);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::COPPER_BULB, true), 15);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_COPPER_BULB, true), 15);

        assert_eq!(CopperBulbBlock::get_light_level(BlockId::EXPOSED_COPPER_BULB, true), 12);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_EXPOSED_COPPER_BULB, true), 12);

        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WEATHERED_COPPER_BULB, true), 8);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_WEATHERED_COPPER_BULB, true), 8);

        assert_eq!(CopperBulbBlock::get_light_level(BlockId::OXIDIZED_COPPER_BULB, true), 4);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_OXIDIZED_COPPER_BULB, true), 4);
    }
#[test]
    fn test_chiseled_bookshelf_slot_raycasting_and_comparator_parity() {
        use crate::block::blocks::chiseled_bookshelf::ChiseledBookshelfBlock;
        use pumpkin_data::block_properties::HorizontalFacing;

        // Constants verification
        assert_eq!(ChiseledBookshelfBlock::MAX_BOOKS_IN_STORAGE, 6);
        assert_eq!(ChiseledBookshelfBlock::BOOKS_PER_ROW, 3);
        assert_eq!(ChiseledBookshelfBlock::ROWS, 2);
        assert_eq!(ChiseledBookshelfBlock::COLUMNS, 3);
        assert_eq!(ChiseledBookshelfBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(ChiseledBookshelfBlock::MAX_COMPARATOR_OUTPUT, 6);
        assert_eq!(ChiseledBookshelfBlock::DEFAULT_FACING, HorizontalFacing::North);
        assert!(!ChiseledBookshelfBlock::DEFAULT_SLOT_OCCUPIED);

        // Section subdivision calculation (16.0 / maxSections)
        assert_eq!(ChiseledBookshelfBlock::get_section(0.1, 3), 0);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.5, 3), 1);
        assert_eq!(ChiseledBookshelfBlock::get_section(0.9, 3), 2);

        // 6-slot 2x3 grid mapping from (hit_x, hit_y)
        // Top row (hit_y > 0.5): slots 0, 1, 2
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.1, 0.9), 0);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.5, 0.9), 1);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.9, 0.9), 2);
        // Bottom row (hit_y < 0.5): slots 3, 4, 5
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.1, 0.1), 3);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.5, 0.1), 4);
        assert_eq!(ChiseledBookshelfBlock::calculate_hit_slot(0.9, 0.1), 5);

        // Relative hit coordinates by facing
        // Hit on front face succeeds
        assert_eq!(
            ChiseledBookshelfBlock::get_relative_hit_coords(0.25, 0.75, 0.0, HorizontalFacing::North, HorizontalFacing::North),
            Some((0.75, 0.75))
        );
        assert_eq!(
            ChiseledBookshelfBlock::get_relative_hit_coords(0.25, 0.75, 0.0, HorizontalFacing::South, HorizontalFacing::South),
            Some((0.25, 0.75))
        );
        assert_eq!(
            ChiseledBookshelfBlock::get_relative_hit_coords(0.0, 0.75, 0.25, HorizontalFacing::West, HorizontalFacing::West),
            Some((0.25, 0.75))
        );
        assert_eq!(
            ChiseledBookshelfBlock::get_relative_hit_coords(0.0, 0.75, 0.25, HorizontalFacing::East, HorizontalFacing::East),
            Some((0.75, 0.75))
        );
        // Hit on non-front face returns None
        assert_eq!(
            ChiseledBookshelfBlock::get_relative_hit_coords(0.25, 0.75, 0.0, HorizontalFacing::South, HorizontalFacing::North),
            None
        );

        // Comparator output formula: lastInteractedSlot + 1 (1..=6, or 0 if -1)
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(-1), 0);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(0), 1);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(1), 2);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(2), 3);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(3), 4);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(4), 5);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(5), 6);
        assert_eq!(ChiseledBookshelfBlock::calculate_comparator_output(6), 0);
    }

    #[test]
    fn test_jukebox_song_durations_comparator_and_allay_dance_parity() {
        use crate::block::blocks::jukebox::JukeboxBlock;
        use pumpkin_data::jukebox_song::JukeboxSong;

        // Constants verification
        assert_eq!(JukeboxBlock::SONG_END_PADDING_TICKS, 20);
        assert_eq!(JukeboxBlock::PLAY_EVENT_INTERVAL_TICKS, 20);
        assert_eq!(JukeboxBlock::ALLAY_HEARING_RANGE, 10.0);
        assert_eq!(JukeboxBlock::REDSTONE_SIGNAL_PLAYING, 15);
        assert_eq!(JukeboxBlock::REDSTONE_SIGNAL_STOPPED, 0);
        assert_eq!(JukeboxBlock::POP_OUT_HORIZONTAL_OFFSET_MAX, 0.7);
        assert_eq!(JukeboxBlock::POP_OUT_Y_OFFSET, 1.01);
        assert_eq!(JukeboxBlock::POP_OUT_PICKUP_DELAY_TICKS, 10);
        assert_eq!(JukeboxBlock::EVENT_PLAY_RECORD, 1010);
        assert_eq!(JukeboxBlock::EVENT_STOP_RECORD, 1011);

        // Playback duration calculation (lengthInTicks + 20-tick padding)
        // Pigstep: 149 seconds * 20 = 2980 ticks; total duration = 3000 ticks
        let pigstep_base = JukeboxSong::Pigstep.length_in_ticks();
        assert_eq!(pigstep_base, 2980);
        assert_eq!(JukeboxBlock::calculate_total_playback_ticks(pigstep_base), 3000);
        assert!(!JukeboxBlock::has_song_finished(2999, pigstep_base));
        assert!(JukeboxBlock::has_song_finished(3000, pigstep_base));
        assert!(JukeboxBlock::has_song_finished(3001, pigstep_base));

        // 11: 71 seconds * 20 = 1420 ticks; total = 1440 ticks
        let eleven_base = JukeboxSong::Id11.length_in_ticks();
        assert_eq!(eleven_base, 1420);
        assert_eq!(JukeboxBlock::calculate_total_playback_ticks(eleven_base), 1440);
        assert!(!JukeboxBlock::has_song_finished(1439, eleven_base));
        assert!(JukeboxBlock::has_song_finished(1440, eleven_base));

        // 5: 178 seconds * 20 = 3560 ticks; total = 3580 ticks
        let five_base = JukeboxSong::Id5.length_in_ticks();
        assert_eq!(five_base, 3560);
        assert_eq!(JukeboxBlock::calculate_total_playback_ticks(five_base), 3580);
        assert!(!JukeboxBlock::has_song_finished(3579, five_base));
        assert!(JukeboxBlock::has_song_finished(3580, five_base));

        // Vanilla comparator output values (0..15)
        assert_eq!(JukeboxSong::Id13.comparator_output(), 1);
        assert_eq!(JukeboxSong::Cat.comparator_output(), 2);
        assert_eq!(JukeboxSong::Blocks.comparator_output(), 3);
        assert_eq!(JukeboxSong::Chirp.comparator_output(), 4);
        assert_eq!(JukeboxSong::Far.comparator_output(), 5);
        assert_eq!(JukeboxSong::Mall.comparator_output(), 6);
        assert_eq!(JukeboxSong::Mellohi.comparator_output(), 7);
        assert_eq!(JukeboxSong::Stal.comparator_output(), 8);
        assert_eq!(JukeboxSong::Strad.comparator_output(), 9);
        assert_eq!(JukeboxSong::Ward.comparator_output(), 10);
        assert_eq!(JukeboxSong::Id11.comparator_output(), 11);
        assert_eq!(JukeboxSong::Wait.comparator_output(), 12);
        assert_eq!(JukeboxSong::Pigstep.comparator_output(), 13);
        assert_eq!(JukeboxSong::Otherside.comparator_output(), 14);
        assert_eq!(JukeboxSong::Id5.comparator_output(), 15);
        assert_eq!(JukeboxSong::Relic.comparator_output(), 14);
        assert_eq!(JukeboxSong::Precipice.comparator_output(), 13);
        assert_eq!(JukeboxSong::Creator.comparator_output(), 12);
        assert_eq!(JukeboxSong::CreatorMusicBox.comparator_output(), 11);
        assert_eq!(JukeboxSong::Tears.comparator_output(), 10);
        assert_eq!(JukeboxSong::LavaChicken.comparator_output(), 9);
        assert_eq!(JukeboxSong::Bounce.comparator_output(), 8);

        // Allay hearing radius qualification (10.0 blocks / dist_sq <= 100.0)
        assert!(JukeboxBlock::can_allay_hear_jukebox(0.0));
        assert!(JukeboxBlock::can_allay_hear_jukebox(25.0)); // 5 blocks
        assert!(JukeboxBlock::can_allay_hear_jukebox(100.0)); // 10 blocks (edge)
        assert!(!JukeboxBlock::can_allay_hear_jukebox(100.01)); // just beyond
        assert!(!JukeboxBlock::can_allay_hear_jukebox(225.0)); // 15 blocks
    }

    #[test]
    fn test_lectern_book_insertion_page_pulse_and_comparator_parity() {
        use crate::block::blocks::lectern::LecternBlock;
        use crate::block::entities::lectern::calculate_lectern_comparator_output;
        use pumpkin_data::BlockDirection;
        use pumpkin_data::block_properties::HorizontalFacing;
        use pumpkin_util::math::position::BlockPos;

        // Constants verification
        assert_eq!(LecternBlock::PAGE_CHANGE_IMPULSE_TICKS, 2);
        assert_eq!(LecternBlock::PAGE_TURN_PULSE_TICKS, 2);
        assert_eq!(LecternBlock::PAGE_CHANGE_EVENT, 1043);
        assert_eq!(LecternBlock::POWER_ON, 15);
        assert_eq!(LecternBlock::POWER_OFF, 0);
        assert_eq!(LecternBlock::DEFAULT_FACING, HorizontalFacing::North);
        assert!(!LecternBlock::DEFAULT_POWERED);
        assert!(!LecternBlock::DEFAULT_HAS_BOOK);
        assert_eq!(LecternBlock::MIN_COMPARATOR_SIGNAL, 0);
        assert_eq!(LecternBlock::MAX_COMPARATOR_SIGNAL, 15);
        assert_eq!(LecternBlock::BOOK_DROP_PICKUP_DELAY_TICKS, 10);

        // Drop position calculation per facing
        let base_pos = BlockPos::new(10, 64, 10);
        let north_drop = LecternBlock::calculate_drop_position(&base_pos, HorizontalFacing::North);
        assert_eq!(north_drop.x, 10.5);
        assert_eq!(north_drop.y, 65.0);
        assert_eq!(north_drop.z, 10.25);

        let south_drop = LecternBlock::calculate_drop_position(&base_pos, HorizontalFacing::South);
        assert_eq!(south_drop.x, 10.5);
        assert_eq!(south_drop.y, 65.0);
        assert_eq!(south_drop.z, 10.75);

        let west_drop = LecternBlock::calculate_drop_position(&base_pos, HorizontalFacing::West);
        assert_eq!(west_drop.x, 10.25);
        assert_eq!(west_drop.y, 65.0);
        assert_eq!(west_drop.z, 10.5);

        let east_drop = LecternBlock::calculate_drop_position(&base_pos, HorizontalFacing::East);
        assert_eq!(east_drop.x, 10.75);
        assert_eq!(east_drop.y, 65.0);
        assert_eq!(east_drop.z, 10.5);

        // Power emissions (weak to all sides, strong strictly downwards)
        assert_eq!(LecternBlock::get_weak_power(true), 15);
        assert_eq!(LecternBlock::get_weak_power(false), 0);
        assert_eq!(LecternBlock::get_strong_power(true, BlockDirection::Up), 15);
        assert_eq!(LecternBlock::get_strong_power(true, BlockDirection::Down), 0);
        assert_eq!(LecternBlock::get_strong_power(true, BlockDirection::North), 0);
        assert_eq!(LecternBlock::get_strong_power(true, BlockDirection::South), 0);
        assert_eq!(LecternBlock::get_strong_power(true, BlockDirection::West), 0);
        assert_eq!(LecternBlock::get_strong_power(true, BlockDirection::East), 0);
        assert_eq!(LecternBlock::get_strong_power(false, BlockDirection::Up), 0);

        // Comparator output formula: floor(progress * 14.0) + (hasBook ? 1 : 0)
        assert_eq!(calculate_lectern_comparator_output(false, 0, 10), 0);
        assert_eq!(calculate_lectern_comparator_output(true, 0, 0), 0);
        assert_eq!(calculate_lectern_comparator_output(true, 0, 1), 15);

        // 15-page book (pages 0..=14) gives 1..=15
        for p in 0..15 {
            assert_eq!(calculate_lectern_comparator_output(true, p, 15), (p + 1) as u8);
        }

        // 3-page book: 0 -> 1, 1 -> 8, 2 -> 15
        assert_eq!(calculate_lectern_comparator_output(true, 0, 3), 1);
        assert_eq!(calculate_lectern_comparator_output(true, 1, 3), 8);
        assert_eq!(calculate_lectern_comparator_output(true, 2, 3), 15);
    }

    #[test]
    fn test_composter_fill_levels_fermentation_and_bone_meal_parity() {
        use crate::block::blocks::composter::ComposterBlock;
        use pumpkin_data::BlockDirection;
        use pumpkin_util::math::position::BlockPos;

        // Constants verification
        assert_eq!(ComposterBlock::READY, 8);
        assert_eq!(ComposterBlock::MIN_LEVEL, 0);
        assert_eq!(ComposterBlock::MAX_LEVEL, 7);
        assert_eq!(ComposterBlock::NUM_LEVELS, 9);
        assert_eq!(ComposterBlock::FULL_COMPOSTING_TICKS, 20);
        assert_eq!(ComposterBlock::COMPOSTER_FILL_EVENT, 1500);
        assert_eq!(ComposterBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(ComposterBlock::MAX_COMPARATOR_OUTPUT, 8);
        assert_eq!(ComposterBlock::BONE_MEAL_Y_OFFSET, 1.01);
        assert_eq!(ComposterBlock::BONE_MEAL_HORIZONTAL_OFFSET_MAX, 0.7);
        assert_eq!(ComposterBlock::BONE_MEAL_PICKUP_DELAY_TICKS, 10);

        // Comparator analog signal matches fill level exactly (0..=8)
        for lvl in 0..=8 {
            assert_eq!(ComposterBlock::calculate_comparator_output(lvl), lvl);
        }
        assert_eq!(ComposterBlock::calculate_comparator_output(9), 8); // clamped to READY

        // Ready and can compost checks
        assert!(ComposterBlock::is_ready(8));
        assert!(!ComposterBlock::is_ready(7));
        assert!(!ComposterBlock::is_ready(0));

        assert!(ComposterBlock::can_compost_more(0));
        assert!(ComposterBlock::can_compost_more(6));
        assert!(!ComposterBlock::can_compost_more(7));
        assert!(!ComposterBlock::can_compost_more(8));

        // Hopper insertion & extraction permissions
        assert!(ComposterBlock::can_hopper_insert(0, BlockDirection::Up));
        assert!(ComposterBlock::can_hopper_insert(6, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_insert(7, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_insert(8, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_insert(0, BlockDirection::Down));
        assert!(!ComposterBlock::can_hopper_insert(0, BlockDirection::North));

        assert!(ComposterBlock::can_hopper_extract(8, BlockDirection::Down));
        assert!(!ComposterBlock::can_hopper_extract(7, BlockDirection::Down));
        assert!(!ComposterBlock::can_hopper_extract(0, BlockDirection::Down));
        assert!(!ComposterBlock::can_hopper_extract(8, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_extract(8, BlockDirection::North));

        // Bone meal spawn coordinates
        let base_pos = BlockPos::new(10, 64, 10);
        let spawn = ComposterBlock::calculate_bone_meal_spawn_pos(&base_pos, 0.2, -0.1);
        assert_eq!(spawn.x, 10.7);
        assert_eq!(spawn.y, 65.01);
        assert_eq!(spawn.z, 10.4);

        // Composting chance rolls
        assert!(ComposterBlock::should_level_increase(0, 0.3, 0.2));
        assert!(!ComposterBlock::should_level_increase(0, 0.3, 0.35));
        assert!(ComposterBlock::should_level_increase(6, 1.0, 0.99));
        assert!(!ComposterBlock::should_level_increase(7, 1.0, 0.0)); // cannot increase beyond 7
    }

    #[test]
    fn test_cauldron_levels_extinguish_thaw_and_comparator_parity() {
        use crate::block::blocks::cauldron::CauldronBlock;
        use pumpkin_data::{Block, BlockId};

        // Constants verification
        assert_eq!(CauldronBlock::MIN_FILL_LEVEL, 1);
        assert_eq!(CauldronBlock::MAX_FILL_LEVEL, 3);
        assert_eq!(CauldronBlock::LAVA_SIGNAL, 3);
        assert_eq!(CauldronBlock::EMPTY_SIGNAL, 0);
        assert_eq!(CauldronBlock::FLOOR_LEVEL, 4);
        assert_eq!(CauldronBlock::RAIN_FILL_CHANCE, 0.05);
        assert_eq!(CauldronBlock::POWDER_SNOW_FILL_CHANCE, 0.1);
        assert_eq!(CauldronBlock::DRIP_WATER_EVENT, 1047);
        assert_eq!(CauldronBlock::DRIP_LAVA_EVENT, 1046);

        // Comparator output per block type and state
        let empty_state = Block::CAULDRON.default_state.id;
        assert_eq!(CauldronBlock::calculate_comparator_output(BlockId::CAULDRON, empty_state), 0);
        assert!(!CauldronBlock::is_full(BlockId::CAULDRON, empty_state));

        let lava_state = Block::LAVA_CAULDRON.default_state.id;
        assert_eq!(CauldronBlock::calculate_comparator_output(BlockId::LAVA_CAULDRON, lava_state), 3);
        assert!(CauldronBlock::is_full(BlockId::LAVA_CAULDRON, lava_state));

        for lvl in 1..=3 {
            let lvl_str = lvl.to_string();
            let water_state = Block::WATER_CAULDRON.from_properties(&[("level", &lvl_str)]).to_state_id(&Block::WATER_CAULDRON);
            assert_eq!(CauldronBlock::calculate_comparator_output(BlockId::WATER_CAULDRON, water_state), lvl);
            assert_eq!(CauldronBlock::is_full(BlockId::WATER_CAULDRON, water_state), lvl == 3);

            let snow_state = Block::POWDER_SNOW_CAULDRON.from_properties(&[("level", &lvl_str)]).to_state_id(&Block::POWDER_SNOW_CAULDRON);
            assert_eq!(CauldronBlock::calculate_comparator_output(BlockId::POWDER_SNOW_CAULDRON, snow_state), lvl);
            assert_eq!(CauldronBlock::is_full(BlockId::POWDER_SNOW_CAULDRON, snow_state), lvl == 3);
        }

        // Fluid content height
        assert_eq!(CauldronBlock::get_content_height(BlockId::CAULDRON, empty_state), 0.0);
        assert_eq!(CauldronBlock::get_content_height(BlockId::LAVA_CAULDRON, lava_state), 0.9375);
        let water_lvl1 = Block::WATER_CAULDRON.from_properties(&[("level", "1")]).to_state_id(&Block::WATER_CAULDRON);
        let water_lvl2 = Block::WATER_CAULDRON.from_properties(&[("level", "2")]).to_state_id(&Block::WATER_CAULDRON);
        let water_lvl3 = Block::WATER_CAULDRON.from_properties(&[("level", "3")]).to_state_id(&Block::WATER_CAULDRON);
        assert_eq!(CauldronBlock::get_content_height(BlockId::WATER_CAULDRON, water_lvl1), 0.5625);
        assert_eq!(CauldronBlock::get_content_height(BlockId::WATER_CAULDRON, water_lvl2), 0.75);
        assert_eq!(CauldronBlock::get_content_height(BlockId::WATER_CAULDRON, water_lvl3), 0.9375);

        // Extinguish state transitions (water & powder snow)
        assert_eq!(CauldronBlock::lower_fill_level_on_extinguish(3, false), (BlockId::WATER_CAULDRON, 2));
        assert_eq!(CauldronBlock::lower_fill_level_on_extinguish(2, false), (BlockId::WATER_CAULDRON, 1));
        assert_eq!(CauldronBlock::lower_fill_level_on_extinguish(1, false), (BlockId::CAULDRON, 0));
        assert_eq!(CauldronBlock::lower_fill_level_on_extinguish(3, true), (BlockId::WATER_CAULDRON, 2));
        assert_eq!(CauldronBlock::lower_fill_level_on_extinguish(1, true), (BlockId::CAULDRON, 0));

        // Dripstone drip reception
        assert!(CauldronBlock::can_receive_drip(BlockId::CAULDRON, true, 0));
        assert!(CauldronBlock::can_receive_drip(BlockId::CAULDRON, false, 0));
        assert!(CauldronBlock::can_receive_drip(BlockId::WATER_CAULDRON, true, 1));
        assert!(CauldronBlock::can_receive_drip(BlockId::WATER_CAULDRON, true, 2));
        assert!(!CauldronBlock::can_receive_drip(BlockId::WATER_CAULDRON, true, 3)); // full
        assert!(!CauldronBlock::can_receive_drip(BlockId::WATER_CAULDRON, false, 1)); // lava on water
        assert!(!CauldronBlock::can_receive_drip(BlockId::POWDER_SNOW_CAULDRON, true, 1));
        assert!(!CauldronBlock::can_receive_drip(BlockId::LAVA_CAULDRON, true, 3));

        // Drip events
        assert_eq!(CauldronBlock::get_drip_event(true), 1047);
        assert_eq!(CauldronBlock::get_drip_event(false), 1046);
    }

    #[test]
