    #[test]
    fn test_target_block_bullseye_delay_and_comparator_parity() {
        use crate::block::blocks::redstone::target_block::TargetBlock;
        use pumpkin_data::block_properties::Axis;
        use pumpkin_data::entity::EntityType;

        // Constants parity
        assert_eq!(TargetBlock::ACTIVATION_TICKS_ARROWS, 20);
        assert_eq!(TargetBlock::ACTIVATION_TICKS_OTHER, 8);
        assert_eq!(TargetBlock::MIN_POWER, 1);
        assert_eq!(TargetBlock::MAX_POWER, 15);
        assert_eq!(TargetBlock::DEFAULT_POWER, 0);
        assert_eq!(TargetBlock::BULLSEYE_MIN_DISTANCE, 30.0);
        assert!(!TargetBlock::emits_strong_power());

        // Activation ticks based on projectile type
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::ARROW), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::SPECTRAL_ARROW), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::TRIDENT), 20);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::SNOWBALL), 8);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::EGG), 8);
        assert_eq!(TargetBlock::get_activation_ticks(&EntityType::ENDER_PEARL), 8);

        // Power calculation from distance: max(1, ceil(15.0 * clamp((0.5 - distance)/0.5, 0.0, 1.0)))
        // Bullseye (distance 0.0) -> 15
        assert_eq!(TargetBlock::calculate_power_from_distance(0.0), 15);

        // Intermediate rings
        assert_eq!(TargetBlock::calculate_power_from_distance(0.25), 8);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.45), 2);

        // Outer ring edge (distance 0.5) -> 1
        assert_eq!(TargetBlock::calculate_power_from_distance(0.50), 1);
        assert_eq!(TargetBlock::calculate_power_from_distance(0.60), 1);

        // Hit power per axis
        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.0, 0.0, 0.0, Axis::Y), 15);
        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.0, 0.0, 0.0, Axis::Z), 15);
        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.0, 0.0, 0.0, Axis::X), 15);

        assert_eq!(TargetBlock::calculate_hit_power_on_axis(0.25, 0.0, 0.25, Axis::Y), 8);

        // Comparator output matches power level 0..15
        for power in 0..=15 {
            assert_eq!(TargetBlock::calculate_comparator_signal(power), power);
        }
        assert_eq!(TargetBlock::calculate_comparator_signal(20), 15); // clamped
    }


    #[test]
    fn test_composter_tiers_progression_and_comparator_parity() {
        use crate::block::blocks::composter::ComposterBlock;
        use pumpkin_data::BlockDirection;
        use pumpkin_util::math::position::BlockPos;

        // Constants parity with Vanilla ComposterBlock.java
        assert_eq!(ComposterBlock::MIN_LEVEL, 0);
        assert_eq!(ComposterBlock::MAX_LEVEL, 7);
        assert_eq!(ComposterBlock::READY, 8);
        assert_eq!(ComposterBlock::NUM_LEVELS, 9);
        assert_eq!(ComposterBlock::FULL_COMPOSTING_TICKS, 20);
        assert_eq!(ComposterBlock::COMPOSTER_FILL_EVENT, 1500);
        assert_eq!(ComposterBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(ComposterBlock::MAX_COMPARATOR_OUTPUT, 8);

        // Tier chances
        assert!((ComposterBlock::CHANCE_TIER_1 - 0.30).abs() < 1e-6);
        assert!((ComposterBlock::CHANCE_TIER_2 - 0.50).abs() < 1e-6);
        assert!((ComposterBlock::CHANCE_TIER_3 - 0.65).abs() < 1e-6);
        assert!((ComposterBlock::CHANCE_TIER_4 - 0.85).abs() < 1e-6);
        assert!((ComposterBlock::CHANCE_TIER_5 - 1.00).abs() < 1e-6);

        // Comparator output corresponds directly to level 0..8
        for lvl in 0..=8 {
            assert_eq!(ComposterBlock::calculate_comparator_output(lvl), lvl);
        }
        assert_eq!(ComposterBlock::calculate_comparator_output(9), 8);

        // Readiness and composting capability
        for lvl in 0..=7 {
            assert!(!ComposterBlock::is_ready(lvl));
        }
        assert!(ComposterBlock::is_ready(8));

        for lvl in 0..7 {
            assert!(ComposterBlock::can_compost_more(lvl));
            assert!(ComposterBlock::can_hopper_insert(lvl, BlockDirection::Up));
            assert!(!ComposterBlock::can_hopper_insert(lvl, BlockDirection::Down));
            assert!(!ComposterBlock::can_hopper_insert(lvl, BlockDirection::North));
        }
        assert!(!ComposterBlock::can_compost_more(7));
        assert!(!ComposterBlock::can_compost_more(8));
        assert!(!ComposterBlock::can_hopper_insert(7, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_insert(8, BlockDirection::Up));

        // Hopper extraction: only when ready (level 8) and extracting from below (Down)
        for lvl in 0..=7 {
            assert!(!ComposterBlock::can_hopper_extract(lvl, BlockDirection::Down));
        }
        assert!(ComposterBlock::can_hopper_extract(8, BlockDirection::Down));
        assert!(!ComposterBlock::can_hopper_extract(8, BlockDirection::Up));
        assert!(!ComposterBlock::can_hopper_extract(8, BlockDirection::East));

        // Bone meal drop offsets
        assert_eq!(ComposterBlock::BONE_MEAL_Y_OFFSET, 1.01);
        assert_eq!(ComposterBlock::BONE_MEAL_HORIZONTAL_OFFSET_MAX, 0.7);
        assert_eq!(ComposterBlock::BONE_MEAL_PICKUP_DELAY_TICKS, 10);

        let pos = BlockPos::new(10, 64, -20);
        let drop_pos = ComposterBlock::calculate_bone_meal_spawn_pos(&pos, 0.1, -0.2);
        assert!((drop_pos.x - 10.6).abs() < 1e-6);
        assert!((drop_pos.y - 65.01).abs() < 1e-6);
        assert!((drop_pos.z - (-19.7)).abs() < 1e-6);

        // should_level_increase helper
        assert!(ComposterBlock::should_level_increase(0, 0.5, 0.2));
        assert!(!ComposterBlock::should_level_increase(0, 0.5, 0.6));
        assert!(!ComposterBlock::should_level_increase(7, 1.0, 0.0));
    }

    #[test]
    fn test_respawn_anchor_charges_offsets_explosion_and_comparator_parity() {
        use crate::block::blocks::respawn_anchor::RespawnAnchorBlock;
        use pumpkin_util::math::position::BlockPos;

        // Constants parity with Vanilla RespawnAnchorBlock.java
        assert_eq!(RespawnAnchorBlock::MIN_CHARGES, 0);
        assert_eq!(RespawnAnchorBlock::MAX_CHARGES, 4);
        assert_eq!(RespawnAnchorBlock::EXPLOSION_POWER, 5.0);
        assert_eq!(RespawnAnchorBlock::MAX_COMPARATOR_SIGNAL, 15);
        assert_eq!(RespawnAnchorBlock::NUM_RESPAWN_OFFSETS, 25);

        // Scaled charge level & comparator signal curve: [0, 3, 7, 11, 15]
        let expected_signals = [0u8, 3, 7, 11, 15];
        for (charge, &expected) in expected_signals.iter().enumerate() {
            assert_eq!(
                RespawnAnchorBlock::calculate_comparator_signal(charge as u8),
                expected
            );
            assert_eq!(
                RespawnAnchorBlock::get_scaled_charge_level(charge as u8, 15),
                expected as u32
            );
        }
        assert_eq!(RespawnAnchorBlock::calculate_comparator_signal(5), 15); // clamped

        // Charging capacity
        for charge in 0..4 {
            assert!(RespawnAnchorBlock::can_be_charged(charge));
        }
        assert!(!RespawnAnchorBlock::can_be_charged(4));
        assert!(!RespawnAnchorBlock::can_be_charged(5));

        // Explosion condition: explodes if charges > 0 and respawn_anchor_works is false
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(0, false));
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(0, true));
        assert!(RespawnAnchorBlock::should_explode_in_unsupported_dimension(1, false));
        assert!(RespawnAnchorBlock::should_explode_in_unsupported_dimension(4, false));
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(1, true));
        assert!(!RespawnAnchorBlock::should_explode_in_unsupported_dimension(4, true));

        // Stand-up respawn candidate offsets (25 positions)
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS.len(), 25);
        // Verify horizontal offsets (first 8)
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[0], (0, 0, -1));
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[1], (-1, 0, 0));
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[2], (0, 0, 1));
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[3], (1, 0, 0));
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[4], (-1, 0, -1));
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[5], (1, 0, -1));
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[6], (-1, 0, 1));
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[7], (1, 0, 1));
        // Verify directly above (last)
        assert_eq!(RespawnAnchorBlock::RESPAWN_OFFSETS[24], (0, 1, 0));

        let anchor = BlockPos::new(100, 50, -200);
        assert_eq!(
            RespawnAnchorBlock::get_respawn_candidate_pos(&anchor, 0),
            Some(BlockPos::new(100, 50, -201))
        );
        assert_eq!(
            RespawnAnchorBlock::get_respawn_candidate_pos(&anchor, 24),
            Some(BlockPos::new(100, 51, -200))
        );
        assert_eq!(
            RespawnAnchorBlock::get_respawn_candidate_pos(&anchor, 25),
            None
        );
    }

    #[test]
    fn test_lodestone_compass_binding_tracking_and_transmutation_parity() {
        use crate::item::items::compass::CompassItem;
        use pumpkin_data::data_component_impl::{LodestoneTarget, LodestoneTrackerImpl};
        use pumpkin_data::{Block, item::Item};
        use pumpkin_util::math::position::BlockPos;

        // Constants and item checks parity with Vanilla CompassItem.java
        assert_eq!(
            CompassItem::LODESTONE_COMPASS_TRANSLATION_KEY,
            "item.minecraft.lodestone_compass"
        );
        assert!(CompassItem::is_lodestone(Block::LODESTONE.id));
        assert!(!CompassItem::is_lodestone(Block::STONE.id));

        assert!(CompassItem::is_compass(Item::COMPASS.id));
        assert!(!CompassItem::is_compass(Item::RECOVERY_COMPASS.id));
        assert!(CompassItem::is_recovery_compass(Item::RECOVERY_COMPASS.id));

        // Stack replacement logic:
        // In survival with count == 1, replace existing stack in hand.
        // Otherwise (count > 1 or creative), consume 1 and create a new stack.
        assert!(CompassItem::should_replace_stack(false, 1));
        assert!(!CompassItem::should_replace_stack(false, 2));
        assert!(!CompassItem::should_replace_stack(false, 64));
        assert!(!CompassItem::should_replace_stack(true, 1));
        assert!(!CompassItem::should_replace_stack(true, 64));

        // Create lodestone tracker
        let pos = BlockPos::new(120, 70, -350);
        let tracker = CompassItem::create_lodestone_tracker("minecraft:overworld", &pos);
        assert!(tracker.tracked);
        assert_eq!(
            tracker.target,
            Some(LodestoneTarget {
                dimension: "minecraft:overworld".to_string(),
                x: 120,
                y: 70,
                z: -350,
            })
        );

        // Tracker ticking across dimensions (Vanilla LodestoneTracker.java:28-30)
        // If player is in a different dimension, the tracker is retained unchanged
        let ticked_diff_dim = CompassItem::tick_tracker(&tracker, "minecraft:the_nether", false);
        assert_eq!(ticked_diff_dim, tracker);

        // Tracker ticking in same dimension:
        // If lodestone block is present, tracker is retained
        let ticked_present = CompassItem::tick_tracker(&tracker, "minecraft:overworld", true);
        assert_eq!(ticked_present, tracker);

        // If lodestone block is broken/absent in same dimension, target becomes None but tracked remains true (spins randomly)
        let ticked_broken = CompassItem::tick_tracker(&tracker, "minecraft:overworld", false);
        assert_eq!(
            ticked_broken,
            LodestoneTrackerImpl {
                target: None,
                tracked: true,
            }
        );
    }

    #[test]
    fn test_enchanting_table_bookshelf_offsets_transmitters_and_cost_parity() {
        use crate::block::blocks::enchanting_table::EnchantingTableBlock;

        // Constants verification
        assert_eq!(EnchantingTableBlock::MAX_BOOKSHELVES, 15);
        assert_eq!(EnchantingTableBlock::TOTAL_BOOKSHELF_POSITIONS, 32);
        assert_eq!(EnchantingTableBlock::BOOKSHELF_OFFSETS.len(), 32);

        // Verify all 32 offsets satisfy Vanilla filter:
        // x in -2..=2, z in -2..=2, y in 0..=1, and (|x| == 2 || |z| == 2)
        for &(dx, dy, dz) in &EnchantingTableBlock::BOOKSHELF_OFFSETS {
            assert!(dx >= -2 && dx <= 2);
            assert!(dy >= 0 && dy <= 1);
            assert!(dz >= -2 && dz <= 2);
            assert!(dx.abs() == 2 || dz.abs() == 2);

            // Transmitter offset must match Vanilla: (dx / 2, dy, dz / 2)
            let trans = EnchantingTableBlock::get_transmitter_offset((dx, dy, dz));
            assert_eq!(trans, (dx / 2, dy, dz / 2));
            assert!(trans.0 >= -1 && trans.0 <= 1);
            assert!(trans.2 >= -1 && trans.2 <= 1);
            assert_eq!(trans.1, dy);
        }

        // Specific transmitter coordinates verification
        // Corner bookshelf at (-2, 0, -2) -> intermediate transmitter at (-1, 0, -1)
        assert_eq!(
            EnchantingTableBlock::get_transmitter_offset((-2, 0, -2)),
            (-1, 0, -1)
        );
        // Face bookshelf at (0, 0, 2) -> intermediate transmitter at (0, 0, 1)
        assert_eq!(
            EnchantingTableBlock::get_transmitter_offset((0, 0, 2)),
            (0, 0, 1)
        );
        // Diagonal offset at (2, 1, 1) -> intermediate transmitter at (1, 1, 0)
        assert_eq!(
            EnchantingTableBlock::get_transmitter_offset((2, 1, 1)),
            (1, 1, 0)
        );

        // Validation helper
        assert!(EnchantingTableBlock::is_valid_bookshelf_at_offset((2, 0, 0), true, true));
        assert!(!EnchantingTableBlock::is_valid_bookshelf_at_offset((2, 0, 0), true, false));
        assert!(!EnchantingTableBlock::is_valid_bookshelf_at_offset((2, 0, 0), false, true));

        // Cost calculation parity with Vanilla EnchantmentHelper.java:
        // Slot 0 (top): max(selected / 3, 1), requires cost >= 1
        // Slot 1 (middle): selected * 2 / 3 + 1, requires cost >= 2
        // Slot 2 (bottom): max(selected, bookcases * 2), requires cost >= 3

        // Zero bookcases: selected = 10
        assert_eq!(
            crate::block::blocks::enchanting_table::calculate_enchantment_cost(0, 0, 10),
            3
        );
        assert_eq!(
            crate::block::blocks::enchanting_table::calculate_enchantment_cost(1, 0, 10),
            7
        );
        assert_eq!(
            crate::block::blocks::enchanting_table::calculate_enchantment_cost(2, 0, 10),
            10
        );

        // 15 bookcases: selected = 24
        // Slot 0: 24 / 3 = 8
        assert_eq!(
            crate::block::blocks::enchanting_table::calculate_enchantment_cost(0, 15, 24),
            8
        );
        // Slot 1: 24 * 2 / 3 + 1 = 17
        assert_eq!(
            crate::block::blocks::enchanting_table::calculate_enchantment_cost(1, 15, 24),
            17
        );
        // Slot 2: max(24, 15 * 2 = 30) = 30 (max level 30 enchantment!)
        assert_eq!(
            crate::block::blocks::enchanting_table::calculate_enchantment_cost(2, 15, 24),
            30
        );

        // Cap at 15 bookcases: passing 20 bookcases should clamp to 15
        assert_eq!(
            crate::block::blocks::enchanting_table::calculate_enchantment_cost(2, 20, 24),
            30
        );
    }

    #[test]
    fn test_beacon_pyramid_levels_radius_duration_and_buffs_parity() {
        use crate::block::entities::beacon::{
            BeaconBlockEntity, BEACON_BLOCKS_CHECK_PER_TICK, BEACON_EFFECT_INTERVAL_TICKS,
            BEACON_LEVELS_NEEDED_FOR_SECONDARY, BEACON_MAX_LEVELS, TOTAL_PYRAMID_BLOCKS_MAX,
        };
        use pumpkin_data::Block;

        // Constants parity with Vanilla BeaconBlockEntity.java
        assert_eq!(BEACON_MAX_LEVELS, 4);
        assert_eq!(BEACON_LEVELS_NEEDED_FOR_SECONDARY, 4);
        assert_eq!(BEACON_BLOCKS_CHECK_PER_TICK, 10);
        assert_eq!(BEACON_EFFECT_INTERVAL_TICKS, 80);
        assert_eq!(TOTAL_PYRAMID_BLOCKS_MAX, 164);

        // Pyramid layer block counts: (2 * step + 1)^2
        // Layer 1: 3x3 = 9
        assert_eq!(BeaconBlockEntity::calculate_pyramid_blocks_for_layer(1), 9);
        // Layer 2: 5x5 = 25
        assert_eq!(BeaconBlockEntity::calculate_pyramid_blocks_for_layer(2), 25);
        // Layer 3: 7x7 = 49
        assert_eq!(BeaconBlockEntity::calculate_pyramid_blocks_for_layer(3), 49);
        // Layer 4: 9x9 = 81
        assert_eq!(BeaconBlockEntity::calculate_pyramid_blocks_for_layer(4), 81);

        // Cumulative pyramid block counts
        assert_eq!(BeaconBlockEntity::calculate_total_pyramid_blocks(0), 0);
        assert_eq!(BeaconBlockEntity::calculate_total_pyramid_blocks(1), 9);
        assert_eq!(BeaconBlockEntity::calculate_total_pyramid_blocks(2), 34);
        assert_eq!(BeaconBlockEntity::calculate_total_pyramid_blocks(3), 83);
        assert_eq!(BeaconBlockEntity::calculate_total_pyramid_blocks(4), 164);
        assert_eq!(BeaconBlockEntity::calculate_total_pyramid_blocks(5), 164); // clamped to max 4

        // Effect range parity: levels * 10 + 10
        assert_eq!(BeaconBlockEntity::calculate_effect_range(0), 10.0);
        assert_eq!(BeaconBlockEntity::calculate_effect_range(1), 20.0);
        assert_eq!(BeaconBlockEntity::calculate_effect_range(2), 30.0);
        assert_eq!(BeaconBlockEntity::calculate_effect_range(3), 40.0);
        assert_eq!(BeaconBlockEntity::calculate_effect_range(4), 50.0);

        // Effect duration ticks parity: (9 + levels * 2) * 20
        assert_eq!(BeaconBlockEntity::calculate_effect_duration_ticks(0), 180); // 9s
        assert_eq!(BeaconBlockEntity::calculate_effect_duration_ticks(1), 220); // 11s
        assert_eq!(BeaconBlockEntity::calculate_effect_duration_ticks(2), 260); // 13s
        assert_eq!(BeaconBlockEntity::calculate_effect_duration_ticks(3), 300); // 15s
        assert_eq!(BeaconBlockEntity::calculate_effect_duration_ticks(4), 340); // 17s

        // Valid base blocks: Iron, Gold, Diamond, Emerald, Netherite blocks
        assert!(BeaconBlockEntity::is_valid_base_block(&Block::IRON_BLOCK));
        assert!(BeaconBlockEntity::is_valid_base_block(&Block::GOLD_BLOCK));
        assert!(BeaconBlockEntity::is_valid_base_block(&Block::DIAMOND_BLOCK));
        assert!(BeaconBlockEntity::is_valid_base_block(&Block::EMERALD_BLOCK));
        assert!(BeaconBlockEntity::is_valid_base_block(&Block::NETHERITE_BLOCK));

        assert!(!BeaconBlockEntity::is_valid_base_block(&Block::STONE));
        assert!(!BeaconBlockEntity::is_valid_base_block(&Block::COPPER_BLOCK));
        assert!(!BeaconBlockEntity::is_valid_base_block(&Block::OBSIDIAN));

        // Secondary effect permission
        for lvl in 0..4 {
            assert!(!BeaconBlockEntity::is_secondary_effect_allowed(lvl));
        }
        assert!(BeaconBlockEntity::is_secondary_effect_allowed(4));
        assert!(BeaconBlockEntity::is_secondary_effect_allowed(5));
    }

    #[test]
    fn test_conduit_frame_activation_range_hunting_and_attack_parity() {
        use crate::block::entities::conduit::{
            calculate_conduit_effect_range, ConduitBlockEntity,
        };

        // Constants parity with Vanilla ConduitBlockEntity.java
        assert_eq!(ConduitBlockEntity::MIN_ACTIVE_SIZE, 16);
        assert_eq!(ConduitBlockEntity::MIN_KILL_SIZE, 42);
        assert_eq!(ConduitBlockEntity::TOTAL_FRAME_POSITIONS, 42);
        assert_eq!(ConduitBlockEntity::KILL_RANGE, 8.0);
        assert_eq!(ConduitBlockEntity::ATTACK_DAMAGE, 4.0);
        assert_eq!(ConduitBlockEntity::EFFECT_DURATION, 13);
        assert_eq!(ConduitBlockEntity::EFFECT_DURATION_TICKS, 260);
        assert_eq!(ConduitBlockEntity::UPDATE_INTERVAL_TICKS, 40);
        assert_eq!(ConduitBlockEntity::AMBIENT_SOUND_INTERVAL_TICKS, 80);

        // Frame positions count verification across 5x5x5 volume (-2..=2)
        let mut valid_offsets_count = 0;
        for ox in -2..=2 {
            for oy in -2..=2 {
                for oz in -2..=2 {
                    if ConduitBlockEntity::is_valid_frame_block_offset(ox, oy, oz) {
                        valid_offsets_count += 1;
                    }
                }
            }
        }
        assert_eq!(valid_offsets_count, 42);

        // Core offsets that must NOT be frame blocks
        assert!(!ConduitBlockEntity::is_valid_frame_block_offset(0, 0, 0));
        assert!(!ConduitBlockEntity::is_valid_frame_block_offset(1, 0, 0));
        assert!(!ConduitBlockEntity::is_valid_frame_block_offset(0, 1, 0));
        assert!(!ConduitBlockEntity::is_valid_frame_block_offset(0, 0, 1));
        assert!(!ConduitBlockEntity::is_valid_frame_block_offset(1, 1, 1));
        // Extreme outer corners (2, 2, 2) are NOT frame blocks (conduit rings are 3 orthogonal circles)
        assert!(!ConduitBlockEntity::is_valid_frame_block_offset(2, 2, 2));
        assert!(!ConduitBlockEntity::is_valid_frame_block_offset(-2, -2, -2));

        // Ring positions that ARE frame blocks:
        // Ring 1 (XY plane, z=0):
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(2, 0, 0));
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(0, 2, 0));
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(-2, 0, 0));
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(0, -2, 0));
        // Ring 2 (YZ plane, x=0):
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(0, 2, 0));
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(0, 0, 2));
        // Ring 3 (XZ plane, y=0):
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(2, 0, 0));
        assert!(ConduitBlockEntity::is_valid_frame_block_offset(0, 0, 2));

        // Effect range formula: (active_size / 7) * 16
        // Under 16: inactive (below threshold)
        for size in 0..16 {
            assert!(!ConduitBlockEntity::is_active_size(size));
            assert!(!ConduitBlockEntity::is_hunting_size(size));
        }

        // Active range tiers:
        // 16..20 blocks: 32 blocks range
        for size in 16..21 {
            assert!(ConduitBlockEntity::is_active_size(size));
            assert!(!ConduitBlockEntity::is_hunting_size(size));
            assert_eq!(calculate_conduit_effect_range(size), 32);
        }
        // 21..27 blocks: 48 blocks range
        for size in 21..28 {
            assert_eq!(calculate_conduit_effect_range(size), 48);
        }
        // 28..34 blocks: 64 blocks range
        for size in 28..35 {
            assert_eq!(calculate_conduit_effect_range(size), 64);
        }
        // 35..41 blocks: 80 blocks range
        for size in 35..42 {
            assert_eq!(calculate_conduit_effect_range(size), 80);
        }
        // 42 blocks (full complete frame): 96 blocks range + hunting mode active!
        assert!(ConduitBlockEntity::is_active_size(42));
        assert!(ConduitBlockEntity::is_hunting_size(42));
        assert_eq!(calculate_conduit_effect_range(42), 96);
    }

    #[test]
    fn test_mace_smash_attack_fall_damage_scaling_and_knockback_parity() {
        use crate::item::items::mace::MaceItem;

        // Constants parity with Vanilla MaceItem.java
        assert_eq!(MaceItem::DEFAULT_ATTACK_DAMAGE, 5.0);
        assert_eq!(MaceItem::DEFAULT_ATTACK_SPEED, -3.4);
        assert_eq!(MaceItem::SMASH_ATTACK_FALL_THRESHOLD, 1.5);
        assert_eq!(MaceItem::SMASH_ATTACK_HEAVY_THRESHOLD, 5.0);
        assert_eq!(MaceItem::SMASH_ATTACK_KNOCKBACK_RADIUS, 3.5);
        assert_eq!(MaceItem::SMASH_ATTACK_KNOCKBACK_POWER, 0.7);
        assert_eq!(MaceItem::SMASH_PARTICLES_EVENT_ID, 2013);
        assert_eq!(MaceItem::SMASH_PARTICLES_DATA, 750);

        // Smash attack eligibility: fall_distance > 1.5 and not fall flying
        assert!(!MaceItem::can_smash_attack(0.0, false));
        assert!(!MaceItem::can_smash_attack(1.0, false));
        assert!(!MaceItem::can_smash_attack(1.5, false));
        assert!(MaceItem::can_smash_attack(1.51, false));
        assert!(MaceItem::can_smash_attack(3.0, false));
        assert!(MaceItem::can_smash_attack(10.0, false));

        // Elytra fall flying prevents smash attack
        assert!(!MaceItem::can_smash_attack(5.0, true));
        assert!(!MaceItem::can_smash_attack(10.0, true));

        // Heavy smash threshold (> 5.0 blocks fall)
        assert!(!MaceItem::is_heavy_smash(1.5));
        assert!(!MaceItem::is_heavy_smash(5.0));
        assert!(MaceItem::is_heavy_smash(5.01));
        assert!(MaceItem::is_heavy_smash(8.0));

        // Piecewise smash damage bonus curve parity (Vanilla MaceItem.java:95-105):
        // Tier 1: <= 3.0 blocks -> 4.0 * fall_distance
        assert_eq!(MaceItem::calculate_smash_damage_bonus(1.5), 6.0);
        assert_eq!(MaceItem::calculate_smash_damage_bonus(2.0), 8.0);
        assert_eq!(MaceItem::calculate_smash_damage_bonus(3.0), 12.0);

        // Tier 2: 3.0 < fall_distance <= 8.0 blocks -> 12.0 + 2.0 * (fall_distance - 3.0)
        assert_eq!(MaceItem::calculate_smash_damage_bonus(4.0), 14.0);
        assert_eq!(MaceItem::calculate_smash_damage_bonus(5.0), 16.0);
        assert_eq!(MaceItem::calculate_smash_damage_bonus(8.0), 22.0);

        // Tier 3: > 8.0 blocks -> 22.0 + 1.0 * (fall_distance - 8.0)
        assert_eq!(MaceItem::calculate_smash_damage_bonus(9.0), 23.0);
        assert_eq!(MaceItem::calculate_smash_damage_bonus(10.0), 24.0);
        assert_eq!(MaceItem::calculate_smash_damage_bonus(20.0), 34.0);

        // Compare with combat helper mace_smash_damage_bonus
        for dist in [1.5, 2.5, 3.0, 5.0, 8.0, 12.0, 25.0] {
            assert_eq!(
                MaceItem::calculate_smash_damage_bonus(dist),
                crate::entity::combat::mace_smash_damage_bonus(dist)
            );
        }
    }

    #[test]
    fn test_wind_charge_physics_radius_cooldown_and_dispense_parity() {
        use crate::item::items::wind_charge::WindChargeItem;

        // Constants parity with Vanilla WindChargeItem.java & WindCharge.java
        assert_eq!(WindChargeItem::PROJECTILE_SHOOT_POWER, 1.5);
        assert_eq!(WindChargeItem::COOLDOWN_TICKS, 10);
        assert_eq!(WindChargeItem::DISPENSE_EVENT_ID, 1051);
        assert_eq!(WindChargeItem::DISPENSER_POWER, 1.0);
        assert!((WindChargeItem::DISPENSER_UNCERTAINTY - 6.6666665).abs() < 1e-6);
        assert_eq!(WindChargeItem::PLAYER_EXPLOSION_RADIUS, 1.2);
        assert_eq!(WindChargeItem::BREEZE_EXPLOSION_RADIUS, 3.0);
        assert_eq!(WindChargeItem::DEFLECT_COOLDOWN_TICKS, 5);

        // Throw sound pitch calculation parity: 0.4 / (rand * 0.4 + 0.8)
        // Min rand (0.0): 0.4 / 0.8 = 0.5
        assert!((WindChargeItem::calculate_throw_pitch(0.0) - 0.5).abs() < 1e-6);
        // Max rand (1.0): 0.4 / 1.2 = 0.33333334
        assert!((WindChargeItem::calculate_throw_pitch(1.0) - (0.4 / 1.2)).abs() < 1e-6);
        // Mid rand (0.5): 0.4 / (0.2 + 0.8) = 0.4 / 1.0 = 0.4
        assert!((WindChargeItem::calculate_throw_pitch(0.5) - 0.4).abs() < 1e-6);

        // Cooldown ticks helper matches 10 ticks
        assert_eq!(WindChargeItem::get_cooldown_ticks(), 10);
    }

    #[test]
    fn test_vault_key_validation_activation_range_and_states_parity() {
        use crate::block::blocks::vault::VaultBlock;
        use pumpkin_data::block_properties::VaultState;
        use pumpkin_data::item::Item;

        // Constants parity with Vanilla VaultConfig.java
        assert_eq!(VaultBlock::ACTIVATION_RANGE, 4.0);
        assert_eq!(VaultBlock::DEACTIVATION_RANGE, 4.5);

        // Activation range checks (squared distances)
        assert!(VaultBlock::is_within_activation_range(0.0));
        assert!(VaultBlock::is_within_activation_range(16.0)); // 4.0^2
        assert!(!VaultBlock::is_within_activation_range(16.01));

        // Deactivation range checks (squared distances)
        assert!(VaultBlock::is_within_deactivation_range(16.0));
        assert!(VaultBlock::is_within_deactivation_range(20.25)); // 4.5^2
        assert!(!VaultBlock::is_within_deactivation_range(20.26));

        // Regular Vault key validation: Trial Key only
        assert!(VaultBlock::is_valid_key(Item::TRIAL_KEY.id, false));
        assert!(!VaultBlock::is_valid_key(Item::OMINOUS_TRIAL_KEY.id, false));
        assert!(!VaultBlock::is_valid_key(Item::STICK.id, false));

        // Ominous Vault key validation: Ominous Trial Key only
        assert!(VaultBlock::is_valid_key(Item::OMINOUS_TRIAL_KEY.id, true));
        assert!(!VaultBlock::is_valid_key(Item::TRIAL_KEY.id, true));
        assert!(!VaultBlock::is_valid_key(Item::EMERALD.id, true));

        // Can insert key states
        assert!(VaultBlock::can_insert_key(VaultState::Active));
        assert!(VaultBlock::can_insert_key(VaultState::Inactive));
        assert!(!VaultBlock::can_insert_key(VaultState::Unlocking));
        assert!(!VaultBlock::can_insert_key(VaultState::Ejecting));
    }

    #[test]
    fn test_trial_spawner_player_scaling_scan_range_and_cooldown_parity() {
        use crate::block::blocks::trial_spawner::TrialSpawnerBlock;

        // Constants parity with Vanilla TrialSpawner.java & TrialSpawnerConfig.java
        assert_eq!(TrialSpawnerBlock::DEFAULT_PLAYER_SCAN_RANGE, 14);
        assert_eq!(TrialSpawnerBlock::DEFAULT_COOLDOWN_TICKS, 36000); // 30 min (36000 ticks)
        assert_eq!(TrialSpawnerBlock::DETECT_PLAYER_SPAWN_BUFFER_TICKS, 40); // 2s (40 ticks)
        assert_eq!(TrialSpawnerBlock::MAX_MOB_TRACKING_DISTANCE, 47.0);

        // Player scan range checks
        let range = TrialSpawnerBlock::DEFAULT_PLAYER_SCAN_RANGE;
        assert!(TrialSpawnerBlock::is_within_player_scan_range(0.0, range));
        assert!(TrialSpawnerBlock::is_within_player_scan_range(196.0, range)); // 14^2 = 196
        assert!(!TrialSpawnerBlock::is_within_player_scan_range(196.01, range));

        // Mob tracking distance checks (47 blocks = 2209 sq)
        assert!(TrialSpawnerBlock::is_within_mob_tracking_distance(2209.0));
        assert!(!TrialSpawnerBlock::is_within_mob_tracking_distance(2209.01));

        // Scaling formulas:
        // total_mobs = floor(base + added_per_player * (player_count - 1))
        // simultaneous_mobs = floor(base + added_per_player * (player_count - 1))
        // Example: base total 6.0, added 2.0; base simul 2.0, added 1.0
        // 1 player (0 additional): total = 6, simul = 2
        assert_eq!(TrialSpawnerBlock::calculate_target_total_mobs(6.0, 2.0, 1), 6);
        assert_eq!(TrialSpawnerBlock::calculate_target_simultaneous_mobs(2.0, 1.0, 1), 2);

        // 2 players (1 additional): total = 6 + 2 = 8, simul = 2 + 1 = 3
        assert_eq!(TrialSpawnerBlock::calculate_target_total_mobs(6.0, 2.0, 2), 8);
        assert_eq!(TrialSpawnerBlock::calculate_target_simultaneous_mobs(2.0, 1.0, 2), 3);

        // 4 players (3 additional): total = 6 + 6 = 12, simul = 2 + 3 = 5
        assert_eq!(TrialSpawnerBlock::calculate_target_total_mobs(6.0, 2.0, 4), 12);
        assert_eq!(TrialSpawnerBlock::calculate_target_simultaneous_mobs(2.0, 1.0, 4), 5);
    }

    #[test]
    fn test_decorated_pot_sherds_insert_pitch_shattering_and_comparator_parity() {
        use crate::block::blocks::decorated_pot::DecoratedPotBlock;

        // Constants parity with Vanilla DecoratedPotBlock.java
        assert_eq!(DecoratedPotBlock::TOTAL_SHERD_FACES, 4);
        assert_eq!(DecoratedPotBlock::INSERT_DUST_PLUME_PARTICLES, 7);

        // Shatter condition: broken with tool and without silk touch
        assert!(DecoratedPotBlock::can_break_pot_shatter(true, false));
        assert!(!DecoratedPotBlock::can_break_pot_shatter(true, true)); // silk touch preserves pot
        assert!(!DecoratedPotBlock::can_break_pot_shatter(false, false)); // fist preserves pot

        // Insert sound pitch calculation: 0.7 + 0.5 * (count / maxStack)
        // Empty to 1 item in 64-stack: 0.7 + 0.5 * (1 / 64)
        assert!((DecoratedPotBlock::calculate_insert_pitch(1, 64) - (0.7 + 0.5 * (1.0 / 64.0))).abs() < 1e-6);
        // Half full (32 / 64): 0.7 + 0.5 * 0.5 = 0.95
        assert!((DecoratedPotBlock::calculate_insert_pitch(32, 64) - 0.95).abs() < 1e-6);
        // Full (64 / 64): 0.7 + 0.5 * 1.0 = 1.2
        assert!((DecoratedPotBlock::calculate_insert_pitch(64, 64) - 1.2).abs() < 1e-6);

        // Comparator output formula parity:
        // Empty -> 0
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(0, 64), 0);
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(0, 16), 0);
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(0, 1), 0);

        // 64-stack item:
        // 1 item -> 1 + floor((1/64) * 14) = 1
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(1, 64), 1);
        // 32 items -> 1 + floor(0.5 * 14) = 1 + 7 = 8
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(32, 64), 8);
        // 64 items -> 1 + floor(1.0 * 14) = 1 + 14 = 15
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(64, 64), 15);

        // 16-stack item (e.g. Ender Pearls):
        // 1 item -> 1 + floor((1/16) * 14) = 1
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(1, 16), 1);
        // 8 items -> 1 + floor(0.5 * 14) = 8
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(8, 16), 8);
        // 16 items -> 15
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(16, 16), 15);

        // 1-stack item (e.g. Sword, Elytra):
        // 1 item -> 1 + floor(1.0 * 14) = 15
        assert_eq!(DecoratedPotBlock::calculate_comparator_output(1, 1), 15);
    }
    #[test]
    fn test_ominous_bottle_amplifier_duration_and_omen_conversion_parity() {
        use crate::item::items::ominous_bottle::OminousBottleItem;
        use pumpkin_util::Difficulty;

        // Constants parity with Vanilla OminousBottleAmplifier.java and TrialSpawnerStateData.java
        assert_eq!(OminousBottleItem::EFFECT_DURATION, 120_000); // 100 minutes = 120,000 ticks
        assert_eq!(OminousBottleItem::MIN_AMPLIFIER, 0); // Bad Omen I
        assert_eq!(OminousBottleItem::MAX_AMPLIFIER, 4); // Bad Omen V
        assert_eq!(OminousBottleItem::TRIAL_OMEN_PER_BAD_OMEN_LEVEL, 18_000); // 15 mins per level
        assert_eq!(OminousBottleItem::RAID_OMEN_DURATION, 600); // 30 seconds

        // Amplifier clamping parity
        assert_eq!(OminousBottleItem::calculate_bad_omen_amplifier(-1), 0);
        assert_eq!(OminousBottleItem::calculate_bad_omen_amplifier(0), 0);
        assert_eq!(OminousBottleItem::calculate_bad_omen_amplifier(2), 2);
        assert_eq!(OminousBottleItem::calculate_bad_omen_amplifier(4), 4);
        assert_eq!(OminousBottleItem::calculate_bad_omen_amplifier(99), 4);

        // Bad Omen -> Trial Omen duration scaling (TrialSpawnerStateData.java:207: 18000 * (amplifier + 1))
        assert_eq!(OminousBottleItem::calculate_trial_omen_duration(0), 18_000); // Level 1: 15 mins
        assert_eq!(OminousBottleItem::calculate_trial_omen_duration(1), 36_000); // Level 2: 30 mins
        assert_eq!(OminousBottleItem::calculate_trial_omen_duration(2), 54_000); // Level 3: 45 mins
        assert_eq!(OminousBottleItem::calculate_trial_omen_duration(3), 72_000); // Level 4: 60 mins
        assert_eq!(OminousBottleItem::calculate_trial_omen_duration(4), 90_000); // Level 5: 75 mins

        // Village raid conversion condition (BadOmenMobEffect.java:21-24)
        assert!(OminousBottleItem::can_convert_bad_omen_to_raid_omen(false, Difficulty::Normal, true));
        assert!(OminousBottleItem::can_convert_bad_omen_to_raid_omen(false, Difficulty::Hard, true));
        // Spectator bypasses raid
        assert!(!OminousBottleItem::can_convert_bad_omen_to_raid_omen(true, Difficulty::Normal, true));
        // Peaceful difficulty prevents raids
        assert!(!OminousBottleItem::can_convert_bad_omen_to_raid_omen(false, Difficulty::Peaceful, true));
        // Outside village does not convert
        assert!(!OminousBottleItem::can_convert_bad_omen_to_raid_omen(false, Difficulty::Normal, false));

        // Raid Omen execution tick parity (RaidOmenMobEffect.java:16: remainingDuration == 1)
        assert!(OminousBottleItem::should_trigger_raid_from_raid_omen(1));
        assert!(!OminousBottleItem::should_trigger_raid_from_raid_omen(2));
        assert!(!OminousBottleItem::should_trigger_raid_from_raid_omen(600));
    }
    #[test]
    fn test_brushable_block_dusting_stages_break_threshold_and_retraction_parity() {
        use crate::block::blocks::brushable_block::BrushableBlock;

        // Constants parity with Vanilla BrushableBlock.java & BrushableBlockEntity.java
        assert_eq!(BrushableBlock::REQUIRED_BRUSHES_TO_BREAK, 10);
        assert_eq!(BrushableBlock::BRUSH_COOLDOWN_TICKS, 10); // 0.5s cooldown between brushes
        assert_eq!(BrushableBlock::BRUSH_RESET_TICKS, 40); // 2.0s before retraction starts
        assert_eq!(BrushableBlock::RETRACTION_SPEED_TICKS, 4); // decays every 4 ticks
        assert_eq!(BrushableBlock::RETRACTION_BRUSH_STEP, 2); // decays 2 brush counts per step
        assert_eq!(BrushableBlock::TICK_DELAY, 2);
        assert_eq!(BrushableBlock::MAX_DUSTED_STAGE, 3);

        // Completion state / dusted mapping parity (BrushableBlockEntity.java:230-238)
        // 0 hits -> dusted 0
        assert_eq!(BrushableBlock::calculate_dusted_stage(0), 0);
        assert_eq!(BrushableBlock::calculate_dusted_stage(-5), 0);

        // 1..2 hits (< 3) -> dusted 1
        assert_eq!(BrushableBlock::calculate_dusted_stage(1), 1);
        assert_eq!(BrushableBlock::calculate_dusted_stage(2), 1);

        // 3..5 hits (< 6) -> dusted 2
        assert_eq!(BrushableBlock::calculate_dusted_stage(3), 2);
        assert_eq!(BrushableBlock::calculate_dusted_stage(4), 2);
        assert_eq!(BrushableBlock::calculate_dusted_stage(5), 2);

        // 6..9 hits (>= 6) -> dusted 3
        assert_eq!(BrushableBlock::calculate_dusted_stage(6), 3);
        assert_eq!(BrushableBlock::calculate_dusted_stage(7), 3);
        assert_eq!(BrushableBlock::calculate_dusted_stage(8), 3);
        assert_eq!(BrushableBlock::calculate_dusted_stage(9), 3);

        // 10+ hits -> complete
        assert!(!BrushableBlock::is_brushing_complete(9));
        assert!(BrushableBlock::is_brushing_complete(10));
        assert!(BrushableBlock::is_brushing_complete(12));

        // Retraction decay step parity (BrushableBlockEntity.java:151: Math.max(0, brushCount - 2))
        assert_eq!(BrushableBlock::decay_brush_count(9), 7);
        assert_eq!(BrushableBlock::decay_brush_count(7), 5);
        assert_eq!(BrushableBlock::decay_brush_count(5), 3);
        assert_eq!(BrushableBlock::decay_brush_count(3), 1);
        assert_eq!(BrushableBlock::decay_brush_count(2), 0);
        assert_eq!(BrushableBlock::decay_brush_count(1), 0);
        assert_eq!(BrushableBlock::decay_brush_count(0), 0);
    }
    #[test]
    fn test_copper_bulb_t_flip_flop_rising_edge_light_levels_and_comparator_parity() {
        use crate::block::blocks::redstone::copper_bulb::CopperBulbBlock;
        use pumpkin_data::BlockId;

        // Constants parity
        assert_eq!(CopperBulbBlock::DEFAULT_POWERED, false);
        assert_eq!(CopperBulbBlock::DEFAULT_LIT, false);
        assert_eq!(CopperBulbBlock::COMPARATOR_SIGNAL_LIT, 15);
        assert_eq!(CopperBulbBlock::COMPARATOR_SIGNAL_UNLIT, 0);

        // Comparator output
        assert_eq!(CopperBulbBlock::get_comparator_output_value(true), 15);
        assert_eq!(CopperBulbBlock::get_comparator_output_value(false), 0);

        // T-Flip-Flop Redstone evaluation (CopperBulbBlock.java:42-53)
        // 1. Initial state: unlit (false), unpowered (false). Rising edge (has_signal = true)
        let (new_lit, new_powered, sound) = CopperBulbBlock::evaluate_t_flip_flop(false, false, true);
        assert_eq!(new_lit, true);
        assert_eq!(new_powered, true);
        assert_eq!(sound, Some(true)); // plays TURN_ON sound

        // 2. Continuous power: lit (true), powered (true). Signal continues (has_signal = true)
        let (new_lit, new_powered, sound) = CopperBulbBlock::evaluate_t_flip_flop(true, true, true);
        assert_eq!(new_lit, true);
        assert_eq!(new_powered, true);
        assert_eq!(sound, None); // no sound, no state change

        // 3. Falling edge: lit (true), powered (true). Signal removed (has_signal = false)
        let (new_lit, new_powered, sound) = CopperBulbBlock::evaluate_t_flip_flop(true, true, false);
        assert_eq!(new_lit, true); // lit persists!
        assert_eq!(new_powered, false); // power drops
        assert_eq!(sound, None); // falling edge produces no sound

        // 4. Second rising edge: lit (true), powered (false). Signal arrives (has_signal = true)
        let (new_lit, new_powered, sound) = CopperBulbBlock::evaluate_t_flip_flop(true, false, true);
        assert_eq!(new_lit, false); // toggles off!
        assert_eq!(new_powered, true);
        assert_eq!(sound, Some(false)); // plays TURN_OFF sound

        // 5. Second falling edge: lit (false), powered (true). Signal removed (has_signal = false)
        let (new_lit, new_powered, sound) = CopperBulbBlock::evaluate_t_flip_flop(false, true, false);
        assert_eq!(new_lit, false); // stays off
        assert_eq!(new_powered, false); // power drops
        assert_eq!(sound, None);

        // Weathering Light Level Parity (Blocks.java: COPPER_BULB lit light levels)
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::COPPER_BULB, true), 15);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::EXPOSED_COPPER_BULB, true), 12);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WEATHERED_COPPER_BULB, true), 8);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::OXIDIZED_COPPER_BULB, true), 4);

        // Waxed variants maintain same light levels
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_COPPER_BULB, true), 15);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_EXPOSED_COPPER_BULB, true), 12);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_WEATHERED_COPPER_BULB, true), 8);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WAXED_OXIDIZED_COPPER_BULB, true), 4);

        // All unlit bulbs emit 0 light
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::COPPER_BULB, false), 0);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::EXPOSED_COPPER_BULB, false), 0);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::WEATHERED_COPPER_BULB, false), 0);
        assert_eq!(CopperBulbBlock::get_light_level(BlockId::OXIDIZED_COPPER_BULB, false), 0);
    }
    #[test]
    fn test_ominous_item_spawner_delay_sound_and_spawn_parity() {
        use crate::entity::ominous_item_spawner::{
            DEFAULT_MIN_SPAWN_TICKS, DEFAULT_MAX_SPAWN_TICKS, TICKS_BEFORE_ABOUT_TO_SPAWN_SOUND,
            OminousItemSpawnerEntity,
        };

        // Constants parity with Vanilla OminousItemSpawner.java
        assert_eq!(DEFAULT_MIN_SPAWN_TICKS, 60); // 3.0s minimum delay
        assert_eq!(DEFAULT_MAX_SPAWN_TICKS, 120); // 6.0s maximum delay
        assert_eq!(TICKS_BEFORE_ABOUT_TO_SPAWN_SOUND, 36); // 1.8s sound warning before spawn

        // Range validation
        assert!(OminousItemSpawnerEntity::is_delay_within_range(60));
        assert!(OminousItemSpawnerEntity::is_delay_within_range(90));
        assert!(OminousItemSpawnerEntity::is_delay_within_range(120));
        assert!(!OminousItemSpawnerEntity::is_delay_within_range(59));
        assert!(!OminousItemSpawnerEntity::is_delay_within_range(121));

        // Sound warning timing parity: tick == delay - 36
        // For delay = 100: warning at tick 64
        assert!(!OminousItemSpawnerEntity::should_play_warning_sound(63, 100));
        assert!(OminousItemSpawnerEntity::should_play_warning_sound(64, 100));
        assert!(!OminousItemSpawnerEntity::should_play_warning_sound(65, 100));

        // For min delay = 60: warning at tick 24
        assert!(OminousItemSpawnerEntity::should_play_warning_sound(24, 60));

        // For max delay = 120: warning at tick 84
        assert!(OminousItemSpawnerEntity::should_play_warning_sound(84, 120));

        // Spawn trigger parity: tick >= delay
        assert!(!OminousItemSpawnerEntity::should_spawn_item(99, 100));
        assert!(OminousItemSpawnerEntity::should_spawn_item(100, 100));
        assert!(OminousItemSpawnerEntity::should_spawn_item(101, 100));
    }
    #[test]
    fn test_trial_omen_mob_effects_wind_charged_weaving_oozing_infested_parity() {
        use crate::entity::combat::TrialOmenEffects;

        // 1. Wind Charged (WindChargedMobEffect.java:23: 3.0F + random * 2.0F)
        assert_eq!(TrialOmenEffects::WIND_CHARGED_MIN_GUST_STRENGTH, 3.0);
        assert_eq!(TrialOmenEffects::WIND_CHARGED_MAX_GUST_STRENGTH, 5.0);
        assert!((TrialOmenEffects::calculate_wind_charged_gust_strength(0.0) - 3.0).abs() < 1e-6);
        assert!((TrialOmenEffects::calculate_wind_charged_gust_strength(0.5) - 4.0).abs() < 1e-6);
        assert!((TrialOmenEffects::calculate_wind_charged_gust_strength(1.0) - 5.0).abs() < 1e-6);

        // 2. Weaving (WeavingMobEffect.java:27: player || mobGriefing)
        assert_eq!(TrialOmenEffects::WEAVING_MIN_COBWEBS, 2);
        assert_eq!(TrialOmenEffects::WEAVING_MAX_COBWEBS, 3);
        assert_eq!(TrialOmenEffects::WEAVING_MAX_SEARCH_ATTEMPTS, 15);
        assert_eq!(TrialOmenEffects::WEAVING_SEARCH_RADIUS, 1);
        assert_eq!(TrialOmenEffects::EVENT_COBWEB_PLACEMENT, 3018);

        assert!(TrialOmenEffects::can_weaving_spawn_cobwebs(true, false)); // player death always spawns
        assert!(TrialOmenEffects::can_weaving_spawn_cobwebs(false, true)); // mob death with mobGriefing
        assert!(!TrialOmenEffects::can_weaving_spawn_cobwebs(false, false)); // mob death without mobGriefing blocked

        // 3. Oozing (OozingMobEffect.java:30-32: numberOfSlimesToSpawn)
        assert_eq!(TrialOmenEffects::OOZING_SLIME_SIZE, 2); // medium slimes
        assert_eq!(TrialOmenEffects::OOZING_DEFAULT_SLIMES, 2);
        assert_eq!(TrialOmenEffects::OOZING_CHECK_RADIUS, 2.0);

        // No cramming limit (cramming < 1) -> all requested spawn
        assert_eq!(TrialOmenEffects::calculate_oozing_slimes_to_spawn(0, 50, 2), 2);
        assert_eq!(TrialOmenEffects::calculate_oozing_slimes_to_spawn(-1, 50, 2), 2);

        // Cramming limit active (e.g. 24 max cramming)
        // 10 nearby slimes -> 24 - 10 = 14 available -> spawns 2
        assert_eq!(TrialOmenEffects::calculate_oozing_slimes_to_spawn(24, 10, 2), 2);
        // 23 nearby slimes -> 24 - 23 = 1 available -> spawns 1
        assert_eq!(TrialOmenEffects::calculate_oozing_slimes_to_spawn(24, 23, 2), 1);
        // 24 nearby slimes -> 0 available -> spawns 0
        assert_eq!(TrialOmenEffects::calculate_oozing_slimes_to_spawn(24, 24, 2), 0);
        // 30 nearby slimes -> 0 available -> spawns 0
        assert_eq!(TrialOmenEffects::calculate_oozing_slimes_to_spawn(24, 30, 2), 0);

        // 4. Infested (InfestedMobEffect.java:21-29: 10% chance on hurt, 1..2 silverfish)
        assert_eq!(TrialOmenEffects::INFESTED_SPAWN_CHANCE, 0.10);
        assert_eq!(TrialOmenEffects::INFESTED_MIN_SILVERFISH, 1);
        assert_eq!(TrialOmenEffects::INFESTED_MAX_SILVERFISH, 2);

        assert!(TrialOmenEffects::should_infested_spawn_silverfish(0.05));
        assert!(TrialOmenEffects::should_infested_spawn_silverfish(0.10));
        assert!(!TrialOmenEffects::should_infested_spawn_silverfish(0.1001));
        assert!(!TrialOmenEffects::should_infested_spawn_silverfish(0.50));
    }
    #[test]
    fn test_crafter_trigger_events_comparator_and_advancement_parity() {
        use crate::block::blocks::redstone::crafter::CrafterBlock;

        // Constants parity with Vanilla CrafterBlock.java
        assert_eq!(CrafterBlock::CRAFTING_TICK_DELAY, 4);
        assert_eq!(CrafterBlock::MAX_CRAFTING_TICKS, 6);
        assert_eq!(CrafterBlock::CRAFTER_ADVANCEMENT_DIAMETER, 17.0);
        assert_eq!(CrafterBlock::CONTAINER_SIZE, 9);
        assert_eq!(CrafterBlock::CONTAINER_WIDTH, 3);
        assert_eq!(CrafterBlock::CONTAINER_HEIGHT, 3);
        assert_eq!(CrafterBlock::MIN_COMPARATOR_OUTPUT, 0);
        assert_eq!(CrafterBlock::MAX_COMPARATOR_OUTPUT, 9);
        assert_eq!(CrafterBlock::SOUND_CRAFTER_CRAFT_EVENT_ID, 1049);
        assert_eq!(CrafterBlock::SOUND_CRAFTER_FAIL_EVENT_ID, 1050);
        assert_eq!(CrafterBlock::PARTICLES_SHOOT_WHITE_SMOKE_EVENT_ID, 2010);

        // Redstone pulse evaluation (CrafterBlock.java:67-81)
        // Rising edge: powered = true, triggered = false -> sets triggered and schedules craft
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(true, false), (true, true));
        // Held powered: powered = true, triggered = true -> no new schedule
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(true, true), (true, false));
        // Falling edge: powered = false, triggered = true -> resets triggered
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(false, true), (false, false));
        // Held off: powered = false, triggered = false -> no change
        assert_eq!(CrafterBlock::evaluate_redstone_trigger(false, false), (false, false));

        // Comparator signal calculation: (occupied + disabled).min(9)
        assert_eq!(CrafterBlock::calculate_comparator_signal(0, 0), 0);
        assert_eq!(CrafterBlock::calculate_comparator_signal(3, 2), 5);
        assert_eq!(CrafterBlock::calculate_comparator_signal(5, 4), 9);
        assert_eq!(CrafterBlock::calculate_comparator_signal(9, 9), 9);

        // Bitmask slot disabled round-trip (CrafterBlockEntity.java: disabled_slots)
        let mut disabled = [false; 9];
        disabled[0] = true;
        disabled[2] = true;
        disabled[4] = true;
        let mask = CrafterBlock::disabled_slots_to_bitmask(&disabled);
        assert_eq!(mask, 1 | 4 | 16);
        assert_eq!(CrafterBlock::bitmask_to_disabled_slots(mask), disabled);

        let all_disabled = [true; 9];
        let full_mask = CrafterBlock::disabled_slots_to_bitmask(&all_disabled);
        assert_eq!(full_mask, 0x1FF); // 511
        assert_eq!(CrafterBlock::bitmask_to_disabled_slots(full_mask), all_disabled);

        // Slot craft validity: occupied && !disabled
        assert!(CrafterBlock::is_slot_valid_for_craft(true, false));
        assert!(!CrafterBlock::is_slot_valid_for_craft(false, false));
        assert!(!CrafterBlock::is_slot_valid_for_craft(true, true));
        assert!(!CrafterBlock::is_slot_valid_for_craft(false, true));

        // Advancement proximity (CrafterBlock.java:217: AABB 17x17x17 around center)
        assert!(CrafterBlock::is_player_within_advancement_range(0.0, 0.0, 0.0));
        assert!(CrafterBlock::is_player_within_advancement_range(8.5, 8.5, 8.5));
        assert!(CrafterBlock::is_player_within_advancement_range(-8.5, 8.5, -8.5));
        assert!(!CrafterBlock::is_player_within_advancement_range(8.51, 0.0, 0.0));
        assert!(!CrafterBlock::is_player_within_advancement_range(0.0, 8.51, 0.0));
        assert!(!CrafterBlock::is_player_within_advancement_range(0.0, 0.0, 8.51));
    }
