        assert_eq!(w4, 2.08);
        assert_eq!(h4, 2.08);
        assert_eq!(eye4, 1.3);

        // Phantom dimensions (Phantom.java:194-198, EntityTypes.java:765-766)
        assert_eq!(PHANTOM_BASE_WIDTH, 0.9);
        assert_eq!(PHANTOM_BASE_HEIGHT, 0.5);
        assert_eq!(PHANTOM_BASE_EYE_HEIGHT, 0.175);

        // Size 0 (default)
