        // Warden digging and emerging pose dimensions (Warden.java:519-521)
        let (wdw, wdh, wdeye) = get_entity_pose_dimensions(&EntityType::WARDEN, EntityPose::Digging);
        assert_eq!(wdw, 0.9);
