        assert_eq!(BeehiveBlock::HONEYCOMB_HARVEST_AMOUNT, 3);
        assert_eq!(BEE_ANGER_RANGE_HORIZONTAL, 8.0);
        assert_eq!(BEE_ANGER_RANGE_VERTICAL, 6.0);

