    #[test]
    fn test_piston_and_piston_head_parity_gap466() {
        use crate::block::blocks::piston::piston::{PistonBlock, PistonProps};
        use crate::block::blocks::piston::piston_head::{PistonHeadBlock, PistonHeadProperties};
        use pumpkin_data::block_properties::{Facing, PistonType};
        use pumpkin_data::block_state::PistonBehavior;
        use pumpkin_data::{Block, BlockDirection};

        // 1. Piston & Resolver Constants (PistonBaseBlock.java:45-48, PistonStructureResolver.java:13)
        assert_eq!(PistonBlock::MAX_PUSH_LIMIT, 12);
        assert_eq!(PistonBlock::TRIGGER_EXTEND, 0);
        assert_eq!(PistonBlock::TRIGGER_CONTRACT, 1);
        assert_eq!(PistonBlock::TRIGGER_DROP, 2);
        assert_eq!(PistonBlock::PLATFORM_THICKNESS, 4.0);
        assert_eq!(PistonHeadBlock::PLATFORM_THICKNESS, 4.0);

        // 2. Sticky & Attachment Logic Parity (PistonStructureResolver.java:64-74)
        assert!(PistonBlock::is_sticky_block(&Block::SLIME_BLOCK));
        assert!(PistonBlock::is_sticky_block(&Block::HONEY_BLOCK));
        assert!(!PistonBlock::is_sticky_block(&Block::STONE));
        assert!(!PistonBlock::is_sticky_block(&Block::DIRT));

        assert!(PistonBlock::can_stick_to_each_other(&Block::SLIME_BLOCK, &Block::SLIME_BLOCK));
        assert!(PistonBlock::can_stick_to_each_other(&Block::HONEY_BLOCK, &Block::HONEY_BLOCK));
        assert!(!PistonBlock::can_stick_to_each_other(&Block::SLIME_BLOCK, &Block::HONEY_BLOCK));
        assert!(!PistonBlock::can_stick_to_each_other(&Block::HONEY_BLOCK, &Block::SLIME_BLOCK));
        assert!(PistonBlock::can_stick_to_each_other(&Block::SLIME_BLOCK, &Block::STONE));
        assert!(PistonBlock::can_stick_to_each_other(&Block::STONE, &Block::SLIME_BLOCK));
        assert!(PistonBlock::can_stick_to_each_other(&Block::HONEY_BLOCK, &Block::STONE));
        assert!(PistonBlock::can_stick_to_each_other(&Block::STONE, &Block::HONEY_BLOCK));
        assert!(!PistonBlock::can_stick_to_each_other(&Block::STONE, &Block::DIRT));

        // 3. Immovable Block Types Parity (Blocks.java pushReaction(IMMOVEABLE))
        assert!(!PistonBlock::is_pushable_block_type(&Block::OBSIDIAN));
        assert!(!PistonBlock::is_pushable_block_type(&Block::CRYING_OBSIDIAN));
        assert!(!PistonBlock::is_pushable_block_type(&Block::RESPAWN_ANCHOR));
        assert!(!PistonBlock::is_pushable_block_type(&Block::REINFORCED_DEEPSLATE));
        assert!(!PistonBlock::is_pushable_block_type(&Block::PISTON_HEAD));
        assert!(PistonBlock::is_pushable_block_type(&Block::STONE));
        assert!(PistonBlock::is_pushable_block_type(&Block::DIRT));
        assert!(PistonBlock::is_pushable_block_type(&Block::IRON_BLOCK));

        // 4. Push Behavior Evaluation Parity (PistonBaseBlock.java:242-250)
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Destroy, true, BlockDirection::East, BlockDirection::East),
            Some(true)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Destroy, false, BlockDirection::East, BlockDirection::East),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Block, true, BlockDirection::East, BlockDirection::East),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::PushOnly, false, BlockDirection::East, BlockDirection::East),
            Some(true)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::PushOnly, false, BlockDirection::West, BlockDirection::East),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Ignore, false, BlockDirection::East, BlockDirection::East),
            Some(false)
        );
        assert_eq!(
            PistonBlock::evaluate_piston_behavior(PistonBehavior::Normal, false, BlockDirection::East, BlockDirection::East),
            None
        );

        // 5. Piston Head Base Fitting Parity (PistonHeadBlock.java:57-60)
        let mut head_props = PistonHeadProperties::default(&Block::PISTON_HEAD);
        head_props.facing = Facing::East;
        head_props.r#type = PistonType::Normal;

        let mut base_props = PistonProps::default(&Block::PISTON);
        base_props.facing = Facing::East;
        base_props.extended = true;
        let base_state_id = base_props.to_state_id(&Block::PISTON);

        assert!(PistonHeadBlock::is_fitting_base(head_props, &Block::PISTON, base_state_id));

        // Non-extended base: should NOT fit
        base_props.extended = false;
        let unextended_state_id = base_props.to_state_id(&Block::PISTON);
        assert!(!PistonHeadBlock::is_fitting_base(head_props, &Block::PISTON, unextended_state_id));

        // Mismatched facing: should NOT fit
        base_props.extended = true;
        base_props.facing = Facing::West;
        let wrong_facing_state_id = base_props.to_state_id(&Block::PISTON);
        assert!(!PistonHeadBlock::is_fitting_base(head_props, &Block::PISTON, wrong_facing_state_id));

        // Normal head on sticky piston: should NOT fit
        base_props.facing = Facing::East;
        let sticky_state_id = base_props.to_state_id(&Block::STICKY_PISTON);
        assert!(!PistonHeadBlock::is_fitting_base(head_props, &Block::STICKY_PISTON, sticky_state_id));

        // Sticky head on sticky piston: should fit!
        head_props.r#type = PistonType::Sticky;
        assert!(PistonHeadBlock::is_fitting_base(head_props, &Block::STICKY_PISTON, sticky_state_id));
    }

    #[test]
    fn test_repeater_comparator_and_redstone_wire_parity_gap467() {
        use crate::block::blocks::redstone::comparator::ComparatorBlock;
        use crate::block::blocks::redstone::redstone_wire::RedstoneWireBlock;
        use crate::block::blocks::redstone::repeater::RepeaterBlock;
        use pumpkin_data::block_properties::HorizontalFacing;
        use pumpkin_data::{BlockDirection, BlockId};

        // 1. Repeater Constants & Delay Calculation (RepeaterBlock.java:24-30, 47-49)
        assert_eq!(RepeaterBlock::MIN_DELAY, 1);
        assert_eq!(RepeaterBlock::MAX_DELAY, 4);
        assert_eq!(RepeaterBlock::DELAY_MULTIPLIER, 2);
        assert_eq!(RepeaterBlock::DEFAULT_DELAY, 1);
        assert_eq!(RepeaterBlock::DEFAULT_LOCKED, false);
        assert_eq!(RepeaterBlock::DEFAULT_POWERED, false);
        assert_eq!(RepeaterBlock::POWER_ON, 15);
        assert_eq!(RepeaterBlock::POWER_OFF, 0);

        assert_eq!(RepeaterBlock::calculate_delay_ticks(1), 2);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(2), 4);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(3), 6);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(4), 8);
        assert_eq!(RepeaterBlock::calculate_delay_ticks(0), 2); // clamped
        assert_eq!(RepeaterBlock::calculate_delay_ticks(5), 8); // clamped

        assert_eq!(RepeaterBlock::cycle_delay(1), 2);
        assert_eq!(RepeaterBlock::cycle_delay(2), 3);
        assert_eq!(RepeaterBlock::cycle_delay(3), 4);
        assert_eq!(RepeaterBlock::cycle_delay(4), 1);

        assert_eq!(RepeaterBlock::get_output_power(true), 15);
        assert_eq!(RepeaterBlock::get_output_power(false), 0);

        // Repeater lock source verification (sideInputDiodesOnly = true)
        assert!(RepeaterBlock::can_be_locked_by_block(BlockId::REPEATER));
        assert!(RepeaterBlock::can_be_locked_by_block(BlockId::COMPARATOR));
        assert!(!RepeaterBlock::can_be_locked_by_block(BlockId::STONE));
        assert!(!RepeaterBlock::can_be_locked_by_block(BlockId::REDSTONE_WIRE));

        assert!(RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::East));
        assert!(RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::West));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::South));
        assert!(!RepeaterBlock::is_locking_side(HorizontalFacing::North, BlockDirection::North));

        // 2. Comparator Constants & Mode Calculations (ComparatorBlock.java:30-41, 64-87)
        assert_eq!(ComparatorBlock::DELAY, 2);
        assert_eq!(ComparatorBlock::CLICK_VOLUME, 0.3);
        assert_eq!(ComparatorBlock::CLICK_PITCH_COMPARE, 0.5);
        assert_eq!(ComparatorBlock::CLICK_PITCH_SUBTRACT, 0.55);
        assert_eq!(ComparatorBlock::POWER_ON, 15);
        assert_eq!(ComparatorBlock::POWER_OFF, 0);
        assert_eq!(ComparatorBlock::DEFAULT_OUTPUT, 0);

        // Compare mode signal calculation
        assert_eq!(ComparatorBlock::calculate_comparator_signal(15, 10, false), 15);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(15, 15, false), 15);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 15, false), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(0, 0, false), 0);

        // Subtract mode signal calculation
        assert_eq!(ComparatorBlock::calculate_comparator_signal(15, 10, true), 5);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(15, 15, true), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(10, 15, true), 0);
        assert_eq!(ComparatorBlock::calculate_comparator_signal(0, 5, true), 0);

        // Turn on condition parity
        assert!(ComparatorBlock::should_turn_on(15, 10, false));
        assert!(ComparatorBlock::should_turn_on(15, 15, false));
        assert!(!ComparatorBlock::should_turn_on(10, 15, false));
        assert!(!ComparatorBlock::should_turn_on(0, 0, false));

        assert!(ComparatorBlock::should_turn_on(15, 10, true));
        assert!(!ComparatorBlock::should_turn_on(15, 15, true));
        assert!(!ComparatorBlock::should_turn_on(10, 15, true));
        assert!(!ComparatorBlock::should_turn_on(0, 5, true));

        // Item frame output parity (1 + rotation % 8, or 0 if empty)
        assert_eq!(ComparatorBlock::calculate_item_frame_output(false, 0), 0);
        assert_eq!(ComparatorBlock::calculate_item_frame_output(true, 0), 1);
        assert_eq!(ComparatorBlock::calculate_item_frame_output(true, 1), 2);
        assert_eq!(ComparatorBlock::calculate_item_frame_output(true, 7), 8);
        assert_eq!(ComparatorBlock::calculate_item_frame_output(true, 8), 1);

        // 3. Redstone Wire Constants & Dropoff Calculation (RedStoneWireBlock.java)
        assert_eq!(RedstoneWireBlock::MIN_POWER, 0);
        assert_eq!(RedstoneWireBlock::MAX_POWER, 15);
        assert_eq!(RedstoneWireBlock::calculate_wire_dropoff(15), 14);
        assert_eq!(RedstoneWireBlock::calculate_wire_dropoff(1), 0);
        assert_eq!(RedstoneWireBlock::calculate_wire_dropoff(0), 0);

        assert_eq!(RedstoneWireBlock::calculate_target_strength(15, 10), 15);
        assert_eq!(RedstoneWireBlock::calculate_target_strength(0, 15), 14);
        assert_eq!(RedstoneWireBlock::calculate_target_strength(5, 8), 7);
        assert_eq!(RedstoneWireBlock::calculate_target_strength(8, 5), 8);
    }

    #[test]
    fn test_observer_target_and_lightning_rod_parity_gap468() {
        use crate::block::blocks::redstone::lightning_rod::LightningRodBlock;
        use crate::block::blocks::redstone::observer::ObserverBlock;
        use crate::block::blocks::redstone::target_block::TargetBlock;
        use pumpkin_data::block_properties::{Axis, Facing};
        use pumpkin_data::entity::EntityType;
        use pumpkin_data::BlockDirection;
        use pumpkin_util::math::position::BlockPos;

        // 1. Observer Constants & Directions (ObserverBlock.java:21-27, 45-54)
        assert_eq!(ObserverBlock::PULSE_DURATION, 2);
        assert_eq!(ObserverBlock::DETECTION_DELAY, 2);
        assert_eq!(ObserverBlock::POWER_ON, 15);
        assert_eq!(ObserverBlock::POWER_OFF, 0);
        assert_eq!(ObserverBlock::DEFAULT_POWERED, false);
        assert_eq!(ObserverBlock::DEFAULT_FACING, Facing::South);

        assert_eq!(ObserverBlock::get_power_signal(true), 15);
        assert_eq!(ObserverBlock::get_power_signal(false), 0);
        assert_eq!(
            ObserverBlock::get_observed_direction(BlockDirection::North),
            BlockDirection::North
        );
        assert_eq!(
            ObserverBlock::get_output_direction(BlockDirection::North),
            BlockDirection::South
        );
        assert!(ObserverBlock::emits_power_in_direction(
            BlockDirection::North,
            BlockDirection::North
        ));
        assert!(!ObserverBlock::emits_power_in_direction(
            BlockDirection::North,
            BlockDirection::South
        ));

        // 2. Target Block Constants & Formula Parity (TargetBlock.java:26-28, 44-70)
        assert_eq!(TargetBlock::ACTIVATION_TICKS_ARROWS, 20);
        assert_eq!(TargetBlock::ACTIVATION_TICKS_OTHER, 8);
        assert_eq!(TargetBlock::MIN_POWER, 1);
        assert_eq!(TargetBlock::MAX_POWER, 15);
        assert_eq!(TargetBlock::DEFAULT_POWER, 0);
        assert_eq!(TargetBlock::BULLSEYE_MIN_DISTANCE, 30.0);
        assert!(!TargetBlock::emits_strong_power());

        assert!(TargetBlock::is_arrow_projectile(&EntityType::ARROW));
        assert!(TargetBlock::is_arrow_projectile(&EntityType::SPECTRAL_ARROW));
        assert!(TargetBlock::is_arrow_projectile(&EntityType::TRIDENT));
        assert!(!TargetBlock::is_arrow_projectile(&EntityType::SNOWBALL));
        assert!(!TargetBlock::is_arrow_projectile(&EntityType::EGG));

        assert_eq!(
            TargetBlock::get_activation_ticks(&EntityType::ARROW),
            20
        );
        assert_eq!(
            TargetBlock::get_activation_ticks(&EntityType::SNOWBALL),
            8
        );

        // Bullseye hit (distance = 0.0) -> power 15
        assert_eq!(TargetBlock::calculate_power_from_distance(0.0), 15);
        // Outer boundary hit (distance = 0.5) -> power 1
        assert_eq!(TargetBlock::calculate_power_from_distance(0.5), 1);
        // Mid-ring hit (distance = 0.25) -> power 8
        assert_eq!(TargetBlock::calculate_power_from_distance(0.25), 8);
        // Out of bounds hit (clamped to min 1)
        assert_eq!(TargetBlock::calculate_power_from_distance(1.0), 1);

        // Power on axis calculation
        assert_eq!(
            TargetBlock::calculate_hit_power_on_axis(0.0, 0.0, 0.0, Axis::Y),
            15
        );
        assert_eq!(
            TargetBlock::calculate_hit_power_on_axis(0.5, 0.0, 0.0, Axis::Y),
            1
        );

        assert_eq!(TargetBlock::calculate_comparator_signal(15), 15);
        assert_eq!(TargetBlock::calculate_comparator_signal(0), 0);

        // 3. Lightning Rod Constants & Power Direction Parity (LightningRodBlock.java:26-30, 68-75)
        assert_eq!(LightningRodBlock::ACTIVATION_TICKS, 8);
        assert_eq!(LightningRodBlock::RANGE, 128);
        assert_eq!(LightningRodBlock::EVENT_LIGHTNING_STRIKE, 3002);
        assert_eq!(LightningRodBlock::SPARK_CYCLE, 200);
        assert_eq!(LightningRodBlock::POWER_ON, 15);
        assert_eq!(LightningRodBlock::POWER_OFF, 0);
        assert_eq!(LightningRodBlock::DEFAULT_FACING, Facing::Up);
        assert_eq!(LightningRodBlock::DEFAULT_POWERED, false);
        assert_eq!(LightningRodBlock::DEFAULT_WATERLOGGED, false);

        assert_eq!(LightningRodBlock::get_weak_power(true), 15);
        assert_eq!(LightningRodBlock::get_weak_power(false), 0);

        // Emits strong power ONLY in facing direction
        assert_eq!(
            LightningRodBlock::get_strong_power(true, Facing::Up, BlockDirection::Up),
            15
        );
        assert_eq!(
            LightningRodBlock::get_strong_power(true, Facing::Up, BlockDirection::Down),
            0
        );
        assert_eq!(
            LightningRodBlock::get_strong_power(false, Facing::Up, BlockDirection::Up),
            0
        );

        let rod_pos = BlockPos::new(10, 64, 10);
        assert_eq!(
            LightningRodBlock::get_attached_position(&rod_pos, Facing::Up),
            rod_pos.down()
        );
        assert_eq!(
            LightningRodBlock::get_attached_position(&rod_pos, Facing::Down),
            rod_pos.up()
        );

        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::East), 0);
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::Up), 1);
        assert_eq!(LightningRodBlock::get_axis_ordinal(Facing::South), 2);
    }

