        assert_eq!(SculkSensorBlock::ACTIVE_TICKS_CALIBRATED, 10);
        assert_eq!(SculkSensorBlock::COOLDOWN_TICKS, 10);
        assert_eq!(SculkSensorBlock::LISTENER_RANGE_REGULAR, 8);
